SET @sql = IF(@col_exists = 0, 'ALTER TABLE homepage_section ADD COLUMN cover_url VARCHAR(500) DEFAULT NULL COMMENT ''封面图'' AFTER content', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

