-- 文章数据导入(仅在数据不存在时插入,用 LEFT JOIN 防重复)
-- ============================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

-- 给 homepage_section 添加 cover_url 字段(如果不存在)
SET @col_exists = (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'homepage_section' AND COLUMN_NAME = 'cover_url');
SET @sql = IF(@col_exists = 0, 'ALTER TABLE homepage_section ADD COLUMN cover_url VARCHAR(500) DEFAULT NULL COMMENT ''封面图'' AFTER content', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 给 news 添加 source 字段(如果不存在)
SET @col_exists = (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'news' AND COLUMN_NAME = 'source');
SET @sql = IF(@col_exists = 0, 'ALTER TABLE news ADD COLUMN source VARCHAR(200) DEFAULT NULL COMMENT ''来源'' AFTER content', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 给 news 添加 summary 字段(如果不存在)
SET @col_exists = (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'news' AND COLUMN_NAME = 'summary');
SET @sql = IF(@col_exists = 0, 'ALTER TABLE news ADD COLUMN summary VARCHAR(500) DEFAULT NULL COMMENT ''摘要'' AFTER source', 'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 通知公告 -> announcement (16 rows)
INSERT INTO `announcement` (`title`, `content`, `status`, `sort`, `create_time`, `update_time`) VALUES ('关于：真假网站  声明通知！！！！！', '<p style="text-align: left;"><span style="text-wrap-mode: nowrap; font-size: 20px;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <strong>严重声明</strong></span></p><p style="text-align: left;"><span style="text-wrap-mode: nowrap; font-size: 20px;"><br/></span></p><p style="text-align: left;"><span style="text-wrap-mode: nowrap; font-size: 20px;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;近日我中心接到群众来电，核实该网址域名<span style="text-wrap-mode: nowrap; font-size: 20px; color: #FF0000;">“http://www.rpzx.org/”</span>是不是我中心最新网址。</span></p><p style="text-align: left;"><span style="font-size: 20px; text-wrap-mode: nowrap;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <strong>&nbsp;现我中心郑重声明如下：</strong></span></p><p style="text-align: left;"><span style="text-wrap-mode: nowrap; font-size: 20px;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 一、我中心从未更换新网址域名，该网站域名与我中心没有任何关系。</span></p><p style="text-align: left;"><span style="text-wrap-mode: nowrap; font-size: 20px;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 二、认准本中心<strong>唯一</strong><strong>官方网址域名</strong>“https://www.zgrlosta.org.cn/”</span></p><p style="text-align: left;"><span style="text-wrap-mode: nowrap; font-size: 20px;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 三、该活动系不法分子盗用我中心名义开展的违法活动；</span></p><p style="text-align: left;"><span style="text-wrap-mode: nowrap; font-size: 20px;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 四、该违法行为已严重侵害我中心名誉，我中心保留依法追究当事方责任的权利。</span></p><p style="text-align: left;"><span style="text-wrap-mode: nowrap; font-size: 20px;"><br/></span></p><p style="text-align: left;"><span style="text-wrap-mode: nowrap; font-size: 20px;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style="text-wrap-mode: nowrap; font-size: 20px; color: #FF0000;">&nbsp;请广大群众提高警惕，谨防上当受骗。</span></span></p><p style="text-align: left;"><span style="text-wrap-mode: nowrap; font-size: 20px;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span></p><p style="text-align: left;"><span style="text-wrap-mode: nowrap; font-size: 20px;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;中国人力资源专业技能人才评价中心</span></p><p style="text-align: left;"><span style="text-wrap-mode: nowrap; font-size: 20px;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 2026年04月28日</span></p><p><span style="text-wrap-mode: nowrap; font-size: 20px;"><img src="/static/upload/image/20260428/1777342113157510.png" alt="12.png"/></span></p><p style="text-align: right;"><br/></p>', 1, 255, '2026-04-28 10:09:59', '2026-04-28 10:18:00');
