INSERT INTO `announcement` (`title`, `content`, `status`, `sort`, `create_time`, `update_time`) VALUES ('春节放假通知', '<p style="text-align: center;"><span style="text-wrap-mode: nowrap;">春节放假通知</span></p><p style="text-align: center;"><span style="text-wrap-mode: nowrap;"><br/></span></p><p style="text-align: center;"><span style="text-wrap-mode: nowrap;">各部门、全体员工及合作单位：</span></p><p style="text-align: center;"><span style="text-wrap-mode: nowrap;"><br/></span></p><p style="text-align: center;"><span style="text-wrap-mode: nowrap;">根据国家法定节假日安排及本中心实际工作情况，现将2026年春节放假事宜通知如下：</span></p><p style="text-align: center;"><span style="text-wrap-mode: nowrap;"><br/></span></p><p style="text-align: center;"><span style="text-wrap-mode: nowrap;">放假时间</span></p><p style="text-align: center;"><span style="text-wrap-mode: nowrap;">2026年2月9日至2月23日放假调休，共计14天；</span></p><p style="text-align: center;"><span style="text-wrap-mode: nowrap;">2月24日（正月初八） 正常返岗上班。</span></p><p style="text-align: center;"><img src="/static/upload/image/20260204/1770206950980415.png" alt="687127ba7c19cf473e4a5ec044aebe5e.png"/></p>', 1, 255, '2026-02-04 20:10:11', '2026-02-04 20:10:11');
INSERT INTO `announcement` (`title`, `content`, `status`, `sort`, `create_time`, `update_time`) VALUES ('关于启用微信公众号的通知', '<p style="margin: 0px; padding: 0px; color: rgb(25, 85, 148); font-weight: 700; font-size: 28px; text-align: center; font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap;">关于启用微信公众号的通知</p><p style="margin: 0px; padding: 0px; color: rgb(25, 85, 148); font-weight: 700; font-size: 28px; font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; text-align: center;"><span style="font-size: 14px;">Notice on the Launch of the WeChat Official Account</span></p><div data-v-537c989c="" class="content" style="margin: 30px 50px; padding: 0px; line-height: 30px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap;"><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px;">各合作机构：</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px;">根据各合作机构需要，中国人力资源专业技能人才评价中心正式启用微信公众号“国培人力资源职业技能测评中心”。我们将通过微信公众号发布新闻、修业证书查询等资讯。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px;">请大家关注微信公众号“ <span style="color: #2C3E50; font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap;">国培人力资源职业技能测评中心</span>&nbsp; ”。</p></div><div style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-family: ui-sans-serif, system-ui, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px; line-height: 24px; text-wrap-mode: wrap; flex: 0 1 auto; flex-direction: row; justify-content: normal; align-items: normal; padding: 0px; margin: 0px; background-image: none; background-position: 0% 0%; background-size: auto; background-repeat: repeat; background-attachment: scroll; background-origin: padding-box; background-clip: border-box; text-align: left;">&nbsp; &nbsp; &nbsp;To All Partner Institutions:</div><p style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-family: ui-sans-serif, system-ui, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px; line-height: 24px; text-wrap-mode: wrap; flex: 0 1 auto; flex-direction: row; justify-content: normal; align-items: normal; padding: 0px; margin: 0px; background-image: none; background-position: 0% 0%; background-size: auto; background-repeat: repeat; background-attachment: scroll; background-origin: padding-box; background-clip: border-box; text-align: left;">&nbsp; &nbsp; &nbsp; In response to the needs of each partner institution, the China Human Resources Professional Skills Talent Evaluation Center has officially launched&nbsp; &nbsp; &nbsp; &nbsp; its WeChat Official Account named <span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-weight: 700; line-height: 24px; flex: 0 1 auto; flex-direction: row; justify-content: normal; align-items: normal; padding: 0px; margin: 0px; background-image: none; background-position: 0% 0%; background-size: auto; background-repeat: repeat; background-attachment: scroll; background-origin: padding-box; background-clip: border-box;">National Training Center for Human Resources Vocational Skills Assessment</span>. We will release information&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; such as news and training certificate inquiries through this WeChat Official Account.</p><p style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-family: ui-sans-serif, system-ui, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px; line-height: 24px; text-wrap-mode: wrap; flex: 0 1 auto; flex-direction: row; justify-content: normal; align-items: normal; padding: 0px; margin: 0px; background-image: none; background-position: 0% 0%; background-size: auto; background-repeat: repeat; background-attachment: scroll; background-origin: padding-box; background-clip: border-box; text-align: left;"><br/></p><div style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-family: ui-sans-serif, system-ui, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px; line-height: 24px; text-wrap-mode: wrap; flex: 0 1 auto; flex-direction: row; justify-content: normal; align-items: normal; padding: 0px; margin: 0px; background-image: none; background-position: 0% 0%; background-size: auto; background-repeat: repeat; background-attachment: scroll; background-origin: padding-box; background-clip: border-box; text-align: left;">&nbsp; &nbsp; &nbsp; Please follow the WeChat Official Account: <span style="font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-size-adjust: none; font-language-override: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-variant-emoji: normal; font-stretch: normal; font-weight: 700; line-height: 24px; flex: 0 1 auto; flex-direction: row; justify-content: normal; align-items: normal; padding: 0px; margin: 0px; background-image: none; background-position: 0% 0%; background-size: auto; background-repeat: repeat; background-attachment: scroll; background-origin: padding-box; background-clip: border-box;">National Training Center for Human Resources Vocational Skills Assessment</span>.</div><p><br/></p>', 1, 255, '2026-01-21 13:31:15', '2026-01-21 14:09:06');
