INSERT INTO `announcement` (`title`, `content`, `status`, `sort`, `create_time`, `update_time`) VALUES ('声明', '<p style="margin-top: 21px; margin-bottom: 21px; text-wrap-mode: wrap; box-sizing: border-box; padding: 15px 0px; outline: 0px; border: 0px; background: rgb(255, 255, 255); vertical-align: baseline; font-size: 18px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, sans-serif; text-align: center; line-height: 27px;"><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 29px; font-family: 方正小标宋_GBK; line-height: 44px;"><span style="box-sizing: border-box;">声</span>&nbsp;&nbsp;<span style="box-sizing: border-box;">明</span></span><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 29px; font-family: 方正小标宋_GBK; line-height: 44px;"><o style="box-sizing: border-box;"></o></span></p><p style="margin-top: 0px; margin-bottom: 0px; text-wrap-mode: wrap; box-sizing: border-box; padding: 15px 0px; outline: 0px; border: 0px; background: rgb(255, 255, 255); vertical-align: baseline; font-size: 18px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, sans-serif; text-indent: 43px;"><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;"><span style="box-sizing: border-box;">近日我中心接到群众来电，核实我中心是否与</span><span style="box-sizing: border-box;">“中国人力资源测评中心”联合开展培训发证活动的有关情况（<span style="background: transparent; vertical-align: baseline; color: #FF0000;">详见附图</span>）。现我中心郑重声明如下：</span></span><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;"><o style="box-sizing: border-box;"></o></span></p><p style="margin-top: 0px; margin-bottom: 0px; text-wrap-mode: wrap; box-sizing: border-box; padding: 15px 0px; outline: 0px; border: 0px; background: rgb(255, 255, 255); vertical-align: baseline; font-size: 18px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, sans-serif; text-indent: 43px;"><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;">一、</span><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;"><span style="box-sizing: border-box;">我中心从未与所谓的</span><span style="box-sizing: border-box;">“中国人力资源测评中心”联合开展过任何活动；</span></span><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;"><o style="box-sizing: border-box;"></o></span></p><p style="margin-top: 0px; margin-bottom: 0px; text-wrap-mode: wrap; box-sizing: border-box; padding: 15px 0px; outline: 0px; border: 0px; background: rgb(255, 255, 255); vertical-align: baseline; font-size: 18px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, sans-serif; text-indent: 43px;"><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;">二、</span><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;">该活动系不法分子盗用我中心名义开展的违法活动；</span><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;"><o style="box-sizing: border-box;"></o></span></p><p style="margin-top: 0px; margin-bottom: 0px; text-wrap-mode: wrap; box-sizing: border-box; padding: 15px 0px; outline: 0px; border: 0px; background: rgb(255, 255, 255); vertical-align: baseline; font-size: 18px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, sans-serif; text-indent: 43px;"><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;">三、</span><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;">该违法行为已严重侵害我中心名誉，我中心保留依法追究当事方责任的权利。</span></p><p style="margin-top: 0px; margin-bottom: 0px; text-wrap-mode: wrap; box-sizing: border-box; padding: 15px 0px; outline: 0px; border: 0px; background: rgb(255, 255, 255); vertical-align: baseline; font-size: 18px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, sans-serif; text-indent: 43px;"><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;">请广大群众提高警惕，谨防上当受骗。</span><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;"><o style="box-sizing: border-box;"></o></span></p><p style="margin-top: 0px; margin-bottom: 0px; text-wrap-mode: wrap; box-sizing: border-box; padding: 15px 0px; outline: 0px; border: 0px; background: rgb(255, 255, 255); vertical-align: baseline; font-size: 18px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, sans-serif;"><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;">&nbsp;</span></p><p style="margin-top: 0px; margin-bottom: 0px; margin-left: 154px; text-wrap-mode: wrap; box-sizing: border-box; padding: 15px 0px; outline: 0px; border: 0px; background: rgb(255, 255, 255); vertical-align: baseline; font-size: 18px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, sans-serif; text-align: center;"><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;">中国人力资源专业技能人才评价中心</span></p><p style="margin-top: 0px; margin-bottom: 0px; margin-left: 154px; text-wrap-mode: wrap; box-sizing: border-box; padding: 15px 0px; outline: 0px; border: 0px; background: rgb(255, 255, 255); vertical-align: baseline; font-size: 18px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, sans-serif; text-align: center;"><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;">2025年10月</span><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;">13</span><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;">日</span></p><p style="margin-top: 0px; margin-bottom: 0px; margin-left: 154px; text-wrap-mode: wrap; box-sizing: border-box; padding: 15px 0px; outline: 0px; border: 0px; background: rgb(255, 255, 255); vertical-align: baseline;"><span style="color: #333333; font-family: 仿宋;"><span style="font-size: 21px;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span></span><span style="color: #FF0000; font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, sans-serif; font-size: 18px;">该证书不是我中心颁发</span></p><p style="text-wrap-mode: wrap; text-align: center;">（全国一手）中国人力资源测评中心</p><p style="text-wrap-mode: wrap; text-align: center;">中国人力资源专业技能人才评价中心</p><p style="text-wrap-mode: wrap;"><br/></p><p style="text-wrap-mode: wrap; text-align: center;">当天出，全工种，时间可以提前。</p><p style="text-wrap-mode: wrap; text-align: center;">https://www.zlzypczx.org.cn/</p><p style="text-wrap-mode: wrap; text-align: center;">价格低，有单速报</p><p style="margin-top: 0px; margin-bottom: 0px; margin-left: 154px; text-wrap-mode: wrap; box-sizing: border-box; padding: 15px 0px; outline: 0px; border: 0px; background: rgb(255, 255, 255); vertical-align: baseline; font-size: 18px; color: rgb(51, 51, 51); font-family: &quot;Microsoft Yahei&quot;, Helvetica, Arial, sans-serif; text-align: center;"><span style="box-sizing: border-box; padding: 0px; outline: 0px; border: 0px; background: transparent; vertical-align: baseline; font-size: 21px; font-family: 仿宋;"><img src="https://www.zgrlosta.org.cn/static/upload/image/20251016/1760606176119819.jpg" alt="9c6c5826549956985695000668f190e6.jpg"/></span></p>', 1, 255, '2025-10-16 17:31:38', '2025-10-16 17:32:28');
