x-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; color: rgb(102, 102, 102); font-family: &quot;Microsoft Yahei&quot;, Arial, Helvetica, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><span style="-webkit-tap-highlight-color: ; margin: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: #E5E7EB; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; font-family: 微软雅黑;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 在营造成长环境方面，政府、企业、院校、社会需协同合作，打造有利于技能人才发展的 “软环境”。适当增加各年龄段学生劳动教育占比，让学生在劳动实践中成长，从小树立技能成才、技能报国的志向，逐步改变社会对技能人才的认知偏差。大力弘扬 “精益求精的工匠精神”，广泛宣传高技能人才先进事迹，提升其社会形象。持续举办高水平职业技能竞赛、技能人才创新大赛，加大对高技能人才在各类表彰中的倾斜力度，增强其职业荣誉感与归属感。</span></div>', NULL, 5, 1, 255, '2025-07-17 22:13:17', '2025-07-17 22:13:17');
INSERT INTO `homepage_section` (`title`, `content`, `cover_url`, `type`, `status`, `sort`, `create_time`, `update_time`) VALUES ('补贴扩容：职业技能证补贴范围再拓宽', '<p style="-webkit-tap-highlight-color: rgba(255, 255, 255, 0);box-sizing: border-box;border-width: 0px;border-style: solid;border-color: rgb(229, 231, 235);--tw-translate-x: 0;--tw-translate-y: 0;--tw-rotate: 0;--tw-skew-x: 0;--tw-skew-y: 0;--tw-scale-x: 1;--tw-scale-y: 1;--tw-pan-x: ;--tw-pan-y: ;--tw-pinch-zoom: ;--tw-scroll-snap-strictness: proximity;--tw-ordinal: ;--tw-slashed-zero: ;--tw-numeric-figure: ;--tw-numeric-spacing: ;--tw-numeric-fraction: ;--tw-ring-inset: ;--tw-ring-offset-width: 0px;--tw-ring-offset-color: #fff;--tw-ring-color: rgb(59 130 246 / 0.5);--tw-ring-offset-shadow: 0 0 #0000;--tw-ring-shadow: 0 0 #0000;--tw-shadow: 0 0 #0000;--tw-shadow-colored: 0 0 #0000;--tw-blur: ;--tw-brightness: ;--tw-contrast: ;--tw-grayscale: ;--tw-hue-rotate: ;--tw-invert: ;--tw-saturate: ;--tw-sepia: ;--tw-drop-shadow: ;--tw-backdrop-blur: ;--tw-backdrop-brightness: ;--tw-backdrop-contrast: ;--tw-backdrop-grayscale: ;--tw-backdrop-hue-rotate: ;--tw-backdrop-invert: ;--tw-backdrop-opacity: ;--tw-backdrop-saturate: ;--tw-backdrop-sepia: ;padding: 0px;text-align: justify;font-family: Calibri;font-size: 14px"><spanyes&#x27;;font-family:calibri;mso-fareast-font-family:宋体; mso-bidi-font-family:="">为激励更多劳动者提升职业技能，政府再度扩大职业技能证补贴范围。最新政策显示，除传统热门职业技能证外，部分新兴职业与社会急需职业技能证也被纳入补贴范畴。新兴职业如物联网安装调试员、工业机器人系统操作员等，其职业技能证持有者符合条件即可申请补贴。以物联网安装调试员为例，只要在规定时间内取得证书，且在当地就业并缴纳社保达一定期限，就能领取对应补贴，补贴金额依证书等级而定。<spanyes&#x27;;font-family:calibri;mso-fareast-font-family:宋体; mso-bidi-font-family:=""></spanyes&#x27;;font-family:calibri;mso-fareast-font-family:宋体;></spanyes&#x27;;font-family:calibri;mso-fareast-font-family:宋体;></p><p style="-webkit-tap-highlight-color: rgba(255, 255, 255, 0);box-sizing: border-box;border-width: 0px;border-style: solid;border-color: rgb(229, 231, 235);--tw-translate-x: 0;--tw-translate-y: 0;--tw-rotate: 0;--tw-skew-x: 0;--tw-s