INSERT INTO `homepage_section` (`title`, `content`, `cover_url`, `type`, `status`, `sort`, `create_time`, `update_time`) VALUES ('教育部办公厅关于公布2025年度第一批 实施专科教育高等学校备案名单的函', '<p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">有关省、直辖市人民政府办公厅：</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　根据《中华人民共和国高等教育法》《普通高等学校设置暂行条例》等有关法律法规和政策文件的规定，现将省级人民政府审批设置的专科层次高等学校备案名单予以公布。</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　专此函告。</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;">　　附件：<span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #0000FF;">省级人民政府审批设置实施专科教育高等学校备案名单</span></span></span></span></span></span></span></span></span></span></span></span></span></p>', NULL, 6, 1, 255, '2025-07-17 23:00:02', '2025-07-17 23:00:02');
INSERT INTO `homepage_section` (`title`, `content`, `cover_url`, `type`, `status`, `sort`, `create_time`, `update_time`) VALUES ('教育部办公厅　国家卫生健康委办公厅关于 加强高等职业教育医养照护与管理 专业建设工作的通知', '<p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">教职成厅〔2025〕1号</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">各省、自治区、直辖市教育厅（教委）、卫生健康委，新疆生产建设兵团教育局、卫生健康委：</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　为深入贯彻党的二十届三中全会和全国教育大会精神，落实《教育强国建设规划纲要（2024—2035年）》部署，促进医养结合发展，加强高等职业教育医养照护与管理专业建设，加快培养医养结合专业人才，现将有关工作通知如下。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　<strong style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;">一、加强专业设置管理</strong></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（一）支持专业梯次设置。引导和支持本地职业本科学校等设置医养照护与管理职业本科专业，并作为贯通培养专业，鼓励健康管理、老年保健与管理、智慧健康养老服务与管理等高职专科专业毕业生报考。鼓励有条件的学校探索医养照护与管理专业中高本贯通培养模式。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（二）完善专业建设管理。引导高等职业学校紧密对接区域医养结合发展需求，结合人才供需情况和学校办学实际，做好医养照护与管理专业设置论证和布点规划。鼓励普通本科高校与高等职业学校建立专业帮扶机制，引导医药卫生类相关优势专业和医养照护与管理专业结对建设，促进共建共享。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　<strong style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;">二、深化专业内涵建设</strong></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（三）优化人才培养方案。各地要加强对医养照护与管理专业的人才培养、课程设置、教学方法、专业规划等方面的办学指导。推进课程思政建设，加强法治素养培养，将健康中国建设、积极应对人口老龄化、依法执业等理念融入教学。引导学校联合医养结合机构、综合性医院老年医学科、基层医疗卫生机构及老年医学特色医院、康复医院、护理院（中心、站）等相关机构共同制定医养照护与管理专业人才培养方案，注重理论与实践紧密结合，实践教学学时原则上不低于50%。除实操课程外，支持学生到相关医疗卫生服务机构实习、实训，在真实环境中提升实操技能，增强就业本领。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（四）开发一批核心课程。引导学校开展职业岗位能力需求调研，与相关医疗卫生服务机构合作，绘制能力图谱，开发专业核心课程，研究制定课程标准。鼓励各地开展医养照护与管理专业教学资源库建设。支持各地、各学校探索将专业课程与医疗护理员等有关职业技能等级标准、培训大纲相结合，鼓励学生在完成学业课程的同时，报考相关职业技能等级证书、参加有关技能大赛。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（五）建设一批优质教材。引导学校与相关医疗卫生服务机构合作编写医养照护与管理专业优质教材。探索以典型工作任务为依据，以项目、任务、活动、案例等为载体的方式，开发活页式、工作手册式教材，对接真实服务、适应学生需求，保证教材的思想性、科学性、创新性、启发性和先进性。结合数智化时代要求，充分应用人工智能技术，融入虚拟仿真等数字资源，开发数字教材，满足学生多样化的学习需求。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（六）培育优秀教师团队。各地要加强医养照护与管理专业“双师型”教师队伍建设，建强用好教师创新团队和名师（名匠）工作室，支持相关医疗卫生服务机构高水平专业人员到职业学校兼职任教，职业学校教师到相关医疗卫生服务机构实践锻炼。鼓励符合条件的机构积极参与医养照护与管理专业专任教师培养培训等教育教学工作。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（七）创新人才培养模式。推进订单培养等人才培养模式改革，促进产教融合、医教协同、校企合作，推动人才培养与行业需求精准对接。支持相关医疗卫生服务机构与职业学校签订实践和培训协议，推动落实学生实习岗位设置与教学实践活动，支持学校建设老年人能力评估、老年人健康管理、老年人整合照护、失能失智老年人照护等真实服务场景的校内实训场所。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　<strong style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;">三、做好组织实施</strong></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　各地教育、卫生健康行政部门要协同推进落实高等职业教育医养照护与管理专业建设。鼓励有条件的地方对新增布点的学校、医养照护与管理专业学生等给予支持。教育行政部门重点支持、指导学校做好专业设置的科学论证和专业建设，支持有条件的机构建设开放型区域产教融合实践中心。卫生健康行政部门重点为有需求的学校提供技术支持、机构对接，协调区域内相关医疗卫生服务机构为学校教师实践和学生实习提供医养结合服务岗位，将医养照护与管理专业师资纳入医养结合人才培训范围，鼓励将符合条件的学校推荐为老年医学人才培训单位，支持各地畅通就业渠道，为毕业生提供良好的职业发展机会。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　北京、河北、黑龙江、江苏、浙江、江西、山东、广东、广西、四川等10个省（区、市）作为医养照护与管理高等职业教育专业建设重点省份，到2025年底，原则上每个重点省份新增1个医养照护与管理专业布点；到2027年底，原则上每个重点省份累计新增不少于3个医养照护与管理专业布点，带动全国医养照护与管理专业建设水平整体提高。</p>', NULL, 6, 1, 255, '2025-07-17 23:00:20', '2025-07-17 23:00:20');
INSERT INTO `homepage_section` (`title`, `content`, `cover_url`, `type`, `status`, `sort`, `create_time`, `update_time`) VALUES ('教育部办公厅关于提名2025年度教育部科学 研究优秀成果奖（自然科学和工程技术）的通知', '<p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">各省、自治区、直辖市教育厅（教委），新疆生产建设兵团教育局，有关部门（单位）教育司（局），中国科学技术协会办公厅，部属各高等学校、部省合建各高等学校：</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　为深入贯彻落实党的二十届三中全会和全国教育大会、全国科技大会精神，促进高等学校科技创新，提升高校创新人才自主培养水平，支撑高水平科技自立自强，助力新质生产力发展，按照有关要求，教育部决定启动2025年度教育部科学研究优秀成果奖（自然科学和工程技术）提名工作。现将有关事项通知如下。</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;">　　<strong style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; border: 0px; overflow: hidden;">一、提名要求</strong></span></span></span></span></span></span></span></span></span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　（一）提名方式</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　1. 单位提名</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　中央部门所属高等学校的各类研究成果，由学校直接提名；地方高等学校的各类研究成果，由省级教育行政部门统一提名。本次提名采用各单位限额提名方式，各单位最大提名数量另行通知。</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　2. 专家或组织提名</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　中国科学院院士、中国工程院院士，可以3人联合提名1项所熟悉专业的研究成果或1名青年奖人选；“双一流”建设高校校长、中国科学技术协会管辖的有关学会（中国数学会、中国物理学会、中国力学会、中国化学会、中国地质学会、中国机械工程学会、中国化工学会、中国土木工程学会、中国材料研究学会、中国动力工程学会、中国电子学会、中国通信学会、中国自动化学会、中国农学会、中华医学会、中国汽车工程学会）可提名1名青年奖人选；鼓励提名服务国家重大战略急需的青年人才。</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　专用项目是指内容涉及国家秘密的项目，除专用项目外的其他项目均为通用项目。提名专用项目的单位应具备相应的保密资格，专用项目只接受单位提名，不接受专家提名。</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　（二）提名项目（人选）的基本条件</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　提名项目（人选）须满足以下条件：</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　1. 提名项目第一完成单位是国内高校，其中专用项目第一完成单位应为国内民口高校。</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　2. 提名自然科学奖项目提供的代表性论文（专著）应当于2022年12月31日前公开发表，工程技术奖项目应当于2022年12月31日前完成整体技术应用。</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　3. 列入国家或省部级计划、基金支持的项目，应当在项目整体验收通过后提名。</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　4. 同一人同一年度只能作为一个教育部提名项目的完成人。</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　5. 已获得或正在申报国家级或省部级科技奖励的项目技术内容，不得提名2025年度教育部自然科学奖、工程技术奖。</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　6. 专用项目的相关内容应当在提名前已定密，并需提供相应的定密文件。</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　7. 青年奖男性被提名者当年未满35周岁（1990年1月1日后出生），女性被提名者当年未满38周岁（1987年1月1日后出生）。</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;">　　<strong style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; border: 0px; overflow: hidden;">二、提名程序</strong></span></span></span></span></span></span></span></span></span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　（一）提名号发放</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　1. 单位提名项目的提名号和校验码由所在学校发放。各学校可通过管理员账号和密码登录教育部科技管理信息系统（以下简称管理信息系统，网址：https://jybkjgl.moe.edu.cn/kjpj，系统开放时间为工作日8:00—20:00，节假日8:00—18:00），在线生成提名号和校验码。</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　管理员账号和密码重置，省级教育行政部门、中央部门所属高等学校请联系教育部科学技术与信息化司，地方高等学校请联系所属省级教育行政部门。</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　2. 专家或组织提名前，请责任提名专家或组织于2025年3月14日前通过本人电子邮件或组织单位邮箱向教育部提出申请（申请表见附件4、5），电邮及附件标题为“专家（组织）提名申请表-奖种-提名专家姓名（或组织名称）”。多名专家联合提名还需同时抄送其他提名专家。教育部将在收到申请后3个工作日内进行审核，经审核符合提名要求后发送提名号和校验码。</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　（二）提名书填写</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　提名书是教育部科学研究优秀成果奖（自然科学和工程技术）评审的主要依据，请提名单位、提名专家或组织按照《2025年度教育部科学研究优秀成果奖（自然科学和工程技术）提名工作手册》（附件1）要求，如实、准确、完整填写，并对所有完成人（青年奖候选人）的政治立场、师德学风、教书育人等情况进行评价。</span></span></span></span></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); border: 0px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-size: 16px;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; overflow: hidden;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: #4B4B4B;"><span style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; font-family: 微软雅黑, Arial, 宋体;">　　通用项目提名单位、提名专家或组织可于2025年3月17日起凭提名号和校验码登录管理信息系统，按要求在线填写、提交和提名。专用项目参照提名书模板（可从管理信息系统下载）、按照保密规定填写和提名。专用项目需按要求于2025年3月14日前至教育部科学技术与信息化司进行成果登记。</span></span></span></span></p>', NULL, 6, 1, 255, '2025-07-17 23:00:40', '2025-07-17 23:00:40');
INSERT INTO `homepage_section` (`title`, `content`, `cover_url`, `type`, `status`, `sort`, `create_time`, `update_time`) VALUES ('教育部部长怀进鹏在首场“部长通道”回应教育热点 提高人才培养质量 办强办优基础教育', '<p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><strong style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;"><span style="color: #666666; font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: #FFFFFF;">　　</span>新华社记者：</strong>最近一段时间，DeepSeek（深度求索）、智能机器人等引起广泛关注，当前新技术、新产业、新业态、新模式不断涌现，对相关人才的需求也越来越迫切。请问，教育部将采取哪些措施来培养更多服务国家战略、科技进步与产业需求的人才？</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　<strong style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;">怀进鹏：</strong>DeepSeek和机器人最近一段时间引起国内外广泛关注，从一个方面也说明了中国科技创新和人才培养的效果。但与此同时，也向我们提出了面对重大科技革命和产业变革，教育如何应对的问题。历史上每一次重大科技革命和产业变革都对社会提出了特别重要的需求，尤其是对教育，所以这也是教育改革和发展的重大机遇。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　习近平总书记在去年全国教育大会上强调，要以科技发展、国家战略需求为牵引，着眼提高创新能力，优化高等教育布局，完善高校学科设置调整机制和人才培养模式。李强总理在政府工作报告中也特别提到这一点。教育部将以制定和实施教育强国建设三年行动计划为基本出发点，推动高等教育综合改革，主要有三点考虑。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　第一，在制度和机制上推动创新。我们会加大产教融合和科教融汇的力度，协同相关部门共同建立有利于人才成长和创新发展相融合的生态和组织机制，围绕产业变革加快和加强学科布局。以产教融合为基础，推动卓越工程师学院建设，目前已建立了40家国家卓越工程师学院，未来将会进一步扩大。与产业加强合作，聘请2000多位企业的总师、1万多名企业工程师一起培养人才，来自实践的课题超过5000个。我们分类推进高校改革发展，根据高校的不同特点，鼓励办出自己的特色和优势。在这个基础上，加大力度推进评价体系改革，更好地引导学校面向国家战略和产业急需培养人才。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　第二，推出战略行动，在服务国家战略和科技发展中加快加强人才培养。一是体现在基础学科。科学技术有它的规律、有科学的范式。如何结合科学规律和科学范式培养人才？我们将深入实施“强基计划”，继续加大基础学科人才培养力度，在数学、计算机等领域，推动核心课程、核心师资队伍和核心教材等建设。二是围绕国家战略技术发展需要优化学科设置，推动新兴学科和交叉学科的人才培养，遵循科技革命、产业变革的规律加强人才培养，加快布局人工智能、生物技术、新能源、新材料等领域学科建设。三是扎实推进优质本科扩容，加强“双一流”建设，大力提升职业教育质量。职业教育为我国的现代产业、现代制造业作出了相当大的贡献，这个领域70%的人才来自职业教育的培养。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　第三，推进试点。发挥地方和高校的创新动能，先行先试，在科教融汇、产教融合中建立示范区。在任何一个国家，高等教育都是国家战略的宝贵资源，要把高校已经积聚的知识创新和技术能力，有效地服务区域发展和国家战略。我们推动建设高校区域技术转移转化中心，布局高等研究院，与人工智能、生物技术等重要领域相结合，适应国家战略和科技发展需要。建立研究生、本科和高职三个学科专业目录统一调整机制，建立人才供需动态监测机制，既要适应还要适度超前，快速跟进产业发展。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　科技革命正在深入开展，我们要继往开来，与时俱进，坚持开门办教育，深化国际开放合作办教育，服务中国式现代化，服务教育强国建设，为民族复兴作出教育的贡献。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　<strong style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;">扎实推进基础教育扩优提质</strong></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　<strong style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;">中国教育电视台记者：</strong>基础教育关系着千家万户，老百姓都非常关心。请问，教育部今年在这方面有什么重要举措？对于落实政府工作报告中的相关要求，又有怎样的考虑？</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　<strong style="margin: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box;">怀进鹏：</strong>基础教育关系千家万户，是老百姓最关心关切的事。中国基础教育有将近50万所学校，有2.3亿名学生。怎么看我国的基础教育？</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　一是学前教育入园率达到91.1%，义务教育巩固率达到95.7%，中国作为发展中大国，这个数据在全球比，处于世界高收入国家行列。二是高中阶段教育的毛入学率达到世界中高收入国家水平。三是全国2895个县全部实现了义务教育基本均衡，城镇务工随迁子女85%都能够进入公办学校就读。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　习近平总书记高度重视办好基础教育，这次政府工作报告又作出专门部署。今年，我们将重点关注两件事。一是教育资源配置。随着人口变化和城镇化的发展，推进“市县结合”的管理体制，完善动态调整机制，适应社会和人口结构的调整。二是县中振兴。近60%的普通高中生是在县中学习。我们将深入实施“县中振兴”行动计划，优化学校布局、加强师资配备，吸引和培养优秀教师到县中，使县中更好地服务乡村学生。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　此外，我们会进一步加大力度推进优质均衡发展。加强义务教育学校标准化建设，建好寄宿制学校，提供更好的教育环境。加强综合高中建设，更好地统筹职普融通。提升随迁子女的教育质量。加强师资队伍建设，把优秀中小学教师和校长的交流作为提高质量的重要内容。我们还会继续加大国家智慧教育平台建设，把人工智能与教育结合起来。今年将发布中国人工智能教育白皮书。提升学生在数字化时代、智能化时代的素养和能力，进一步加强科技教育和人文教育的融合。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　大家可能都注意到，春季学期开学，北京、安徽、甘肃等20多个省份开始实践“课间15分钟”，我们希望学生心里有阳光、身体能出汗，为未来奠定良好的基础。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-wrap: break-word; outline: none; word-break: break-all; -webkit-tap-highlight-color: transparent; -webkit-font-smoothing: antialiased; box-sizing: border-box; color: rgb(102, 102, 102); font-family: &quot;Microsoft YaHei&quot;, Verdana, Geneva, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　今天李强总理在政府工作报告中提到，要逐步推行免费学前教育，大家都很关心。教育部将会同相关部门研究出台相关政策，切实把普及普惠、教育布局和教师队伍建设做扎实。今年6月1日，学前教育法将正式实施，我们将推动制度、政策、保障机制深入落实，鼓励有条件的幼儿园为2—3岁的幼儿提供托育服务，切实把生育、养育和教育有机结合起来，为老百姓提供更多实惠。</p>', NULL, 6, 1, 255, '2025-07-17 23:01:08', '2025-07-17 23:01:08');

-- 信息公开 -> homepage_section (9 rows)
INSERT INTO `homepage_section` (`title`, `content`, `cover_url`, `type`, `status`, `sort`, `create_time`, `update_time`) VALUES ('关于许昌上嘉供应链管理有限公司职工邓洪委《深圳市认定工伤决定书》的送达公告', '<p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">许昌上嘉供应链管理有限公司：</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　我局于2025年06月18日作出《深圳市认定工伤决定书》（深人社工认决字〔2025〕050002271号），因你单位无法联系，且依据民事诉讼法规的其他送达方式无法送达，现公告送达如下：</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　你单位职工邓洪委（身份证号码：522122200210******）于2023年01月25日在深圳市光明大道聚丰路西17米（光明大道聚丰路11）因日常工作受伤，根据2023年01月25日初诊记录及其他诊断结论（或病历本）诊断为右胫腓骨远端骨折、右踝关节半脱位、右侧踝关节骨折、右侧跟骨骨折，受伤部位是右下肢。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　该员工上述情形符合《广东省工伤保险条例》第九条第（一）项，属于工伤认定范围，现予以认定（或视同）为工伤。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　如对本认定工伤决定不服的，可自本决定书送达之日起六十日内依法向深圳市人民政府申请行政复议；或自本决定书送达之日起六个月内依法向深圳市盐田区人民法院提起行政诉讼。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　本决定书自公告之日起经过三十日，视为送达。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　特此公告。</p>', NULL, 2, 1, 255, '2025-07-17 22:02:07', '2025-07-17 22:02:07');
INSERT INTO `homepage_section` (`title`, `content`, `cover_url`, `type`, `status`, `sort`, `create_time`, `update_time`) VALUES ('深圳市人力资源和社会保障局关于开展“深”怀绝技“圳”精彩·技能照亮前程—大规模职业技能提升培训行动政策系列宣讲会的通知', '<p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">各有关单位、个人：</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　为深入贯彻2025年政府工作报告关于开展大规模职业技能提升培训行动有关工作部署，全面落实人力资源社会保障部等相关部门关于“技能强企”“技能照亮前程”培训行动有关工作要求，我市开展&nbsp;“深”怀绝技“圳”精彩·技能照亮前程—大规模职业技能提升培训行动政策系列宣讲会。宣讲活动分期分批进行，本期活动主要围绕产教评技能生态链建设、企业新型学徒制培养政策、企业和技工院校、培训机构展示交流等方面开展。有关事项通知如下：</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　一、会议时间</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　7月18日（星期五）14:30—17:30</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　二、培训宣讲形式</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　线下培训和线上培训同步进行</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　三、线下宣讲地点</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　深圳人才园2041会议室（深南中路8005号）</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　四、活动议程：</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（一）政策宣讲</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　1.产教评技能生态链建设政策解读；</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　2.企业新型学徒制培养政策解读；</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　3.技能人才评价政策解读；</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（二）本市技工教育院校代表现场交流展示</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（三）本市职业培训机构、行业协会现场交流展示</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（四）本市企业代表现场分享交流</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　五、培训宣讲对象</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（一）各区人力资源部门有关负责同志；</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（二）企业、培训机构、职业院校、技工院校、行业协会等技能人才培养主体及劳动者个人。</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　六、报名方式</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（一）线下宣讲。参加线下宣讲会的单位和个人请于7月16日（星期三）下午5：00前将人员名单（见附件）发送到邮箱：<a href="mailto:szzpxh@163.com">szzpxh@163.com</a>；并请于宣讲会当天14:15前入场完毕，培训期间手机调为震动模式，注意保持会场秩序。</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（二）线上宣讲。参加线上宣讲会的单位和个人请于7月18日（星期五）14:25前直接进入腾讯会议，会议号：444921197 。宣讲会期间，不得在线上会议室发布与政策宣讲会无关的广告等信息。</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　六、其他</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　深圳人才园停车位紧张，请参会人员尽量乘坐公共交通出行。</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　特此通知。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　附件：参加线下宣讲会报名表</p>', NULL, 2, 1, 255, '2025-07-17 22:02:34', '2025-07-17 22:02:34');
INSERT INTO `homepage_section` (`title`, `content`, `cover_url`, `type`, `status`, `sort`, `create_time`, `update_time`) VALUES ('2025年度第27批次职业技能提升补贴公示', '<p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　根据《深圳市职业技能培训补贴办法》(深人社规〔2023〕8号)的规定，现将审核拟发放的职业技能提升补贴名单予以公示。公示期为2025年7月15日至2025年7月21日。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　公示期间，任何单位或个人均可通过来人、来电、来信等方式向深圳市人力资源和社会保障局反映公示对象存在的问题。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　反映情况和问题须实事求是、客观公正。反映人必须提供真实姓名、联系电话，以示负责。我局将对反映人和反映情况严格保密，对所反映的情况和问题，将认真进行调查核实，并视情况按有关文件规定进行处理。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　地址：深圳市福田区深南大道8005号市行政服务大厅人才园服务厅10号综合窗口，邮编：518040；联系电话：0755-83699610；电子邮箱：szsybxpxbt@hrss.sz.gov.cn。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　附件：2025年第27批次职业技能提升补贴公示名单</p>', NULL, 2, 1, 255, '2025-07-17 22:03:15', '2025-07-17 22:03:15');
INSERT INTO `homepage_section` (`title`, `content`, `cover_url`, `type`, `status`, `sort`, `create_time`, `update_time`) VALUES ('深圳市人力资源和社会保障局关于公布我市博士后设站单位名单和动态调整情况的通知', '<p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">各有关博士后设站单位：</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　为规范我市博士后设站单位管理，建立健全动态调整机制，推动博士后工作高质量发展，根据《深圳市博士后工作管理规定》（深人社规〔2024〕2号）（以下简称《规定》），我局对我市博士后设站单位提交年度报告情况开展核查工作，经核查，现将我市当前正常开展博士后工作的设站单位名单予以公布（见附件）。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　请各博士后设站单位高度重视博士后科研平台的建设工作，履行主体责任，强化规范管理，提升建设质量。<strong>一是</strong>要切实发挥主体作用，做好建章立制、招收培养、考核管理、资金管理等工作，充分发挥博士后制度在聚焦培养青年科技人才、持续推动产学研合作方面的重要作用。<strong>二是</strong>要高度重视年度报告提交工作，及时、准确报送本单位博士后招收培养、质量管理和产学研合作等履行主体责任情况。<strong>三是</strong>要积极发动本单位博士后团队参加全国和粤港澳大湾区博士后创新创业大赛，做好本单位博士后工作信息收集和成果统计，发动本单位博士后参与我市创新创业成果展示交易工作。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　特此通知。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　附件：2025年深圳市博士后设站单位名单</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: right;">　　深圳市人力资源和社会保障局<br/></p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: right;">　　2025年7月15日</p>', NULL, 2, 1, 255, '2025-07-17 22:03:37', '2025-07-17 22:03:37');
INSERT INTO `homepage_section` (`title`, `content`, `cover_url`, `type`, `status`, `sort`, `create_time`, `update_time`) VALUES ('深圳市创业担保贷款贴息情况（第七批）', '<p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　根据《深圳市创业担保贷款管理办法》（深人社规〔2024〕1号）（以下简称《管理办法》）第三十条有关规定，现公布已还本付息的1073笔个人创业担保贷款和33笔小微企业创业担保贷款的贴息情况（见附件）。</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　任何单位和个人如对公布内容有异议，均可通过来电、来函、来信等方式反映。（地址：深圳市福田区八卦二路劳动就业大厦；电话：0755-82132891、0755-82131672）</p><p indenttext="　　" noextractcontent="true" style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　附件：深圳市创业担保贷款贴息情况表（第七批）</p>', NULL, 2, 1, 255, '2025-07-17 22:04:31', '2025-07-17 22:04:31');
INSERT INTO `homepage_section` (`title`, `content`, `cover_url`, `type`, `status`, `sort`, `create_time`, `update_time`) VALUES ('深圳市人力资源和社会保障局关于开展2025年劳务派遣用工情况调查工作的通知', '<p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">各区人力资源局，大鹏新区、深汕特别合作区统战和社会建设局，各相关单位：<br/></p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　为贯彻落实《关于实施人力资源服务业统计制度的通知》（粤人社函〔2022〕73号）工作要求，进一步做好我市劳务派遣用工情况监测工作，我局委托第三方专业机构深圳市维度数据科技股份有限公司开展2025年深圳市劳务派遣用工情况调查工作。现将相关事项通知如下：</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　一、调查时间</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　2025年7月开展半年度调查，2026年1月开展年度调查。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　二、调查对象</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　调查对象为在我市已办理商事主体登记，并经人力资源部门许可或备案，且许可或备案尚在有效期内的劳务派遣单位。年度调查对象还包括与劳务派遣单位签订了劳务派遣合同且正在合同期内的用工单位和我市劳务派遣单位的派遣员工。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　三、调查方式</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　填报方式为登录系统填报，可登录填报网址或扫描二维码填报（网址、二维码见附件）。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　四、填报时间</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　请各调查对象于通知印发后的20日内完成问卷填报。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　五、工作要求</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（一）各区人力资源部门要及时上报辖区符合要求的劳务派遣单位名单、单位状态异常说明情况，确保名单和单位信息全面、准确，并配合发动调查对象积极填报，单位无法填报的说明原因。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（二）问卷填报如有疑问，请通过电话等方式咨询。联系人及电话:陈丽丽，13128729428。咨询QQ群名称:深圳市劳务派遣市场情况调查咨询群，群号：134670087、1002374337。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　（三）填报信息将严格按照《中华人民共和国统计法》规定予以保密，仅用于项目分析工作。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　特此通知。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　&nbsp; &nbsp; &nbsp; &nbsp;附件：2025年劳务派遣用工情况调查数据填报网址及二维码</p>', NULL, 2, 1, 255, '2025-07-17 22:04:07', '2025-07-17 22:04:07');
INSERT INTO `homepage_section` (`title`, `content`, `cover_url`, `type`, `status`, `sort`, `create_time`, `update_time`) VALUES ('关于广东博佑建筑劳务有限公司职工陈亮《深圳市认定工伤决定书》的送达公告', '<p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">广东博佑建筑劳务有限公司：</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　我局于2025年06月26日作出《深圳市认定工伤决定书》（深人社建工认决字〔2025〕110000291号）。因无法联系到你单位，且依据民事诉讼法规的其他送达方式无法送达，现公告送达如下：</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　你单位员工陈亮（身份证号码：513723196503******）于2024年11月25日在世优工业园项目工地因日常工作受伤，根据2024年11月26日初诊记录及其他诊断结论（或病历本）诊断为鼻损伤，鼻骨骨折，受伤部位是鼻部。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　该员工上述情形符合《广东省工伤保险条例》第九条第（一）项，属于工伤认定范围，现予以认定（或视同）为工伤。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　如对本认定工伤决定不服的，可自本决定书送达之日起六十日内依法向深圳市人民政府申请行政复议；或自本决定书送达之日起六个月内依法向深圳市盐田区人民法院提起行政诉讼。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　本决定自公告之日起经过三十日，视为送达。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　特此公告。</p>', NULL, 2, 1, 255, '2025-07-17 22:04:54', '2025-07-17 22:04:54');
INSERT INTO `homepage_section` (`title`, `content`, `cover_url`, `type`, `status`, `sort`, `create_time`, `update_time`) VALUES ('关于深圳应东建筑工程劳务有限公司职工杨常木《深圳市更正工伤决定告知书》的送达公告', '<p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">深圳应东建筑工程劳务有限公司：</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　我局于2025年06月13日作出《深圳市更正工伤决定告知书》（深人社工更认决字〔2025〕0003号），因你单位拒收文书，且依据民事诉讼法规的其他送达方式无法送达，现公告送达如下：</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　我局于2025年01月20日作出《深圳市认定工伤决定书》（深人社建工认决字〔2025〕100000038号），依法认定杨常木为工伤。经核实，该决定书存在笔误，应予更正，具体如下：</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　原决定书正文中第1行、第2行“深圳市应东建筑工程劳务有限公司”更正为“深圳应东建筑工程劳务有限公司”。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　本告知书自公告之日起经过三十日，视为送达。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　特此公告。</p>', NULL, 2, 1, 255, '2025-07-17 22:05:16', '2025-07-17 22:05:16');
INSERT INTO `homepage_section` (`title`, `content`, `cover_url`, `type`, `status`, `sort`, `create_time`, `update_time`) VALUES ('关于深圳应东建筑工程劳务有限公司职工杨常木《深圳市更正工伤决定告知书》的送达公告', '<p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">深圳应东建筑工程劳务有限公司：</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　我局于2025年06月13日作出《深圳市更正工伤决定告知书》（深人社工更认决字〔2025〕0004号），因你单位拒收文书，且依据民事诉讼法规的其他送达方式无法送达，现公告送达如下：</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　我局于2024年11月13日出具的《深圳市工伤认定申请收件回执》（深人社工认收字〔2024〕100002505号）、2024年11月27日出具的《深圳市工伤认定申请受理告知书》（深人社工认受告字〔2024〕100002422号），经核实，该两份文件存在笔误，应予更正，具体如下：</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　将申请人：“深圳市应东建筑工程劳务有限公司”更正为“深圳应东建筑工程劳务有限公司”。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　本告知书自公告之日起经过三十日，视为送达。</p><p style="margin-top: 0px; line-height: 1.5; color: rgb(25, 26, 27); font-family: 微软雅黑, &quot;sans-serif&quot;, Arial; font-size: 17.5px; text-wrap-mode: wrap; background-color: rgb(255, 255, 255); text-align: justify;">　　特此公告。</p>', NULL, 2, 1, 255, '2025-07-17 22:05:43', '2025-07-17 22:05:43');

-- 机构概况 -> homepage_section (1 rows)
INSERT INTO `homepage_section` (`title`, `content`, `cover_url`, `type`, `status`, `sort`, `create_time`, `update_time`) VALUES ('机构概况', '<p>&nbsp; &nbsp;中国人力资源专业技能人才评价中心（China Human Resources Professional Skills Talent Evaluation Center）经香港政府批准成立，职能部门有人力资源技能人才培育委员会、岗位职责职能培训部、人才数据入库审核部、专项技能人才培训部，致力于专业人才测评与考核、专业人才储备库建设平台。 <span>专业技能人才评价中心</span>搭建线上测评平台、线上学习平台、线上人才库查询平台，为经过合作机构培训及举荐的人才提供线上服务系统并免费发放合格证书，中心总部位于香港。</p><p>&nbsp; &nbsp; &nbsp; &nbsp; 属于非赢利性机构， <span></span>人力资源专业技能人才评价中心<span>和技能人才培育委员会</span>致力于高水平认证考评服务和专业的人才举荐、储备服务，本中心发放的证书作为合作机构人才举荐的人才储备证明，非职业资格证书，不承诺用途，作为人才储备入库凭证，为学员和用人单位提供参考，为提高我国认证的有效性及人才的有效储备、培养、交流努力做出积极的贡献。</p><p>&nbsp; &nbsp; &nbsp; &nbsp; <span>中国人力资源专业技能人才评价中心</span><span></span>是为全面落实国家人部发【2007】96号文件精神，全面加强专业技术人才队伍建设，按照《国家中长期科学和技术发展规划纲要（2006-2020年）》和《干部教育培训工作条例（试行）》的要求，人事部、教育部、科技部、财政部制定的《关于加强专业技术人员继续教育工作的意见》中心以“希望在于人才，一切为了人才”为服务理念，宗旨是立足香港、面向全国，为社会各类企业、事业单位和人才提供社会化人事管理服务，为人才流动和人力资源开发提供综合性服务，促进人才合理流动、合理配置、合理使用，为我国的经济建设和社会全面发展服务.中心是以人才培养开发、人才评价为核心业务的国际化、市场化人才服务测评中心。 &nbsp;<span>技能人才评价中心</span>以实现党的十七大、《国家中长期人才发展规划》、十八大等一系列会议和文件中关于人才工作的指示精神和规划等为目标开展市场化人才评价业务并颁发结业证书。人才是指具有一定的专业知识或专门技能，进行创造性劳动并对社会作出贡献的人，是人力资源中能力和素质较高的劳动者。人才是我国经济社会发展的第一资源。《国家中长期人才发展规划》指出，到2020年我国人才发展总体目标是：培养造就规模宏大、结构优化、布局合理、素质优良的人才队伍，确立国家人才竞争比较优势，进入世界人才强国行列，为在本世纪中叶基本实现社会主义现代化奠定人才基础。我们要围绕这个总体目标，坚定不移走人才强国之路，科学规划，深化改革，重点突破，整体推进，努力实现人才资源总量稳步增长、队伍规模不断壮大，人才素质大幅度提高、结构进一步优化，人才竞争比较优势明显增强、竞争力不断提升，人才使用效能明显提高、人才发展体制机制创新取得突破性进展，逐步实现由人力资源大国向人才强国转变。</p><p>中心宗旨</p><p>&nbsp; &nbsp; &nbsp;贯彻科学发展观，建立和完善市场化人才评价体系，推进中高端人才的发现评价和培养开发、储备，为我国社会主义建设提供高素质人才保障，形成具有国际竞争力的人力资源优势，实现我国人才发展总体目标。  </p><p>历史使命</p><p>&nbsp; &nbsp;强调“开放、责任、质量、多样化、国际化”的人才理念，按照需求导向深入推进人才评价模式的创新，搭建人才培养与社会需求“立交桥”，适应国家经济社会发展和人的全面发展需要。致力于把中国人力资源专业技术技能评价中心建设成为市场化人才评价体系的中坚力量；世界人才评价体系中富有中国特色的开放典型；我国人才评价体系的重要支柱。 </p><p><br/></p>', NULL, 7, 1, 255, '2025-07-14 15:04:54', '2025-08-01 11:33:25');

