INSERT INTO `homepage_section` (`title`, `content`, `cover_url`, `type`, `status`, `sort`, `create_time`, `update_time`) VALUES ('联系方式', '<p><span style="caret-color: #2C3E50; color: #2C3E50; font-family: &quot;Microsoft Yahei&quot;; background-color: #F6F6F6;">网上报名相关问题：</span></p><p><span style="caret-color: #2C3E50; color: #2C3E50; font-family: &quot;Microsoft Yahei&quot;; background-color: #F6F6F6;">邮箱：</span><span style="caret-color: #21293A; color: #21293A; font-family: verdana; background-color: #F5F5F5;">zgrlzyjnrc@163.com</span></p><p><span style="caret-color: #2C3E50; color: #2C3E50; font-family: &quot;Microsoft Yahei&quot;; background-color: #F6F6F6;">工作时间为：周一至周五，8:30-12:00；13:00-17:30（国家法定节假日除外）。</span></p><p><br/></p>', NULL, 9, 1, 255, '2025-07-14 15:38:27', '2025-07-19 13:21:17');

