-- 新闻动态 -> news (26 rows)
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('2026世界数字教育大会将聚焦人工智能与教育融合发展', '<p style="white-space: normal; margin-top: 10px; margin-bottom: 10px; padding: 0px; border: 0px; list-style: none; line-height: 30px; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: -apple-system, BlinkMacSystemFont, &quot;PingFang SC&quot;, &quot;Helvetica Neue&quot;, STHeiti, &quot;Microsoft Yahei&quot;, Tahoma, Simsun, sans-serif, Helvetica, 微软雅黑;">新华社北京5月7日电（记者王鹏、俞菀）记者7日从教育部新闻发布会获悉，2026世界数字教育大会将于5月11日至13日在浙江杭州举办，主题为“人工智能+教育：变革 发展 治理”。各国嘉宾将齐聚一堂，讨论人工智能如何推动教育系统性变革、促进教育高质量发展。</p><p style="white-space: normal; margin-top: 10px; margin-bottom: 10px; padding: 0px; border: 0px; list-style: none; line-height: 30px; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: -apple-system, BlinkMacSystemFont, &quot;PingFang SC&quot;, &quot;Helvetica Neue&quot;, STHeiti, &quot;Microsoft Yahei&quot;, Tahoma, Simsun, sans-serif, Helvetica, 微软雅黑;">　 “近年来，教育部充分发挥中国教育体系完备、师生规模庞大优势，推动人工智能融入教育全要素、全过程和全领域。同时，也积极深化包括人工智能在内的数智教育国际合作，搭建交流平台、共享实践成果，促进全球教育高质量发展。”发布会上，教育部国际合作与交流司司长杨丹说。</p><p style="white-space: normal; margin-top: 10px; margin-bottom: 10px; padding: 0px; border: 0px; list-style: none; line-height: 30px; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: -apple-system, BlinkMacSystemFont, &quot;PingFang SC&quot;, &quot;Helvetica Neue&quot;, STHeiti, &quot;Microsoft Yahei&quot;, Tahoma, Simsun, sans-serif, Helvetica, 微软雅黑;">　 据介绍，2026世界数字教育大会主要包括开幕式、全体会议、平行会议和闭幕式等四个环节，集中展现人工智能赋能教育变革和人工智能产教融合的创新实践、深度思考和创新案例，还将发布《中国智慧教育发展报告（2025—2026）》《全球数字教育发展指数（2026年）》等八项成果。</p><p style="white-space: normal; margin-top: 10px; margin-bottom: 10px; padding: 0px; border: 0px; list-style: none; line-height: 30px; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: -apple-system, BlinkMacSystemFont, &quot;PingFang SC&quot;, &quot;Helvetica Neue&quot;, STHeiti, &quot;Microsoft Yahei&quot;, Tahoma, Simsun, sans-serif, Helvetica, 微软雅黑;">　 此外，大会同期将举办全球数字教育成果展。“展览遴选118个优秀实践案例，全方位展示智能技术在教学模式、学习方式、学校治理、科技创新等方面的创新应用，特别是在促进教育优质均衡、赋能学生个性发展、完善全民终身学习等方面的实践经验。”教育部科学技术与信息化司副司长舒华说。</p>', NULL, '本站', '新华社北京5月7日电（记者王鹏、俞菀）记者7日从教育部新闻发布会获悉，2026世界数字教育大会将于5月11日至13日在浙江杭州举办，主题为“人工智能+教育：变革 发展 治理”。各国嘉宾将齐聚一堂，讨论人工智能如何推动教育系统性变革、促进教育高质量发展。 “近年来，教育部充分发挥中国教育体系完备、师生规模庞大优势，', 1, 255, 1, '2026-05-22 15:29:07', '2026-05-22 15:33:10', '2026-05-22 15:33:10');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('我国不断增强技能培训质量和效果', '<p data-spm-anchor-id="C73544894212.P26598934187.0.i1" style="white-space: normal; padding: 0px; margin-top: 0px; margin-bottom: 30px; list-style: none; font-size: 18px; line-height: 32px; color: rgb(51, 51, 51); word-break: break-all; font-family: PingFangSC-Regular, Helvetica, Arial, &quot;Microsoft Yahei&quot;, sans-serif;">记者近日获悉，2025年人力资源社会保障部以“技能照亮前程”培训行动为牵引，开展大规模职业技能提升培训，全面推行“岗位需求＋技能培训＋技能评价＋就业服务”联动模式，增强培训质量和效果。全年开展补贴性培训超过1100万人次，帮助劳动者实现技能就业、技能增收。</p><p style="white-space: normal; padding: 0px; margin-top: 0px; margin-bottom: 30px; list-style: none; font-size: 18px; line-height: 32px; color: rgb(51, 51, 51); word-break: break-all; font-family: PingFangSC-Regular, Helvetica, Arial, &quot;Microsoft Yahei&quot;, sans-serif;">　　人力资源社会保障部职业能力建设司副司长翟涛介绍，人力资源社会保障部紧密对接新质生产力培育和就业容量大的民生领域，会同有关部门组织实施制造业、数字人才、长期照护、养老护理、家政服务、交通运输、文物修复等领域专项培训，加强急需紧缺技能人才供给。充分考虑高校毕业生、农民工等重点群体的差异化培训需求，实施技能强企行动和面向青年、农民工群体的培训计划，缓解结构性就业矛盾。</p><p style="white-space: normal; padding: 0px; margin-top: 0px; margin-bottom: 30px; list-style: none; font-size: 18px; line-height: 32px; color: rgb(51, 51, 51); word-break: break-all; font-family: PingFangSC-Regular, Helvetica, Arial, &quot;Microsoft Yahei&quot;, sans-serif;">　　同时，创新培训模式，提高培训质效。人力资源社会保障部以龙头企业、链主企业为主导，引导各地打造230多条“产教评”技能生态链，把培训建在产业链上；推动职业院校、技工院校深化校企合作、对接企业用人需求，打造“订单式”培训模式；依托劳务品牌机构、优质培训机构打造“项目制”培训模式。</p><p style="white-space: normal; padding: 0px; margin-top: 0px; margin-bottom: 30px; list-style: none; font-size: 18px; line-height: 32px; color: rgb(51, 51, 51); word-break: break-all; font-family: PingFangSC-Regular, Helvetica, Arial, &quot;Microsoft Yahei&quot;, sans-serif;">　　翟涛表示，2026年将聚焦“投资于人”，深入实施“技能照亮前程”培训行动，使培训更好服务于产业发展，促进人才培养和就业紧密衔接，让培训红利更加可感可及，引导更多劳动者走技能成才、技能就业之路。（记者张晓洁）</p>', NULL, '本站', '记者近日获悉，2025年人力资源社会保障部以“技能照亮前程”培训行动为牵引，开展大规模职业技能提升培训，全面推行“岗位需求＋技能培训＋技能评价＋就业服务”联动模式，增强培训质量和效果。全年开展补贴性培训超过1100万人次，帮助劳动者实现技能就业、技能增收。人力资源社会保障部职业能力建设司副司长翟涛介绍，', 1, 255, 1, '2026-05-22 15:27:45', '2026-05-22 15:29:05', '2026-05-22 15:29:05');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('人社部：实施百万青年技能提升培训，鼓励各地开设大学生技师班', '<div class="dpu8C   " style="white-space: normal; overflow-wrap: anywhere; word-break: normal; max-width: 100%; overflow-x: visible; font-size: 19px; color: rgb(34, 34, 34); line-height: 30px; margin-top: 28px; font-family: arial; text-align: justify; text-wrap-style: unset !important;"><p style="overflow-wrap: anywhere; white-space-collapse: collapse; word-break: normal; overflow-y: auto; max-width: 100%; line-height: 30px; margin-top: 0px !important; margin-bottom: 0px !important; padding: 0px !important; text-wrap: unset !important;"><strong style="overflow-wrap: anywhere; white-space-collapse: collapse; word-break: normal; max-width: 100%; text-wrap: unset !important;"><img src="/static/upload/image/20260522/1779434826122951.png" alt="499e200b-c73f-426b-aa0f-265549878385.png"/>21世纪经济报道记者王峰 北京报道</strong></p></div><div class="dpu8C   " style="white-space: normal; overflow-wrap: anywhere; word-break: normal; max-width: 100%; overflow-x: visible; font-size: 19px; color: rgb(34, 34, 34); line-height: 30px; margin-top: 24px; font-family: arial; text-align: justify; text-wrap-style: unset !important;"><p style="overflow-wrap: anywhere; white-space-collapse: collapse; word-break: normal; overflow-y: auto; max-width: 100%; line-height: 30px; margin-top: 0px !important; margin-bottom: 0px !important; padding: 0px !important; text-wrap: unset !important;">2025年，大规模职业技能提升培训取得积极进展，全年共开展补贴性职业培训1153万人次。</p></div><div class="dpu8C   " style="white-space: normal; overflow-wrap: anywhere; word-break: normal; max-width: 100%; overflow-x: visible; font-size: 19px; color: rgb(34, 34, 34); line-height: 30px; margin-top: 24px; font-family: arial; text-align: justify; text-wrap-style: unset !important;"><p style="overflow-wrap: anywhere; white-space-collapse: collapse; word-break: normal; overflow-y: auto; max-width: 100%; line-height: 30px; margin-top: 0px !important; margin-bottom: 0px !important; padding: 0px !important; text-wrap: unset !important;">在4月28日人力资源社会保障部例行新闻发布会上，人力资源社会保障部职业能力建设司副司长翟涛介绍，今年将进一步加强统筹协调，不断提高培训质效。</p></div><div class="dpu8C   " style="white-space: normal; overflow-wrap: anywhere; word-break: normal; max-width: 100%; overflow-x: visible; font-size: 19px; color: rgb(34, 34, 34); line-height: 30px; margin-top: 24px; font-family: arial; text-align: justify; text-wrap-style: unset !important;"><p style="overflow-wrap: anywhere; white-space-collapse: collapse; word-break: normal; overflow-y: auto; max-width: 100%; line-height: 30px; margin-top: 0px !important; margin-bottom: 0px !important; padding: 0px !important; text-wrap: unset !important;">翟涛特别提到，<strong style="overflow-wrap: anywhere; white-space-collapse: collapse; word-break: normal; max-width: 100%; text-wrap: unset !important;">将实施百万青年技能提升培训，鼓励各地通过开设大学生技师班等多种方式，更好满足大学生等青年群体学技能的需求。</strong></p></div><div class="dpu8C   " style="white-space: normal; overflow-wrap: anywhere; word-break: normal; max-width: 100%; overflow-x: visible; font-size: 19px; color: rgb(34, 34, 34); line-height: 30px; margin-top: 24px; font-family: arial; text-align: justify; text-wrap-style: unset !important;"><p style="overflow-wrap: anywhere; white-space-collapse: collapse; word-break: normal; overflow-y: auto; max-width: 100%; line-height: 30px; margin-top: 0px !important; margin-bottom: 0px !important; padding: 0px !important; text-wrap: unset !important;">今年，人社部将联合有关部门实施一批重点领域、重点群体技能提升行动。</p></div><div class="dpu8C   " style="white-space: normal; overflow-wrap: anywhere; word-break: normal; max-width: 100%; overflow-x: visible; font-size: 19px; color: rgb(34, 34, 34); line-height: 30px; margin-top: 24px; font-family: arial; text-align: justify; text-wrap-style: unset !important;"><p style="overflow-wrap: anywhere; white-space-collapse: collapse; word-break: normal; overflow-y: auto; max-width: 100%; line-height: 30px; margin-top: 0px !important; margin-bottom: 0px !important; padding: 0px !important; text-wrap: unset !important;">重点领域主要包括人工智能、先进制造业、低空经济、新能源汽车、康养服务等领域。重点群体主要包括高校毕业生、农民工、退役军人、新就业形态群体等。</p></div><div class="dpu8C   " style="white-space: normal; overflow-wrap: anywhere; word-break: normal; max-width: 100%; overflow-x: visible; font-size: 19px; color: rgb(34, 34, 34); line-height: 30px; margin-top: 24px; font-family: arial; text-align: justify; text-wrap-style: unset !important;"><p style="overflow-wrap: anywhere; white-space-collapse: collapse; word-break: normal; overflow-y: auto; max-width: 100%; line-height: 30px; margin-top: 0px !important; margin-bottom: 0px !important; padding: 0px !important; text-wrap: unset !important;">比如，随着人工智能的迅猛发展，掌握人工智能技术应用技能，已经成为劳动者提升就业能力和提高生活品质的刚需。今年将会同有关部门开展人工智能技术技能提升行动，加强人工智能通识教育，不断提升劳动者数字素养和人工智能应用能力。广大劳动者可以到技工教育网等线上平台免费学习相关课程。</p></div><div class="dpu8C   " style="white-space: normal; overflow-wrap: anywhere; word-break: normal; max-width: 100%; overflow-x: visible; font-size: 19px; color: rgb(34, 34, 34); line-height: 30px; margin-top: 24px; font-family: arial; text-align: justify; text-wrap-style: unset !important;"><p style="overflow-wrap: anywhere; white-space-collapse: collapse; word-break: normal; overflow-y: auto; max-width: 100%; line-height: 30px; margin-top: 0px !important; margin-bottom: 0px !important; padding: 0px !important; text-wrap: unset !important;">再比如，针对高校毕业生等青年多样化、个性化的技能培训需求，将实施百万青年技能提升培训，鼓励各地通过开设大学生技师班等多种方式，更好满足大学生等青年群体学技能的需求。</p></div><div class="dpu8C   " style="white-space: normal; overflow-wrap: anywhere; word-break: normal; max-width: 100%; overflow-x: visible; font-size: 19px; color: rgb(34, 34, 34); line-height: 30px; margin-top: 24px; font-family: arial; text-align: justify; text-wrap-style: unset !important;"><p style="overflow-wrap: anywhere; white-space-collapse: collapse; word-break: normal; overflow-y: auto; max-width: 100%; line-height: 30px; margin-top: 0px !important; margin-bottom: 0px !important; padding: 0px !important; text-wrap: unset !important;">今年，北京市在北京市工业技师学院、北京市工贸技师学院、北京市新媒体技师学院、北京电子信息技师学院、北京汽车技师学院、北京市工艺美术技师学院6所技师学院，开设生物制药、智能制造技术应用、多媒体制作、电子技术应用、汽车维修、工艺美术等大学生技师班。</p></div><div class="dpu8C   " style="white-space: normal; overflow-wrap: anywhere; word-break: normal; max-width: 100%; overflow-x: visible; font-size: 19px; color: rgb(34, 34, 34); line-height: 30px; margin-top: 24px; font-family: arial; text-align: justify; text-wrap-style: unset !important;"><p style="overflow-wrap: anywhere; white-space-collapse: collapse; word-break: normal; overflow-y: auto; max-width: 100%; line-height: 30px; margin-top: 0px !important; margin-bottom: 0px !important; padding: 0px !important; text-wrap: unset !important;">这6个大学生技师班面向大学专科及以上学历毕业生，学制2年，其中1年在校学习、1年企业实习，毕业时可取得技工院校毕业证书和职业技能等级证书。</p></div><div class="dpu8C   " style="white-space: normal; overflow-wrap: anywhere; word-break: normal; max-width: 100%; overflow-x: visible; font-size: 19px; color: rgb(34, 34, 34); line-height: 30px; margin-top: 24px; font-family: arial; text-align: justify; text-wrap-style: unset !important;"><p style="overflow-wrap: anywhere; white-space-collapse: collapse; word-break: normal; overflow-y: auto; max-width: 100%; line-height: 30px; margin-top: 0px !important; margin-bottom: 0px !important; padding: 0px !important; text-wrap: unset !important;">同时，北京市还组织了21个短期的大学生就业培训班，这些班次培训时间从15天到半年不等，专业覆盖从航空航天精密制造培训到西式面点师培训，特别适合大学生在已有的理论知识学习的基础上再进行技能深造。</p></div><div class="dpu8C   " style="white-space: normal; overflow-wrap: anywhere; word-break: normal; max-width: 100%; overflow-x: visible; font-size: 19px; color: rgb(34, 34, 34); line-height: 30px; margin-top: 24px; font-family: arial; text-align: justify; text-wrap-style: unset !important;"><p style="overflow-wrap: anywhere; white-space-collapse: collapse; word-break: normal; overflow-y: auto; max-width: 100%; line-height: 30px; margin-top: 0px !important; margin-bottom: 0px !important; padding: 0px !important; text-wrap: unset !important;">北京市人社局职业能力建设处处长王希今年3月曾表示，“所有这些班的学员参加完学习后，我们还可以推荐就业。”</p></div><div class="dpu8C   " style="white-space: normal; overflow-wrap: anywhere; word-break: normal; max-width: 100%; overflow-x: visible; font-size: 19px; color: rgb(34, 34, 34); line-height: 30px; margin-top: 24px; font-family: arial; text-align: justify; text-wrap-style: unset !important;"><p style="overflow-wrap: anywhere; white-space-collapse: collapse; word-break: normal; overflow-y: auto; max-width: 100%; line-height: 30px; margin-top: 0px !important; margin-bottom: 0px !important; padding: 0px !important; text-wrap: unset !important;">大学生读技校现象已非个例。2025年，山东、浙江、广东等省份密集出台政策，支持技工院校面向就业和未就业大学生，开设全日制和非全日制大学生技师班。2026年，大学生技师班的布局范围将更大。</p></div><div class="dpu8C   " style="white-space: normal; overflow-wrap: anywhere; word-break: normal; max-width: 100%; overflow-x: visible; font-size: 19px; color: rgb(34, 34, 34); line-height: 30px; margin-top: 24px; font-family: arial; text-align: justify; text-wrap-style: unset !important;"><p style="overflow-wrap: anywhere; white-space-collapse: collapse; word-break: normal; overflow-y: auto; max-width: 100%; line-height: 30px; margin-top: 0px !important; margin-bottom: 0px !important; padding: 0px !important; text-wrap: unset !important;">翟涛介绍，今年将推动技工院校普遍对接企业需求，开展订单式培训，促进人岗匹配；紧盯用工急需紧缺领域，由政府组织推动，大力开展项目制培训，加强技能人才供给。</p></div>', '/static/upload/image/20260522/1779434826122951.png', '本站', '21世纪经济报道记者王峰 北京报道2025年，大规模职业技能提升培训取得积极进展，全年共开展补贴性职业培训1153万人次。在4月28日人力资源社会保障部例行新闻发布会上，人力资源社会保障部职业能力建设司副司长翟涛介绍，今年将进一步加强统筹协调，不断提高培训质效。翟涛特别提到，将实施百万青年技能提升培训，鼓励各地通', 1, 255, 1, '2026-05-22 15:26:00', '2026-05-22 15:27:44', '2026-05-22 15:27:44');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('教育部等五部门关于印发 《“人工智能+教育”行动计划》的通知', '<h1 style="margin: 0px; padding: 0px; border: 0px; overflow: hidden; font-size: 20px; text-align: center; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; white-space: normal; background-color: rgb(255, 255, 255);">教育部等五部门关于印发<br/>《“人工智能+教育”行动计划》的通知</h1><p class="moe-policy-wenhao" style="margin: 30px 0px 0px; padding: 16px 0px; border: 0px; overflow: hidden; text-align: right; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">教科信〔2026〕1号</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　现将《“人工智能+教育”行动计划》印发给你们，请认真贯彻落实。</p><p style="text-align:right;margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">教 育 部&nbsp; 国家发展改革委&nbsp; 工业和信息化部</p><p style="text-align:right;margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">科技部&nbsp; 国家数据局</p><p style="text-align:right;margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">2026年4月2日</p><p style="text-align:center;margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);"><strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">“人工智能+教育”行动计划</strong></p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　根据《教育强国建设规划纲要（2024—2035年）》战略部署，按照《国务院关于深入实施“人工智能+”行动的意见》的要求，制定本计划。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">一、总体要求</strong></p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届历次全会、全国教育大会精神，全面贯彻党的教育方针，落实立德树人根本任务，深入实施国家教育数字化战略，坚持育人为本、素养为先、应用导向、智能向善，充分发挥人工智能赋能教育变革的引擎作用，推动智能技术与教育全要素融合、全过程贯通、全场景覆盖，统筹推进人工智能人才培养和应用创新，协同推进基础环境和创新生态建设，加快构建人机协同、虚实结合、泛在可及的智慧教育新形态，促进规模教育与个性培养、知识传授与能力培养、技术应用与人文关怀相统一，着力培育胜任智能时代的高素质人才，为加快建设教育强国、办好人民满意的教育提供强大动能。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　到2030年，人工智能与教育深度融合格局基本形成，构建起纵向贯通、横向联通的人工智能全学段教育和全社会通识教育体系，人工智能人才培养规模与质量显著提升，形成全民人工智能素养培育长效机制。教育教学模式、科研范式、治理模式实现系统性变革，教育服务供给能力和现代化水平大幅增强，基础支撑环境更加集约高效，创新生态体系更加开放协同，智能技术应用更加普惠、安全、高效，形成一批高价值、可推广、可复制的应用场景，智慧教育新形态基本形成、全球影响力进入前列。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">二、推动人工智能人才培养与素养提升</strong></p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　（一）加快普及中小学生的人工智能教育。持续完善《中小学人工智能通识教育指南》，开齐开足开好人工智能相关课程。推动人工智能教育全面纳入地方课程体系，指导各地研制人工智能课程指南，明确各学段课程目标、内容与课时要求。鼓励开展人工智能跨学科教学，推动人工智能教育融入课后服务、研学实践等环节。坚持科技教育与人文教育相结合，注重学生的启智、心灵的培养，引导学生科学认识、合理利用智能技术，提升学生智能素养，激发学生好奇心，培养创新思维，提高认知思考和解决复杂问题的能力。建强中小学人工智能教育基地，支持农村、边远地区学校利用国家平台开好人工智能课程。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　（二）培育面向智能时代的高层次人才。推动人工智能成为高校公共基础课，按学科专业分类编写课程教材，推动全体学生掌握人工智能知识。根据人工智能技术特点，打造“短实新”的前沿创新课程。优化传统学科专业人才培养方案，指导高校开设人工智能交叉融合课程，丰富跨学科、跨专业课程群，培养复合型交叉人才。根据产业结构智能升级优化调整学科专业设置，新设一批适应新技术、新产业、新业态的学科专业。整合高水平研究型大学、科技领军企业、国家实验室等力量，深化学科交叉、产教融合、科教融汇，探索人工智能拔尖创新人才培养新模式。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　（三）推动职业教育传统专业的升级转型。及时研判人工智能对职业教育的结构性影响，调整优化技能型人才培养要求，推动传统专业智能化升级，科学设计“人工智能+”专业体系、课程体系、教学体系，提高专业设置对产业发展的适配性。对接国家人工智能产业发展需求，立足培育新兴产业和未来产业，实施人工智能领域高技能人才集群培养计划，联合行业企业制定人才培养方案，更新课程体系，共建实习、实训、实践基地，有针对性培养新兴岗位高技能人才。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　（四）促进全社会的人工智能通识教育。持续丰富国家平台的数字资源，汇聚开发人工智能通识教育资源，鼓励高校和企业开发人工智能专业特色资源，面向广大师生和社会学习者开放。将人工智能纳入高校学生就业能力提升“双千”计划，鼓励开设相关微专业课程和微证书项目，助力高水平就业。发挥高校和开放大学体系作用，面向重点群体定制开发人工智能素养和技能课程，提供个性职后培训服务，推动有关学习成果纳入学分银行。优化调整学历继续教育专业布局和人才培养方案，支持自学考试开设人工智能相关专业。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　（五）提高广大教师的智能素养与技能。制定教师智能素养标准，明确教师应具备的人工智能素养能力。根据不同岗位需求分层分类开展人工智能素养培训，通过多种方式实现全覆盖。构建情境化测评系统，开发智能化、梯度化的测评工具，鼓励各地各校开展规模化的教师素养测评，根据测评结果针对性地提升教师素养和能力。推动师范生培养改革，将人工智能等前沿技术知识纳入课程体系，更新知识体系。将人工智能纳入教师资格考试和认证内容，在国家及省级教学成果奖中设立智能教育项目，激发人工智能创新的内生动力。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">三、促进人工智能与教育深度广泛融合</strong></p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　（六）利用人工智能赋能学生学习。立足促进德智体美劳全面发展，研发智能学伴。研发思政大模型，丰富智能思政应用，建立全息、全域、全员、全时的沉浸式思政育人模式。建设学生数字档案，根据学生能力、特质和爱好，动态优化学习路径，更好满足多元化学习需求。探索人工智能赋能体育、美育、劳动教育、科技教育等有效路径，帮助学生个性成长。推动智能技术在中西部地区、乡村学校的应用，帮助学生开展自主学习，推广国家通用语言文字，促进教育优质均衡。研发应用智能辅具，支撑特殊教育学生的监测、评估和康复训练，促进教育全纳包容发展。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　（七）利用人工智能赋能教师教学。围绕课前、课中、课后教育教学全过程，加强智能教学系统应用，为教师减负增效。支撑教师课前备课，辅助教师开展学情分析，支撑多模态教学资源自动生成、方案优化和教学过程模拟，实现人机共创备课。探索人机协同教学模式，利用智能系统参与教学环节，开发强交互虚拟仿真实验，提升沉浸式体验和个性评价反馈，提升课堂育人质效。辅助教师开展作业管理，推进智能批改、答疑和辅导。利用智能技术分析课堂教学行为，开展人工智能循证教研实践，构建适应智能时代的教师研修模式，帮助教师提升教学质量。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　（八）利用人工智能赋能教育治理。围绕便捷服务、精准管理、科学决策，打造教育智能大脑。建设国家人才供需对接大数据平台，开展人才需求调查、预测分析和评价反馈。利用智能技术科学预测人口变化和产业发展趋势，健全资源统筹调配和学科专业设置调整机制。推动智能命题、智能组卷、智能监考、智能评卷等应用。研发教育评价智能化工具，探索开展学生学习全过程纵向评价、德智体美劳全要素横向评价。打造智能化就业服务系统，实现大学生就业岗位智能推荐，促进高校毕业生高质量充分就业。高效分析海量多模态监测数据，提升校园安全风险实时预警、应急处置能力，支撑平安校园建设。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　（九）利用人工智能赋能科学研究。围绕自然科学、工程科学和哲学社会科学，探索以揭榜挂帅等形式，建设并推广科学智能体和智能工具，帮助科研人员发现、总结规律，解决复杂问题。建设人工智能学科交叉创新平台，强化人工智能牵引的多学科融合发展，拓展知识边界，加快探索智能时代科研新范式。推动基础科研平台和科技基础设施智能升级，建设智能实验室和自主实验集群，实现自动化设计实验方案、开展实验操作、分析实验数据，提高科研创新效率。深化高校科技成果交易平台“科交汇”智能体应用，实现企业需求智能感知和转化成果智能匹配，培育新质生产力。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">四、建强“人工智能+教育”基础环境</strong></p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　（十）构筑集约高效的智能教育基座。建设国家教育智能算力服务平台，有效汇聚算力、数据、模型、工具等人工智能创新资源。用好教育和科研计算机网，连接国家算力训练场、国家算力枢纽、企业和高校，整合各方智算、通算和超算资源。鼓励省级教育行政部门利用全国一体化算力网，为人工智能应用提供算力保障。围绕思政教育、学科知识、科学研究等方向，组织开发国家基础语料库，鼓励地方和高校开发领域特色数据集。建强国家教育大数据中心，建立跨部门、跨地域、跨平台的数据网络，探索基于平台、期刊、终端等数据动态更新机制。国家开展有组织攻关，分教育阶段研发人工智能教育大模型，强化价值对齐、逻辑推理、安全伦理等能力，为地方和高校应用提供支撑，有效避免资源浪费和低水平重复建设。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　（十一）培育共创共享的智能应用体系。深入推动国家平台智能升级，实现资源个性推送、服务智能办理、数据智能分析。建立高等学校和中小学的协同贯通机制，共同研制人工智能课程，共同开发人工智能应用。布局建设国家人工智能（教育）应用中试基地，提供学生知识、能力和素质图谱等公共产品，降低应用创新门槛，培育应用服务体系，加快智能产品与服务落地。建设人工智能学习社区，汇聚开源课程，提供创新资源，开展成果认证，鼓励师生参与开源生态建设，实现语料共建、模型共测、应用共创，持续培育优质的教育智能应用。建立智能应用能力评估体系，遴选面向不同教育角色、不同应用场景的教育智能体，择优上线国家平台。组织人工智能先导应用场景项目，打造一批高价值的标杆应用。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　（十二）打造虚实融合的未来教育空间。打造未来课堂、未来学校、未来学习中心和未来实训中心，打通人工智能应用“最后一公里”。在重点学科领域布局教学和实践能力中心，打造精品人工智能交叉课程和实践项目，支撑学科智能升级。试点研发数字教材，推出新一代智慧慕课，深化虚拟仿真实验建设，丰富数字教育资源形态，构建沉浸式的教学空间，构建人机协同的教学新模式。推动智能终端应用，通过大数据分析构建学生用户画像，以学生为中心配置学习资源，支撑规模教育下的个性学习。整合教育大模型和智能体工具，打造一批主题式学习场景，推动项目式、探究式、场景式育人，引导学生学会思考，培养胜任智能时代的能力。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">五、优化“人工智能+教育”发展生态</strong></p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　（十三）开展“人工智能+教育”的研究创新。推动人工智能与认知科学、脑科学、心理学、教育学等多学科领域交叉，创新教育研究范式，深化对教育规律、认知发展等理解。持续开展人工智能社会实验，深化人工智能伦理研究，科学评估技术对教育的影响。构建“人工智能+教育”的技术创新体系，建强联合攻关平台和教育实践研究基地，组织开展共性关键技术攻关，鼓励高校、企业、科研院所参与“人工智能+教育”生态建设，引导国有和社会的长期资本、耐心资本、战略资本投入教育科技创新，推动更多先进技术服务于人的发展。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　（十四）加强“人工智能+教育”的条件保障。加强人工智能教育培训、应用创新、技术研发、安全保障等方面的制度，构建适应人工智能发展要求的教育政策制度体系。鼓励教育机构、企业、科研单位聚焦教育行业人工智能应用、大模型评测、数据安全等研制一批标准规范。创新人才队伍建设模式，引进高校、企业人才参与开发建设，培育一支复合型、高水平的工程技术团队。支持鼓励通过购买服务等方式创新投入模式，构建政府主导，高校、社会、企业共同参与的多元投入机制。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　（十五）促进“人工智能+教育”国际合作。持续举办世界数字教育大会、世界慕课与在线教育大会、国际人工智能与教育会议等国际会议，建强人工智能开放联盟、世界数字教育联盟、世界慕课与在线教育联盟，打造系列国际交流旗舰平台。充分发挥双边及多边机制，分国别、分区域推进教育国际合作，共享多语种人工智能课程、教育大模型和智能体，加强优质教育资源和经验互学互鉴。积极参加全球教育治理，依托联合国教科文组织等重要国际组织平台，深度参与人工智能教育领域国际议程、规则和标准制定，不断提升我国数字教育国际影响力。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　（十六）筑牢“人工智能+教育”安全屏障。建立人工智能教育应用的安全防护体系，分类分级确定安全防护标准。深化建立教育大模型安全审核机制，确保生成内容积极健康、向上向善。建立人工智能教育应用的安全测评标准，一体保障模型算法、数据资源、基础设施、应用系统等安全，确保技术应用符合教育规律。推动软件正版化，保障人工智能应用安全、可信、可控。强化人工智能进校园管理，明确智能产品、终端的应用规范。健全人工智能评估备案、技术监测、风险预警、应急响应机制，有效防范利用人工智能伪造诈骗、学术造假、应试内卷、泄露隐私等问题。</p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">六、组织实施</strong></p><p style="margin: 0px; padding: 16px 0px; border: 0px; overflow: hidden; color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);">　　坚持把党的领导贯彻到“人工智能+教育”全过程，强化组织领导、统筹谋划、指导监督和条件保障。教育部门负责制定行动计划，统筹推进实施；发展改革部门加强统筹协调，支持符合要求的项目建设；科技部门负责加强重点领域科研布局；工业和信息化、数据管理部门负责提供政策支持，促进开源开放和数据互联互通。各地各校要将“人工智能+教育”纳入发展规划，制定符合自身实际的实施方案，积极开展应用示范。加强智库与咨询机构建设，加强政策战略研究、一线工作指导和建言献策。组织开展专题培训，提升管理干部的人工智能领导力。深入实施人工智能赋能教育行动试点，构建基于数据的常态化应用监督机制，及时总结宣传优秀经验做法。</p>', NULL, '本站', '教育部等五部门关于印发《“人工智能+教育”行动计划》的通知教科信〔2026〕1号现将《“人工智能+教育”行动计划》印发给你们，请认真贯彻落实。教 育 部 国家发展改革委 工业和信息化部科技部 国家数据局2026年4月2日“人工智能+教育”行动计划根据《教育强国建设规划纲要（2024—2035年）》战略', 1, 255, 1, '2026-04-28 09:04:47', '2026-04-28 09:07:20', '2026-04-28 09:07:27');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('赋能绿色低碳人才培育 川渝地区2025年碳排放管理员职业技能培训班开班', '<p data-t="{&quot;n&quot;:&quot;blueLinks&quot;,&quot;t&quot;:13,&quot;a&quot;:&quot;click&quot;,&quot;b&quot;:76}" style="margin-top: 0px; margin-bottom: 16px; color: rgb(36, 36, 36); font-family: &quot;Segoe UI&quot;, &quot;Segoe UI Midlevel&quot;, sans-serif; font-size: 17px; text-wrap-mode: wrap; background-color: rgb(247, 247, 247);">9月17日，由中国（重庆）职业技能公共实训中心（以下简称“实训中心”）、重庆市应对气候变化发展中心（重庆资源与环境交易中心）、四川能投双碳产业发展有限公司、重庆联合产权交易所集团股份有限公司联合举办的川渝地区2025年碳排放管理员职业技能培训班在实训中心开班。本次培训课程以“线上+线下”融合教学模式，吸引了川渝两地环保、电力、造纸等重点行业50余名企业骨干参与，为区域绿色低碳发展注入专业技能人才动力。</p><div class="article-image-slot image-slot-placeholder" data-doc-id="cms/api/amp/image/AA1MN2oH" style="color: rgb(36, 36, 36); font-family: &quot;Segoe UI&quot;, &quot;Segoe UI Midlevel&quot;, sans-serif; font-size: 17px; text-wrap-mode: wrap; background-color: rgb(247, 247, 247);"><slot name="AA1MN6Xd-image-cms/api/amp/image/AA1MN2oH"><div slot="AA1MN6Xd-image-cms/api/amp/image/AA1MN2oH" class="article-image-slot"><cp-article-image style="color: rgb(38, 38, 38);"><div class="article-image-container polished" data-t="{&quot;n&quot;:&quot;OpenModal&quot;,&quot;t&quot;:13,&quot;b&quot;:8,&quot;c.i&quot;:&quot;AA1MN6Xd&quot;,&quot;c.l&quot;:false,&quot;c.t&quot;:13,&quot;c.v&quot;:&quot;news&quot;,&quot;c.c&quot;:&quot;others&quot;,&quot;c.b&quot;:&quot;上游新闻&quot;,&quot;c.bi&quot;:&quot;AA1itK1K&quot;,&quot;c.tv&quot;:&quot;education-and-learning&quot;,&quot;c.tc&quot;:&quot;general&quot;,&quot;c.hl&quot;:&quot;赋能绿色低碳人才培育 川渝地区2025年碳排放管理员职业技能培训班开班&quot;}" data-test-id="AA1MN2oH" style="position: relative; margin: 0px 0px 8px; width: 874px; height: 100%;"><button data-customhandled="true" class="article-image-height-wrapper expandable article-image-height-wrapper-new" data-t="{&quot;n&quot;:&quot;OpenModalButton&quot;,&quot;a&quot;:&quot;click&quot;,&quot;b&quot;:1,&quot;c.i&quot;:&quot;AA1MN6Xd&quot;,&quot;c.l&quot;:false,&quot;c.t&quot;:13,&quot;c.v&quot;:&quot;news&quot;,&quot;c.c&quot;:&quot;others&quot;,&quot;c.b&quot;:&quot;上游新闻&quot;,&quot;c.bi&quot;:&quot;AA1itK1K&quot;,&quot;c.tv&quot;:&quot;education-and-learning&quot;,&quot;c.tc&quot;:&quot;general&quot;,&quot;c.hl&quot;:&quot;赋能绿色低碳人才培育 川渝地区2025年碳排放管理员职业技能培训班开班&quot;}" style="width: inherit; display: block; appearance: none; padding: 0px; border-width: initial; border-style: none; border-color: initial; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; position: relative; overflow: hidden; border-radius: 6px; z-index: 1; outline-offset: -2px; cursor: zoom-in; height: 431px;"><div style="background: url(&quot;https://img-s.msn.cn/tenant/amp/entityid/AA1MN2oH.img?w=768&amp;h=431&amp;m=6&quot;) center center / cover no-repeat; filter: blur(90px); height: 431px; z-index: -1; position: relative;"></div><img class="article-image article-image-ux-impr article-image-new expandable" src="https://img-s.msn.cn/tenant/amp/entityid/AA1MN2oH.img?w=768&h=431&m=6" alt=" 赋能绿色低碳人才培育 川渝地区2025年碳排放管理员职业技能培训班开班 " title=" 赋能绿色低碳人才培育 川渝地区2025年碳排放管理员职业技能培训班开班 " loading="eager" style="border-radius: 6px; position: absolute; top: 0px; bottom: 0px; left: 437px; transform: translateX(-50%); vertical-align: middle; object-fit: contain; background: rgb(242, 242, 242); transform-origin: 0px 0px; z-index: -1; width: auto !important;"/></button><div class="image-caption-container image-caption-container-ux-impr articlewc-image-caption-container" style="display: flex; font-size: 12px; line-height: 16px; padding: 12px 16px 8px 24px; flex-flow: column; gap: normal;"><span class="image-caption" style="color: #242424;">赋能绿色低碳人才培育 川渝地区2025年碳排放管理员职业技能培训班开班</span></div></div></cp-article-image></div></slot></div><p data-t="{&quot;n&quot;:&quot;blueLinks&quot;,&quot;t&quot;:13,&quot;a&quot;:&quot;click&quot;,&quot;b&quot;:76}" style="margin-top: 0px; margin-bottom: 16px; color: rgb(36, 36, 36); font-family: &quot;Segoe UI&quot;, &quot;Segoe UI Midlevel&quot;, sans-serif; font-size: 17px; text-wrap-mode: wrap; background-color: rgb(247, 247, 247);">开班仪式上，公共实训中心相关负责人表示，此次培训是积极响应国家“双碳”战略和实施“技能照亮前程”培训行动的具体举措，将有力促进碳排放管理员人才队伍建设。培训结束后，还将组织西南地区首次碳排放管理员职业技能认定工作，完善“培训+评价+就业”闭环服务体系。四川能投双碳产业发展有限公司董事长陈翔表示，作为四川能源发展集团旗下专注“双碳”产业发展的专业公司，将充分发挥产业优势，与重庆各方携手打造川渝绿色人才培养高地，未来，还将拓展更多层次、更多工种的“双碳”技能培训，推动两地人才链与产业链深度融合。重庆市应对气候变化发展中心（重庆资源与环境交易中心）副主任李新宇介绍，本次培训班师资力量雄厚权威，整合了重庆在碳交易、环境管理领域的技术积累与四川的能源产业资源，将为成渝地区双城经济圈绿色低碳发展输送“实战型”人才。</p><div class="article-image-slot image-slot-placeholder" data-doc-id="cms/api/amp/image/AA1MN2oN" style="color: rgb(36, 36, 36); font-family: &quot;Segoe UI&quot;, &quot;Segoe UI Midlevel&quot;, sans-serif; font-size: 17px; text-wrap-mode: wrap; background-color: rgb(247, 247, 247);"><slot name="AA1MN6Xd-image-cms/api/amp/image/AA1MN2oN"><div slot="AA1MN6Xd-image-cms/api/amp/image/AA1MN2oN" class="article-image-slot"><cp-article-image style="color: rgb(38, 38, 38);"><div class="article-image-container polished" data-t="{&quot;n&quot;:&quot;OpenModal&quot;,&quot;t&quot;:13,&quot;b&quot;:8,&quot;c.i&quot;:&quot;AA1MN6Xd&quot;,&quot;c.l&quot;:false,&quot;c.t&quot;:13,&quot;c.v&quot;:&quot;news&quot;,&quot;c.c&quot;:&quot;others&quot;,&quot;c.b&quot;:&quot;上游新闻&quot;,&quot;c.bi&quot;:&quot;AA1itK1K&quot;,&quot;c.tv&quot;:&quot;education-and-learning&quot;,&quot;c.tc&quot;:&quot;general&quot;,&quot;c.hl&quot;:&quot;赋能绿色低碳人才培育 川渝地区2025年碳排放管理员职业技能培训班开班&quot;}" data-test-id="AA1MN2oN" style="position: relative; margin: 0px 0px 8px; width: 874px; height: 100%;"><button data-customhandled="true" class="article-image-height-wrapper expandable article-image-height-wrapper-new" data-t="{&quot;n&quot;:&quot;OpenModalButton&quot;,&quot;a&quot;:&quot;click&quot;,&quot;b&quot;:1,&quot;c.i&quot;:&quot;AA1MN6Xd&quot;,&quot;c.l&quot;:false,&quot;c.t&quot;:13,&quot;c.v&quot;:&quot;news&quot;,&quot;c.c&quot;:&quot;others&quot;,&quot;c.b&quot;:&quot;上游新闻&quot;,&quot;c.bi&quot;:&quot;AA1itK1K&quot;,&quot;c.tv&quot;:&quot;education-and-learning&quot;,&quot;c.tc&quot;:&quot;general&quot;,&quot;c.hl&quot;:&quot;赋能绿色低碳人才培育 川渝地区2025年碳排放管理员职业技能培训班开班&quot;}" style="width: inherit; display: block; appearance: none; padding: 0px; border-width: initial; border-style: none; border-color: initial; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; position: relative; overflow: hidden; border-radius: 6px; z-index: 1; outline-offset: -2px; cursor: zoom-in; height: 431px;"><div style="background: url(&quot;https://img-s.msn.cn/tenant/amp/entityid/AA1MN2oN.img?w=768&amp;h=431&amp;m=6&amp;x=1070&amp;y=293&amp;s=40&amp;d=40&quot;) center center / cover no-repeat; filter: blur(90px); height: 431px; z-index: -1; position: relative;"></div><img class="article-image article-image-ux-impr article-image-new expandable" src="https://img-s.msn.cn/tenant/amp/entityid/AA1MN2oN.img?w=768&h=431&m=6&x=1070&y=293&s=40&d=40" alt="赋能绿色低碳人才培育 川渝地区2025年碳排放管理员职业技能培训班开班" title="赋能绿色低碳人才培育 川渝地区2025年碳排放管理员职业技能培训班开班" loading="eager" style="border-radius: 6px; position: absolute; top: 0px; bottom: 0px; left: 437px; transform: translateX(-50%); vertical-align: middle; object-fit: contain; background: rgb(242, 242, 242); transform-origin: 0px 0px; z-index: -1; width: auto !important;"/></button><div class="image-caption-container image-caption-container-ux-impr articlewc-image-caption-container" style="display: flex; font-size: 12px; line-height: 16px; padding: 12px 16px 8px 24px; flex-flow: column; gap: normal;"><span class="image-caption" style="color: #242424;">赋能绿色低碳人才培育 川渝地区2025年碳排放管理员职业技能培训班开班</span></div></div></cp-article-image></div></slot></div><div class="article-image-slot image-slot-placeholder" data-doc-id="cms/api/amp/image/AA1MMTaW" style="color: rgb(36, 36, 36); font-family: &quot;Segoe UI&quot;, &quot;Segoe UI Midlevel&quot;, sans-serif; font-size: 17px; text-wrap-mode: wrap; background-color: rgb(247, 247, 247);"><slot name="AA1MN6Xd-image-cms/api/amp/image/AA1MMTaW"><div slot="AA1MN6Xd-image-cms/api/amp/image/AA1MMTaW" class="article-image-slot"><cp-article-image style="color: rgb(38, 38, 38);"><div class="article-image-container polished" data-t="{&quot;n&quot;:&quot;OpenModal&quot;,&quot;t&quot;:13,&quot;b&quot;:8,&quot;c.i&quot;:&quot;AA1MN6Xd&quot;,&quot;c.l&quot;:false,&quot;c.t&quot;:13,&quot;c.v&quot;:&quot;news&quot;,&quot;c.c&quot;:&quot;others&quot;,&quot;c.b&quot;:&quot;上游新闻&quot;,&quot;c.bi&quot;:&quot;AA1itK1K&quot;,&quot;c.tv&quot;:&quot;education-and-learning&quot;,&quot;c.tc&quot;:&quot;general&quot;,&quot;c.hl&quot;:&quot;赋能绿色低碳人才培育 川渝地区2025年碳排放管理员职业技能培训班开班&quot;}" data-test-id="AA1MMTaW" style="position: relative; margin: 0px 0px 8px; width: 874px; height: 100%;"><button data-customhandled="true" class="article-image-height-wrapper expandable article-image-height-wrapper-new" data-t="{&quot;n&quot;:&quot;OpenModalButton&quot;,&quot;a&quot;:&quot;click&quot;,&quot;b&quot;:1,&quot;c.i&quot;:&quot;AA1MN6Xd&quot;,&quot;c.l&quot;:false,&quot;c.t&quot;:13,&quot;c.v&quot;:&quot;news&quot;,&quot;c.c&quot;:&quot;others&quot;,&quot;c.b&quot;:&quot;上游新闻&quot;,&quot;c.bi&quot;:&quot;AA1itK1K&quot;,&quot;c.tv&quot;:&quot;education-and-learning&quot;,&quot;c.tc&quot;:&quot;general&quot;,&quot;c.hl&quot;:&quot;赋能绿色低碳人才培育 川渝地区2025年碳排放管理员职业技能培训班开班&quot;}" style="width: inherit; display: block; appearance: none; padding: 0px; border-width: initial; border-style: none; border-color: initial; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; position: relative; overflow: hidden; border-radius: 6px; z-index: 1; outline-offset: -2px; cursor: zoom-in; height: 431px;"><div style="background: url(&quot;https://img-s.msn.cn/tenant/amp/entityid/AA1MMTaW.img?w=768&amp;h=431&amp;m=6&quot;) center center / cover no-repeat; filter: blur(90px); height: 431px; z-index: -1; position: relative;"></div><img class="article-image article-image-ux-impr article-image-new expandable" src="https://img-s.msn.cn/tenant/amp/entityid/AA1MMTaW.img?w=768&h=431&m=6" alt="赋能绿色低碳人才培育 川渝地区2025年碳排放管理员职业技能培训班开班" title="赋能绿色低碳人才培育 川渝地区2025年碳排放管理员职业技能培训班开班" loading="eager" style="border-radius: 6px; position: absolute; top: 0px; bottom: 0px; left: 437px; transform: translateX(-50%); vertical-align: middle; object-fit: contain; background: rgb(242, 242, 242); transform-origin: 0px 0px; z-index: -1; width: auto !important;"/></button><div class="image-caption-container image-caption-container-ux-impr articlewc-image-caption-container" style="display: flex; font-size: 12px; line-height: 16px; padding: 12px 16px 8px 24px; flex-flow: column; gap: normal;"><span class="image-caption" style="color: #242424;">赋能绿色低碳人才培育 川渝地区2025年碳排放管理员职业技能培训班开班</span></div></div></cp-article-image></div></slot></div><p data-t="{&quot;n&quot;:&quot;blueLinks&quot;,&quot;t&quot;:13,&quot;a&quot;:&quot;click&quot;,&quot;b&quot;:76}" class="continue-read-break" style="opacity: 1; position: static; margin-top: 0px; margin-bottom: 16px; color: rgb(36, 36, 36); font-family: &quot;Segoe UI&quot;, &quot;Segoe UI Midlevel&quot;, sans-serif; font-size: 17px; text-wrap-mode: wrap; background-color: rgb(247, 247, 247);">此次培训的成功举办，为川渝两地“双碳”技能人才培养蹚出一条新路径，既是响应“技能照亮前程”培训行动的生动实践，也是川渝深化技能合作、共筑人才梯队的重要探索。下一步，实训中心将坚持人才与产业链需求导向，推行“岗位需求+技能培训+技能评价+就业服务”四位一体培训模式，助力更多劳动者通过技能提升实现高质量充分就业，让技能成为点亮个人前程、服务产业转型的重要力量。（资讯）<slot name="cont-read-break"></slot></p><p data-t="{&quot;n&quot;:&quot;blueLinks&quot;,&quot;t&quot;:13,&quot;a&quot;:&quot;click&quot;,&quot;b&quot;:76}" style="margin-top: 0px; margin-bottom: 16px; color: rgb(36, 36, 36); font-family: &quot;Segoe UI&quot;, &quot;Segoe UI Midlevel&quot;, sans-serif; font-size: 17px; text-wrap-mode: wrap; background-color: rgb(247, 247, 247);">文图/杨晓玉</p>', NULL, '本站', '9月17日，由中国（重庆）职业技能公共实训中心（以下简称“实训中心”）、重庆市应对气候变化发展中心（重庆资源与环境交易中心）、四川能投双碳产业发展有限公司、重庆联合产权交易所集团股份有限公司联合举办的川渝地区2025年碳排放管理员职业技能培训班在实训中心开班。本次培训课程以“线上+线下”融合教学模式，吸引了', 1, 255, 1, '2025-09-19 16:24:08', '2025-09-19 16:29:35', '2025-09-19 16:29:35');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('人力资源社会保障部 中央网信办关于进一步加强人力资源市场规范管理的通知', '<div style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">人社部发〔2024〕62号</div><div style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">各省、自治区、直辖市及新疆生产建设兵团人力资源社会保障厅（局）、网信办：</div><p style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　为贯彻落实党中央、国务院关于健全统一规范的人力资源市场体系、加强市场监管和劳动保障监察执法部署要求，进一步规范人力资源市场活动，维护人力资源市场良好秩序，推动人力资源服务机构诚实守信、依法履责，切实保障劳动者和用人单位合法权益，现就加强人力资源市场规范管理有关事项通知如下：</p><p style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　一、加强人力资源市场准入管理。各地人力资源社会保障部门要贯彻落实建设全国统一大市场要求，健全人力资源市场准入制度，规范实施告知承诺制，简化优化行政许可，积极推广电子证书。加强部门间监管信息互联互通，会同网信等部门对有关公众号、APP、短视频、互联网群组等网站平台开展职业中介活动进行筛查、甄别，督促指导开展职业中介活动的市场主体依法申请许可，避免出现监管盲区。结合监督检查、专项行动等加强对告知承诺事项真实性核查，对不符合许可条件的依法撤销许可。对未经许可擅自开展职业中介活动的，依法予以关闭或责令停止从事职业中介活动，有违法所得的没收违法所得并处罚款；涉及未经许可开展网络招聘服务的，网信部门根据人力资源社会保障部门的意见，依法依规对相关网站平台进行处置。</p><p style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　二、严格网络招聘服务监管。各地人力资源社会保障部门要进一步完善网络招聘服务监管制度，健全部门间协同监管机制，加强网上预警监测。严格招聘信息管理，督导网络招聘服务机构落实招聘信息审核责任，规范审核流程，加强审核人员管理，切实保障招聘信息真实、合法。强化数据安全，落实数据分级分类保护要求，指导网络招聘服务机构安全管理人力资源服务有关数据。强化个人信息保护，督导大型网络招聘服务机构完善技防、人防、制防一体化信息保护措施，引导接入国家网络身份认证公共服务平台，为用户提供安全、便捷的非明文身份登记和核验服务，对外发布或使用涉密、敏感信息前依法进行脱密脱敏处理，有效防范泄密、泄露求职者个人信息等事件发生。规范管理以直播带岗、依托零工平台线上匹配供需等方式开展的职业中介活动，依法打击服务过程中虚假招聘等违法违规行为。对发布虚假招聘信息、泄露求职者个人信息等违规行为，人力资源社会保障部门会同网信等部门，综合运用责令改正、处置账号、下架移动应用程序、暂停招聘服务、关闭平台或网站等措施依法处置。</p><p style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　三、加强对就业歧视行为监管。各地人力资源社会保障部门要完善招聘信息管理制度，推行招聘信息规范格式，防止用人单位和人力资源服务机构发布含有性别、年龄、学历等方面歧视性内容的招聘信息。加强监督检查和动态监测，定期检查或抽查用人单位和人力资源服务机构发布的招聘信息，运用互联网、大数据等技术对就业歧视有关关键词开展线上监测，针对性跟踪调查、督促提醒。加大惩处力度，对发布含有歧视性内容招聘信息的人力资源服务机构，依法采取行政约谈、通报曝光、没收违法所得、罚款等措施，情节严重的依法吊销其人力资源服务许可证。</p><p style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　四、强化现场招聘安全管理。各地人力资源社会保障部门要严格落实管行业必须管安全、管业务必须管安全要求，增强现场招聘安全管理意识，严格属地管理责任，细化安全管理措施，确保各类现场招聘安全有序。压实举办单位的主体责任，制定组织实施办法、应急预案和安全保卫工作方案，严格落实公安、消防安全等要求，防止招聘现场发生踩踏、疫情、火灾等安全和自然灾害事件。加强招聘现场管理，建立实施巡查制度，督促举办单位合理匹配场地面积、招聘规模与展位数量，足量配备现场工作人员，合理把控入场人数。健全安全管理长效机制，建立总结评估制度，梳理分析存在的薄弱环节和风险隐患，持续提升现场招聘管理工作科学化、规范化水平。</p><p style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　五、规范市场服务收费行为。各地人力资源社会保障部门要健全人力资源服务收费监测机制，探索建立人力资源服务收费目录清单，收集、发布经营性人力资源服务机构收费标准，督促经营性人力资源服务机构在其服务场所及所属网站等平台上明示收费标准，在服务台账记录服务收费等情况，有效维护市场服务收费秩序。对经营性人力资源服务机构以“内部推荐”等为名收取高额费用、介绍挂靠“残疾人证”牟取不正当利益、诱导个人参与贷款、以培训等名目设置求职招聘陷阱骗取财物等违规行为，人力资源社会保障部门会同相关部门依法查处，探索实施“一线多查”、“一案多查”，健全案件移送、行刑衔接等机制，形成有力震慑。</p><p style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　六、强化市场活动综合监管。各地人力资源社会保障部门要落实属地监管责任，综合运用现场监管、线上巡查、信用监管、协同监管、宣传引导等措施，加强辖区内人力资源市场活动管理。加强人力资源服务机构名录库建设，及时采集、公布依法取得许可或者经过备案的经营性人力资源服务机构名单及其变更、注销等信息，并提供查询服务。强化日常监管，制定实施“双随机、一公开”监督检查计划，探索实施网格化管理，分期实现对辖区内人力资源服务机构日常监督检查全覆盖。加强重点监管，对举报投诉多、违法违规线索反映集中或涉案在查的有关单位，采取加大检查频次、联合检查等管理措施。创新监管方式，运用大数据等技术主动发现和识别违法违规线索，对有多次投诉或不良评价的监管对象实施风险预警，做到早发现早处置。健全人力资源市场监管与监察执法协作机制，对监管中发现的涉行政处罚的线索案件移送监察机构处理，监察执法中发现的违规行为和查处情况及时通报监管机构，形成齐抓共管工作格局。加强劳动保障监察执法，畅通举报投诉渠道，适时开展专项执法行动，集中整治相关突出违法问题，依法打击人力资源市场各类违法违规行为。</p><p style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　七、加强对求职者教育引导。各地人力资源社会保障部门要加强政策宣传，广泛宣传解读就业促进法、《人力资源市场暂行条例》、《网络招聘服务管理规定》、《人力资源服务机构管理规定》等法规制度，发布违规典型案例、求职风险提示，提升求职者防范识别能力和自身权益保护意识。开展诚信教育，充分利用人力资源市场、人力资源服务产业园等服务窗口，开展标准化、规范化、便捷化的信用知识教育，提高求职者诚信意识。探索加强求职者职业信用管理，对求职者有关身份、学历、经历等造假以及考试作弊、职业骗薪等情节严重、影响恶劣的行为，协同有关部门依法实施信用约束。</p><p style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><div style="margin: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">　　各地要高度重视人力资源市场管理工作，加强组织领导，强化责任担当，坚持守土有责、守土尽责，积极探索创新，细化监管措施，强化跟踪问效，推动工作落实，积极营造人力资源市场良好环境，更好促进就业创业和人才顺畅有序合理流动。</div>', '/static/upload/image/20251119/1763543400740383.jpg', '本站', '人社部发〔2024〕62号各省、自治区、直辖市及新疆生产建设兵团人力资源社会保障厅（局）、网信办：为贯彻落实党中央、国务院关于健全统一规范的人力资源市场体系、加强市场监管和劳动保障监察执法部署要求，进一步规范人力资源市场活动，维护人力资源市场良好秩序，推动人力资源服务机构诚实守信、依法履责，切实保障劳', 1, 255, 1, '2025-07-14 21:40:51', '2025-07-17 21:41:32', '2025-11-19 17:10:34');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('多部门联手 开展民企员工职业技能提升行动', '<p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">新华社北京5月3日电&nbsp;&nbsp;《国家发展改革委等部门关于共享公共实训基地开展民营企业员工职业技能提升行动的通知》近日印发。通知提出，从2024年至2027年，加力提效用好公共实训基地，开展百万民企员工职业技能提升行动。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">通知从共享场地设备、建强师傅队伍、开发优质课程、扩大岗前培训、加强在岗培训、深化以赛促训、完善就业帮扶、凝聚工作合力、推广典型经验等9个方面作出安排。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">通知明确，发展改革部门要牵头建立绩效评估体系，根据地方实际确定公共实训基地为民营企业开展的岗前培训和在岗培训规模，力争2024年至2027年，每年培训民营企业员工100万人次以上，持续增强对民营经济发展的支撑带动作用。各级总工会、工商联要强化劳动者培训与企业需求对接，推动共建共享，形成工作合力。参训人员、相关企业和公共实训基地可按规定享受有关资金政策支持。</p>', NULL, '本站', '新华社北京5月3日电《国家发展改革委等部门关于共享公共实训基地开展民营企业员工职业技能提升行动的通知》近日印发。通知提出，从2024年至2027年，加力提效用好公共实训基地，开展百万民企员工职业技能提升行动。通知从共享场地设备、建强师傅队伍、开发优质课程、扩大岗前培训、加强在岗培训、深化以赛促训、', 1, 255, 1, '2025-05-30 21:39:42', '2025-07-17 21:40:14', '2025-07-17 21:40:14');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('北京市推进高校就业创业指导服务站试点建设', '<p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">3月27日，北京工商大学、北京石油化工学院、北京农学院、北京联合大学、北京城市学院5所高校同步举办“京聚英才 职创未来——就业创业指导服务站试点高校联合招聘会”，270余家用人单位提供就业岗位5000余个。本次活动由北京市人力资源社会保障局主办，昌平区、朝阳区、房山区、顺义区、大兴区人力资源社会和保障局协办。北京市5所试点高校就业创业指导服务站将集成求职招聘、就业指导、政策宣讲等就业服务，打通高校毕业生就业服务“最后一公里”。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">昌平区专场创新引入“AI”模拟面试等功能&nbsp;</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">根据北京农学院、华北电力大学等驻昌高校专业特点，昌平区人社局广泛动员北京首农味业集团、北京脑科学与类脑研究所等用人单位，80余家重点企业提供岗位1800余个。同时，活动现场设置职业指导咨询、政策咨询等综合服务专区，编制发放《“英才聚昌”高校毕业生就业服务一览通》，为高校毕业生等青年提供求职就业指引；引入AI智能简历诊断与优化、AI面试模拟、AI表达训练助手等辅助工具；组织本市就业指导名师、企业HR配套开展“一对一”辅导、极速面试等交流活动，助力青年学子把握春招机遇。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">&nbsp;“线上+线下”为毕业生打造全天候就业场景&nbsp;</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">朝阳区、房山区分会场采用“线上+线下”服务模式，为毕业生拓展就业场景，提供全天候服务。朝阳区人社局在北京联合大学招聘会现场设置了三大特色展区：职业指导区、AI赋能区、专家座谈区，30家用人单位提供近700个就业岗位；线上同步开设“宜业朝阳”官方抖音直播间，企业HR云端直播带岗，解读招聘需求并在线答疑。房山区人社局与区司法局紧密联动，征集区内外23家律师事务所、10余家专精特新企业，在北京工商大学提供实习、就业岗位100余个；线下开展“人社、司法局局长进校园”等活动，线上覆盖良乡大学城5所高校法律系毕业生，以校园网络、社群为桥梁，为同学们搭建求职信息交流平台。&nbsp;</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">进校园为高校学子送政策送就业指导&nbsp;</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">顺义区人社局联合怀柔区、平谷区人社局，针对北京城市学院等京籍高校毕业生较多的情况，开展“专家+AI”就业指导、百企千岗进校园等内容丰富的活动，100余家用人单位带来2000余个岗位。大兴区人社局在北京石油化工学院招聘会现场设置了“局长宣讲+就业指导+精准对接”等活动内容，区局副局长李哲现场为毕业生面对面送就业政策、做就业指导；国家级职业指导师宋巍为青年学生讲解当前就业形势，并指导毕业生简历制作、面试技巧等。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">据介绍，下一步，北京市将深化“驻校”服务，依托5所高校就业创业指导服务站试点，提供政策咨询、就业创业指导、岗位推介等服务，加强就业观念引导，提升服务精准性，助力青年学子从校园迈向职场，顺利开启职业生涯新篇章，为经济社会发展源源不断地注入全新活力，推动实现首都高质量充分就业。</p>', NULL, '本站', '3月27日，北京工商大学、北京石油化工学院、北京农学院、北京联合大学、北京城市学院5所高校同步举办“京聚英才 职创未来——就业创业指导服务站试点高校联合招聘会”，270余家用人单位提供就业岗位5000余个。本次活动由北京市人力资源社会保障局主办，昌平区、朝阳区、房山区、顺义区、大兴区人力资源社会和保障局协办。北', 1, 255, 1, '2025-05-30 21:38:22', '2025-07-17 21:39:41', '2025-07-17 21:39:41');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('第二十届中国西部国际博览会在成都开幕', '<div data-v-3c7c6d20="" data-v-670bcc64="" class="app-main" style="padding: 0px; margin: 0px; width: 1200px; overflow: hidden; font-family: &quot;Times New Roman&quot;; font-size: 16px; text-wrap-mode: wrap; background-color: rgb(247, 247, 247);"><div data-v-4cf1aec9="" data-v-3c7c6d20="" class="content clearfix" style="padding: 10px; margin: 20px 0px; zoom: 1; background-color: rgb(255, 255, 255); min-height: 600px;"><div data-v-4cf1aec9="" class="right" style="padding: 0px; margin: 0px; float: right; width: 1180px;"><div data-v-4cf1aec9="" class="detailcontent text-list" style="padding: 20px; margin: 0px; border: 1px solid rgb(220, 220, 220);"><div data-v-4cf1aec9="" class="tong_connr" style="padding: 0px; margin: 0px 0px 20px;"><p style="padding: 0px; margin-top: 0px; margin-bottom: 0px;"><img src="/static/upload/image/20251119/1763543782178960.jpg" width="800" needdownload="true" title="" picname="XxjpsgC007291_20250525_PEPFN0A001.jpg" alt="" oldsrc="W020250525741157056417_ORIGIN.jpg" style="padding: 0px; margin: 0px;" data-catch-result="success"/></p><p style="padding: 0px; margin-top: 0px; margin-bottom: 0px;">这是5月25日拍摄的第二十届中国西部国际博览会开幕式现场。</p><p style="padding: 0px; margin-top: 0px; margin-bottom: 0px;">当日，第二十届中国西部国际博览会在四川省成都市开幕，主题为“深化改革增动能 扩大开放促发展”，由四川省人民政府主办。据了解，本届西博会首次设立匈牙利、老挝双主宾国和浙江、青海双主宾省，共吸引境内外3000余家企业参展，博览会将持续至29日。</p><p style="padding: 0px; margin-top: 0px; margin-bottom: 0px;">新华社记者 刘坤 摄</p><p style="padding: 0px; margin-top: 0px; margin-bottom: 0px;"><img src="/static/upload/image/20251119/1763543784194915.jpg" width="800" needdownload="true" title="" picname="XxjpsgC007289_20250525_PEPFN0A001.jpg" alt="" oldsrc="W020250525741157343987_ORIGIN.jpg" style="padding: 0px; margin: 0px;" data-catch-result="success"/></p><p style="padding: 0px; margin-top: 0px; margin-bottom: 0px;">5月25日，观众在第二十届中国西部国际博览会四川馆参观展出的高等级商用客运航空器模型。</p><p style="padding: 0px; margin-top: 0px; margin-bottom: 0px;">当日，第二十届中国西部国际博览会在四川省成都市开幕，主题为“深化改革增动能 扩大开放促发展”，由四川省人民政府主办。据了解，本届西博会首次设立匈牙利、老挝双主宾国和浙江、青海双主宾省，共吸引境内外3000余家企业参展，博览会将持续至29日。</p><p style="padding: 0px; margin-top: 0px; margin-bottom: 0px;">新华社记者 刘坤 摄</p></div><div data-v-4cf1aec9="" class="bottom" style="padding: 0px; margin: 0px;"><a data-v-4cf1aec9="" href="https://www.rcrzgl.org.cn/textArticleInfo?articleId=1378" class="router-link-active" style="padding: 0px; margin: 0px; outline: 0px; color: rgb(102, 102, 102);"><button data-v-4cf1aec9="" type="button" class="el-button button el-button--text" style="padding: 12px 0px; margin: 0px; user-select: none; display: block; line-height: 1; text-wrap-mode: nowrap; cursor: pointer; background-image: initial; background-position: 0px 0px; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; border-width: 1px; border-style: solid; border-color: transparent; color: rgb(64, 158, 255); appearance: none; outline: 0px; transition: 0.1s; font-weight: 500; font-size: 20px; border-radius: 4px;"><span style="padding: 0px; margin: 0px;">下一篇</span></button></a><button data-v-4cf1aec9="" type="button" class="el-button button el-button--text" style="padding: 12px 0px; margin: 0px; outline: 0px; color: rgb(64, 158, 255); user-select: none; display: block; line-height: 1; text-wrap-mode: nowrap; cursor: pointer; background-image: initial; background-position: 0px 0px; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; border-width: 1px; border-style: solid; border-color: transparent; appearance: none; transition: 0.1s; font-weight: 500; font-size: 20px; border-radius: 4px;"><span style="padding: 0px; margin: 0px;"><a data-v-4cf1aec9="" href="https://www.rcrzgl.org.cn/textArticleInfo?articleId=1357" class="router-link-active" style="padding: 0px; margin: 0px; outline: 0px; color: rgb(102, 102, 102);">上一篇</a></span></button></div></div></div></div></div><div data-v-670bcc64="" style="padding: 0px; margin: 0px; font-family: &quot;Times New Roman&quot;; font-size: 16px; text-wrap-mode: wrap; background-color: rgb(247, 247, 247);"><div class="link clearfix" style="padding: 0px; margin: 20px 0px; zoom: 1;"><ul class="link-1-nav clearfix list-paddingleft-2" style="padding: 0px; zoom: 1; width: 1200px; background-color: rgb(255, 255, 255); overflow: hidden;"></ul></div></div>', '/static/upload/image/20251119/1763543795530037.png', '本站', '6月19日至23日，人力资源社会保障部百日千万招聘专项行动推出实体门店、信息技术、金融业、电力新能源、先进制造、医疗护理6个线上招聘专场，共有1.2万家用人单位参与，招聘需求超6万人。实体门店专场由前程无忧承办，共有伊利、星巴克、华润超市、肯德基、屈臣氏等9530家企业参加，招聘需求超3.3万人，涵盖营业员、门店', 1, 255, 1, '2025-05-26 21:41:34', '2025-07-17 21:45:13', '2025-11-19 17:19:38');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('习近平出席中拉论坛第四届部长级会议开幕式并发表主旨讲话', '<p><span style="font-family: &quot;Times New Roman&quot;; font-size: 40px; font-weight: 700; text-align: center; text-wrap-mode: wrap; background-color: #FFFFFF;">习近平出席中拉论坛第四届部长级会议开幕式并发表主旨讲话</span></p><p><br/></p>', '/static/upload/image/20251119/1763543641585667.png', '本站', '近日，住房城乡建设部、人力资源社会保障部联合发布通知，开展乡村建设工匠（以下简称“工匠”）职业技能等级认定工作，建立完善工匠职业技能等级认定工作机制，优化工匠队伍结构，培育扎根农村、服务农民的工匠队伍。通知从备案等级认定机构、规范开展等级认定、组织开展考评和督导、加强认定机构监督管理、强化等级认定结', 1, 255, 1, '2025-05-16 21:40:16', '2025-07-17 21:40:49', '2026-01-15 16:58:29');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('江西：优化调整政策稳岗扩岗', '<p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">日前，江西省政府办公厅印发《关于优化调整稳就业政策全力促发展惠民生的若干措施》，深入实施就业优先战略，建立常态化援企稳岗帮扶机制，多措并举稳定和扩大就业岗位，全力促发展惠民生。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">支持金融机构开展稳岗扩岗服务和贷款业务、大力推进职业技能培训、支持国有企业扩大招聘规模、稳定机关事业单位岗位规模等16项具体措施，要求各地优化经办服务，推动更多政策直达快享，加速释放政策红利，为就业大局总体稳定提供有力保障。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">为进一步加大对吸纳就业能力强的行业企业扩岗政策支持，《若干措施》明确，为本地区带动就业能力强、涉及国计民生和生产保供的企业配备就业服务专员，建立惠企政策兑现、岗位收集、技能培训、送工上岗等服务机制。大力实施一批以工代赈项目，积极组织当地群众参与工程建设，严格按照政策落实劳务报酬发放，促进当地群众就近就地就业增收。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">针对高校毕业生等重点群体就业，运用“直补快办”等模式，一揽子兑现社会保险补贴、吸纳就业补贴、职业培训补贴等政策。对新招用毕业年度或离校2年内未就业高校毕业生、登记失业的16至24岁青年，签订1年以上劳动合同的企业，按照每人1500元的标准给予一次性吸纳就业补贴。对符合条件的毕业学年困难高校毕业生给予每人1000元的一次性求职补贴。同时，扩大就业见习规模，对吸纳就业见习的单位给予当地最低工资标准80%的就业见习补贴。对当年见习期满留用率达到50%以上的见习单位，补贴标准提高到最低工资标准的100%。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">聚焦高校毕业生、农民工等群体创业需求，支持其创办投资少、风险小的创业项目，从事创意经济、个性化定制化文化业态等特色经营。对有创业意愿的高校毕业生优先推荐入驻政府投资开发的创业载体，按规定给予场地免费、创业担保贷款、创业补贴、政策指导等支持。加大创业担保贷款支持力度，对2023年新签订借款合同(含续贷新发放)的个人创业担保贷款，涉及就业困难人员、返乡创业农民工、高校毕业生、脱贫人口、退捕渔民、复员转业退役军人6类群体的，其原需个人承担利息部分全部予以免除，其他群体原需个人承担利息部分的50%予以免除，政策实施期限截至2023年12月31日</p>', NULL, '本站', '日前，江西省政府办公厅印发《关于优化调整稳就业政策全力促发展惠民生的若干措施》，深入实施就业优先战略，建立常态化援企稳岗帮扶机制，多措并举稳定和扩大就业岗位，全力促发展惠民生。支持金融机构开展稳岗扩岗服务和贷款业务、大力推进职业技能培训、支持国有企业扩大招聘规模、稳定机关事业单位岗位规模等16项具体措', 1, 255, 1, '2025-05-05 21:45:49', '2025-07-17 21:46:26', '2025-07-17 21:46:26');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('“新八级工”有了升级人生', '<p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">“当工人，就要当最好的工人。”领到工装的第一天，20岁的刘劲松在心里默默立下了职业目标。当时，他刚刚从北京石油化工学校毕业。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">27年后，2023年5月7日，第十六届高技能人才表彰大会在北京举行。人力资源和社会保障部（以下简称人社部）公开表彰30名中华技能大奖获得者和295名全国技术能手，中国石化燕山石化炼油厂职工、集团公司技能大师刘劲松作为中华技能大奖获得者参加表彰大会接受现场颁奖。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">2022年6月，我国开始建立并推行“新八级工”制度，开展特级技师、首席技师评聘工作，推进技能人才与专业技术人才贯通发展。“新八级工”制度实施满一年，包括刘劲松等中华技能大奖获得者们在内的“新八级工”感受如何？制度实施过程中，薪酬待遇等有怎样的调整变化？中青报·中青网记者对此进行了采访。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">&nbsp;</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><strong style="margin: 0px; padding: 0px;">这些技能大师的总体薪酬达到直属企业副总师水平</strong><strong style="margin: 0px; padding: 0px;"></strong></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">刘劲松是从基层一线技能操作岗位上成长起来的技能大师。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">2004年，28岁的刘劲松在全国石油石化行业职业技能竞赛中锋芒初露，斩获加氢裂化装置操作工竞赛的第三名。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">全国技术能手、北京市劳动模范……随着荣誉纷至沓来，不少人鼓励刘劲松转为管理岗，他却有自己的坚持，“我愿意扎根一线，干自己喜欢的事情”。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">多年来，他始终在生产一线，专注加氢技术。他为企业提出优化措施11项，累计为企业创造效益近4000万元；解决了高压加氢装置航煤银片腐蚀波动等29项生产难题；累计指导临氢装置16次开停工。刘劲松的名气越来越大，但对他而言，比这些更重要的，是能够用自己的所知所学服务企业、报效国家。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">“老八级工当年在社会上非常受尊重，只要告诉别人，你是一个八级工，就会受到尊重，现在，我们‘新八级工’在各个层面也受到了这种尊重。”刘劲松说。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">八级工是新中国成立之初，伴随工资等级体系建立起来的技能等级制度，从一级工划分到八级工。20世纪80年代中期，原有的八个技能等级被简化为初、中、高三级，高级工相当于原来的八级工。20世纪90年代左右，在高级工的基础上，增设了技师和高级技师，形成了“五级工”制度。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">2022年3月，人社部印发《关于健全完善新时代技能人才职业技能等级制度的意见（试行）》，将原有的五级技能等级延伸为八级，形成由学徒工、初级工、中级工、高级工、技师、高级技师、特级技师、首席技师构成的“新八级工”职业技能等级序列，并建立与职业技能等级（岗位）序列相匹配的岗位绩效工资制，强化工资收入分配的技能价值激励导向，促进实现多劳者多得、技高者多得。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">中国石化党组组织部（人力资源部）人才工作室专家丁新兴介绍，新八级工评定中，重要的做法就是根据岗位价值、人力资本价值确定待遇，将职位层级与薪酬待遇挂钩，对主任技师及以上职位设置高技能津贴，如集团公司技能大师津贴为每人每月4000元，企业首席技师津贴为每人每月2000元。“集团公司技能大师的总体薪酬达到直属企业副总师水平，高于中层管理人员，高技能人才基本实现薪酬水平与市场价位接轨。”丁新兴说。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">“按照新八级工制度，坚持收入分配向关键岗位、核心骨干人才及生产一线技能人才倾斜。”丁新兴介绍，中国石化对当选中华技能大奖、全国技术能手、石化名匠、中国石化技术能手者除给予一次性20万元、10万元、两万元奖励外，还给予激励性年金等中长期奖励。在部分企业实行技能创新成果转化奖励机制，根据开发的技术工具、创新成果应用情况给予相应奖励，如上海石化将高技能人才纳入股票期权激励范围。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">刘劲松说：“我成了单位的首席技师之后，薪资待遇得到了相应的提升，还担任了公司工会兼职副主席。2021年5月，我作为代表参加中共中央国务院召开的政府特殊津贴制度高层次高技能人才座谈会。新八级工制度在企业的落地，给了我满满的获得感。”</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><strong style="margin: 0px; padding: 0px;">“新八级工”制度的出台顺应时代对高级技能人才的需求</strong><strong style="margin: 0px; padding: 0px;"></strong></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">全国人大代表、杭州技师学院90后教师杨金龙15岁开始学习汽车喷漆，21岁在第43届世界技能大赛上拿下汽车喷漆项目金牌。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">这个比赛项目并不简单：需要在陌生的环境中快速掌握未知涂料的属性——标准喷涂厚度0.13毫米，允许上下浮动的误差只有0.01毫米，相当于一根头发直径的1／6左右。喷涂过程中手抖一下，误差都会超过0.01毫米。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">2015年，杨金龙被浙江省人民政府授予浙江省五一劳动奖章，并获浙江省特级技师证书，证书编号0001。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">蒋应成是杨金龙的师弟，同样来自杭州技师学院。2018年3月，蒋应成获得了浙江省特级技师证书，编号0002。他被认定为杭州市B类高层次人才，享受购房补贴，在桐庐买了一套160平方米的住宅。同时获得的还有一系列荣誉：中国五四青年奖章、杭州市五一劳动奖章、杭州工匠、最美浙江人、浙江省五一劳动奖章等。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">2020年，因在世界技能大赛上取得优异成绩，浙江省政府给予杨金龙、蒋应成以及杨金龙的师傅梁思龙3人记个人一等功，培养他们的杭州技师学院获记集体一等功。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">据了解，在杭州技师学院，杭州市D类及以上的高层次人才就有42位，还有20余位省级、国家级技术能手。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">“新八级工制度的出台顺应时代对高级技能人才的需求，会让更多的人向往技能，而不是唯学历导向。”在杭州技师学院院长邵伟军看来，实施“新八级工”制度为人才培育提供了新的方法和途径。除了传统的技能培训外，技工可以通过参加技能评定、职称评定等方式来取得职业技能等级证书和职称。这为有实践经验但学历较低的技工提供了寻求职业发展的路径和晋升的可能，也可以使他们更好地为企业创造价值。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">作为全国人大代表，杨金龙今年参加全国两会时建议，加大技能人才培养激励力度，从国有企业做起，对通过相应技能等级认定的学生给予相应的薪资待遇，在职业晋升中让技师、高级工毕业生享受本科、大专生同等待遇。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">杨金龙在接受中青报·中青网记者采访时说，许多企业在转型升级过程中，高技能人才，尤其是高技能复合型人才的缺口依旧不小，企业“喊渴”表明需要相应的技能人才队伍建设支持，“八级工制度”的推行和落实对于企业留住高技能人才至关重要。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">目前，全国有技工院校2551所，在校生445万人，每年面向社会开展职业技能培训600余万人次。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">邵伟军表示，我国技工院校在社会经济发展中发挥了重要作用。“我们通过项目化、校企合作、精英化三个产教融合培养路径，致力于培育输送‘核心技术骨干、技术创新能手、技术操作能手和技术专家’，建立起一套技工教育特色的卓越技师培养机制。”</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">中国职工教育和职业培训协会学术委员会副主任崔秋立认为，“新八级工”制度将多年来国家和各地在技能等级制度建设方面的探索进行统筹和规范，构成相对完整、相互衔接的技能等级体系，对技能人才起到引导和激励作用。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><strong style="margin: 0px; padding: 0px;">通过培训让技术工人得到成长</strong><strong style="margin: 0px; padding: 0px;"></strong></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">中青报·中青网记者从人社部获悉，“新八级工”职业技能等级制度实施一年来，各地相继出台了配套措施办法，广东、江苏、安徽、河南、云南、重庆等近20个省份组织企业开展特级技师、首席技师评聘工作。同时，中国船舶、中国石油、中国石化、中国兵器工业、中国航天科技、中国航天科工和徐工集团等企业积极开展技能人才自主评价。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">2022年，全国取得职业技能等级证书者超过1100万人次，较2021年增加近87%。评聘特级技师、首席技师近500人。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">江西省景德镇三宝占绍陶瓷文化传播有限公司负责人占绍林是第十六届中华技能大奖获得者。1994年，年仅16岁的占绍林从江西鄱阳县农村来到景德镇学习拉坯。那时，他就立志要成为一名一流的陶瓷工匠。从入门到热爱，从学徒到带徒，占绍林始终扎根陶瓷技能一线。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">占绍林先后获得江西省首位拉坯大师、江西省赣鄱英才领军人物、全国技术能手、国家级技能大师工作室带头人等多项荣誉。截至目前，占绍林所带学生近5000人，有3名学生获得全国技术能手称号。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">2020年，人社部《关于进一步加强高技能人才与专业技术人才职业发展贯通的实施意见》出台后，像占绍林这样的国家级技能大师工作室带头人，可直接申报评审正高级或副高级职称。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">占绍林为自己获得的副高级职称感到骄傲。获得中华技能大奖后，占绍林准备申报正高级职称的评审，“我们企业目前技术工人的数量不太多，国家新八级工制度的出台，给我很大触动，我准备在企业中进一步完善相关制度，通过培训让技术工人得到成长”。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">崔秋立认为：“老八级工制度是在计划经济体制下实行的，工资收入由政府管控。而市场经济条件下，企业自主分配，如何进行等级评定，并实现技术等级与收入待遇挂钩，是一个难点问题。正是由于近年来企业自主评价的大力推广，为解决这一问题提供了可能。”</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">人社部的统计显示，截至目前，全国有2.4万多家企业自主开展技能人才评价，8000多家社会评价机构开展社会化职业技能等级认定，累计近2100万人次取得职业技能等级证书，其中690余万人次取得高级工及以上职业技能等级证书，初步建立技能人才职业技能等级制度和多元化评价机制。（李桂杰 刘胤衡）&nbsp;</p>', NULL, '本站', '“当工人，就要当最好的工人。”领到工装的第一天，20岁的刘劲松在心里默默立下了职业目标。当时，他刚刚从北京石油化工学校毕业。27年后，2023年5月7日，第十六届高技能人才表彰大会在北京举行。人力资源和社会保障部（以下简称人社部）公开表彰30名中华技能大奖获得者和295名全国技术能手，中国石化燕山石化炼油厂职工、集', 1, 255, 1, '2025-05-04 21:45:15', '2025-07-17 21:45:48', '2025-07-17 21:45:48');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('湖北：“百县进百校”数万岗位送到大学生身边', '<p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">为深入推进2023年“才聚荆楚·百县进百校”就业促进专项行动，日前，湖北省荆门市组团走进湖北工业大学、咸宁市通城县组团走进湖北开放职业学院专场招聘。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">荆门市走进湖北工业大学招聘现场设企业招聘专区、公益性岗位专区、就业见习专区、政策咨询专区，共组织与湖北工业大学专业对口的172个单位参加，提供就业岗位3810个。其中，企业招聘岗位1980个，现场收到简历 &nbsp;1875份，达成就业意向324人；公益性岗位、就业见习岗位1830个，接受就业登记149人。现场同步开展招才引智推介会，播放引才宣传片，举办“最美家乡代言人”选聘仪式，湖北多家企业作为代表开展现场推介。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">咸宁市采取“1+6”抱团引才模式，深度挖掘全市规模以上企业需求，大力开发见习、实习岗位，以线上线下招聘活动相结合等方式，为咸宁企业招揽人才。咸宁市通城县走进湖北开放职业学院招聘现场设企业招聘专区、见习实习专区、政策咨询专区、直播带岗专区。共组织84家用人企业，提供1172个就业岗位、100个就业见习岗位，现场咨询人数1118人，达成就业意向332人，直播带岗观看量达1.1万人次。通城县与湖北开放职业学院签订人才战略合作协议，多家重点企业参加招聘活动。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">截至目前，87个市州县已经赴70所对接高校开展了招聘活动，参与用人单位数2765个、提供就业岗位数74638个，提供就业见习岗位数4558个，达成就业意向数13800个。后续其它县市区将陆续赴对接高校开展专场招聘，确保“百县进百校”就业促进专项行动实现各市州县全参与、全省高校全覆盖，吸引更多高校毕业生留鄂就业创业</p>', NULL, '本站', '为深入推进2023年“才聚荆楚·百县进百校”就业促进专项行动，日前，湖北省荆门市组团走进湖北工业大学、咸宁市通城县组团走进湖北开放职业学院专场招聘。荆门市走进湖北工业大学招聘现场设企业招聘专区、公益性岗位专区、就业见习专区、政策咨询专区，共组织与湖北工业大学专业对口的172个单位参加，提供就业岗位3810个。其', 1, 255, 1, '2025-04-29 21:46:36', '2025-07-17 21:47:09', '2025-07-17 21:47:09');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('海南：多措助力毕业生就业“百日冲刺”', '<p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">近日，海南省印发《海南省2023届高校毕业生就业“百日冲刺”行动方案》。通过开展“百日冲刺”行动，引导毕业生主动求职，帮助更多高校毕业生在离校前后落实就业去向，全力促进2023届高校毕业生高质量充分就业，并推进留琼就业。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">《方案》明确，各高校、三亚崖州湾科技城管理局要提高访企拓岗促就业专项行动成效，提升校园招聘供需匹配度，发挥“互联网+就业”资源优势，开展中小微企业吸纳毕业生就业政策落实行动。要针对未落实去向毕业生的情况，有针对性地拓展市场性岗位，更好匹配毕业生的就业需求，提升访企拓岗的实效性和供需匹配度。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">《方案》指出，各高校、三亚崖州湾科技城管理局要重点针对2023届部分毕业生“求稳”和“慢就业”等情况，有针对性地开展就业指导，采取培育积极正向的就业价值观、组织开展就业政策宣讲活动、实施专项技能提升行动、组织开展就业实习实践活动、启动大学生职业规划大赛、开展高校毕业生创业服务支持行动、切实维护毕业生就业权益等有效措施，引导毕业生积极求职、尽早就业，积极建立就业育人体系。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">《方案》对加强重点群体就业帮扶作出明确安排。“百日冲刺”期间，各高校、三亚崖州湾科技城管理局要重点帮扶求职受阻的毕业生。针对有就业意愿但在求职中屡屡受挫、尚未落实岗位的毕业生，特别是困难家庭毕业生，安排高校负责教师及时跟进，提供有效帮扶；要帮助学生分析诊断求职中的问题，完善个人简历，合理选择就业目标，提升求职技能。各高校至少为每一名就业困难群体毕业生精准推送3个岗位;鼓励教师陪同学生投递简历，了解毕业生求职困难和用人单位需求。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">同时，各高校、三亚崖州湾科技城管理局要精准帮扶就业困难毕业生，按照“一人一档”“一人一策”，精准开展有温度的就业帮扶工作。省教育厅、省人社厅抓紧实施年度“宏志助航计划”，开展线上线下就业能力培训，2023届高校毕业生的集中培训任务原则上应于5月底前完成;鼓励各高校设立校级培训项目，帮助更多有需要的重点群体困难毕业生提升就业能力。深入实施“雨露计划”，持续推动困难群体就业帮扶“晴天行动”，聚焦高校毕业生开展就业帮扶，帮助他们接触职场、融入社会。</p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="margin-top: 0px; margin-bottom: 0px; padding: 0px; color: rgb(44, 62, 80); font-family: &quot;Microsoft Yahei&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">此外，海南省还将开展离校未就业毕业生服务攻坚行动。通过线上线下失业登记、业务经办、走访摸排等途径，把在本地登记和省级人社部门分解下发的未就业毕业生全部纳入实名制服务范围。提早公布服务渠道，6月底前面向高校毕业生发出一封公开信或服务公告，方便毕业生查询求职就业信息。全面落实实名帮扶，对有就业意愿的未就业毕业生逐一联系，了解就业需求，有针对性提供职业指导、岗位推荐、职业培训或就业见习机会。</p>', NULL, '本站', '近日，海南省印发《海南省2023届高校毕业生就业“百日冲刺”行动方案》。通过开展“百日冲刺”行动，引导毕业生主动求职，帮助更多高校毕业生在离校前后落实就业去向，全力促进2023届高校毕业生高质量充分就业，并推进留琼就业。《方案》明确，各高校、三亚崖州湾科技城管理局要提高访企拓岗促就业专项行动成效，提升校园招', 1, 255, 1, '2025-04-03 21:47:11', '2025-07-17 21:47:37', '2025-07-17 21:47:37');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('电子科技大学深化新工科建设 提高人才自主培养质量', '<p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; text-align: center;">教育部简报〔2024〕第29期</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　电子科技大学认真学习贯彻习近平总书记关于教育的重要论述，坚守为党育人、为国育才初心使命，深入落实立德树人根本任务，聚焦课程体系优化、育人机制创新、人工智能培育、教学改革深化，探索构建中国特色新工科建设新模式，努力提高人才自主培养质量，为发展新质生产力、加快建设教育强国、全面推进中华民族伟大复兴贡献力量。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">强化课程体系建设，厚植人才发展沃土。</strong>一是整合专业核心课程。全面修订新一轮本科人才培养方案，推动每个专业汇聚高水平教师，通过课程整合、内容整合，打通专业核心知识体系，打造6—8门高整合性、大颗粒度、高标准的专业核心课程，推进专业核心课程、实验、教材一体化建设。压缩总学分，减少学生修读课程门数，扩大专业选修和跨学科（领域）选修范围，明确课堂教学周学时不超过20学时，让学生将更多精力投入研究型、挑战性学习。二是升级核心通识课程。成立新一届通识教育委员会，强化通识教育课程研究、指导和咨询。打造“文史哲学与文化传承”“自然科学与技术前沿”等七大模块组成的核心通识课程体系2.0，持续提升学生综合素养。面向全校选拔组建优秀教学团队，为全体理工学生开设“专业写作基础”通识必修课，注重培养打通学科壁垒的底层逻辑思维。开展通识教育课程优秀作业评选，调动学生积极性，提升学生学习获得感。三是构建项目式课程体系。全面优化“始于新生、贯通四年、逐级进阶”的项目式课程体系，为学生提供从新生项目式课程到高峰体验项目式课程的贯通学习，强化真实工程场景中的创新人才培养。优化毕业设计转化机制，推动高峰体验项目式课程、高质量挑战性学习课程、高水平课外创新实践计划等成果转化为学生毕业设计，目前已有一批学生将学习成果转化为全国优秀本科毕业设计。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">推进育人机制创新，架设人才成长云梯。</strong>一是建立创新人才个性发展机制。在“大类招生、大类培养”和提供两次转专业机会基础上，实施《本科生自主设计个人专业培养方案修读计划》《优秀本科生自主掌握学业进程、申请课程免听或免修管理办法》，学生可以打破学院和学科专业壁垒，实现自定义专业方向和自设计培养方案。目前已有89名本科生拥有“私人定制化”培养方案。二是深化急需紧缺人才成长机制。建设国家集成电路产教融合创新平台、国家示范性微电子学院，实施集成电路“强芯铸魂”本硕博贯通培养特别行动计划，按“一院一方案，一生一计划”原则实施个性化培养。深入实施基础学科拔尖学生培养计划2.0，建立以“师资大师化”“课程定制化”“教学国际化”“三对一导师制”为特色的培养机制，努力培养一流的计算机科学家。深化应用物理“强基计划”“成电英才计划”以及18个院级拔尖创新人才培养计划，持续做实“三制三化”模式，加快培养基础学科与基础研究创新人才。三是构建“大—中”衔接协同育人机制。优化人才推荐与选拔机制，开设大学先修课，与中学共同开发科学课程，实施中学生“英才计划”等，探索“大学+中学”衔接培养新模式。与相关中学签订拔尖创新人才培养协议，共建科技创新人才孵化站、实验室，不断完善人才贯通培养平台。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">深化课堂教学改革，筑牢人才培育根基。</strong>一是坚持科教融汇引领教学改革。推动杰出科技人才领衔并亲自组织科研大团队实施12项“高水平科研育人新工程教育计划”，将信息技术关键领域的重大科研成果转化为“核心课程·逐级挑战冲关项目”交融的专业教育体系。瞄准未来技术前沿，联合企业强化面向产业场景的课程开发，提高学生解决真实工程问题能力，目前开发教育部－华为“智能基座”课程31门。二是推进研究型挑战性教学改革。持续开展研究型挑战性教学改革、课程建设与质量评估，打造成体系的研究型挑战性标杆课程与常态化“示范—改进—退出”机制。截至目前，已建设各类研究型挑战性课程1300余门，形成研究型标杆课程191门。三是推动数智转型赋能教学改革。以未来学习中心建设为牵引，在“成电慕课”“校级实验教学共享平台”“成电学堂”等平台基础上，整合各类线上线下资源，特别是数字教学平台、智能教学助手、虚拟仿真技术、智能化实验辅助等，构建集成化的智慧教学平台，打造泛在、智能、交互的智慧学习空间，推动以智助学、以智助教、以智助管、以智助研。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">培育人工智能特色，激发人才创新潜能。</strong>一是完善人工智能课程体系。开设“人工智能导论”等新生研讨课和“计算机视觉识别系统开发实践”等新生项目课，引导新生走近、了解人工智能。由国家杰出人才领衔，组建校级跨学院、跨学科“大课程组”，建设高质量人工智能核心通识课。结合专业特点，开设面向应用场景、逐级进阶的“人工智能+”专业类课程，为人工智能拔尖创新人才培养提供有力支撑。二是打造人工智能特色培养项目。充分发挥人工智能在信息通信、材料、测控、生命科学、金融管理等领域的创新驱动作用，推动计算机科学、自动控制、电子信息、机器学习、统计学、数学、脑科学与认知科学等多学科交叉融合，实施深度交叉融合的人才培养新模式。如，在基础学科拔尖学生培养计划2.0中开展人工智能方向拔尖人才培养，在“高水平科研育人新工程教育计划”中强化“人工智能+”领域的逐级冲关挑战项目体系建设。三是扩展人工智能覆盖范围。由信息与通信工程学院牵头，联合多个学院开设“人工智能时代”“人工智能及其应用”“漫谈人工智能”“走近人工智能”等面向全校学生的人工智能通识教育课程，增强学生的人工智能素养与能力。面向全校学生开设人工智能微专业，为学生提供系统的人工智能知识与实践机会，让学生在短时间内掌握人工智能的核心概念和技术，为发展新质生产力提供更广泛的人才基础。</p>', NULL, '本站', '教育部简报〔2024〕第29期电子科技大学认真学习贯彻习近平总书记关于教育的重要论述，坚守为党育人、为国育才初心使命，深入落实立德树人根本任务，聚焦课程体系优化、育人机制创新、人工智能培育、教学改革深化，探索构建中国特色新工科建设新模式，努力提高人才自主培养质量，为发展新质生产力、加快建设教育强国、全', 1, 255, 1, '2024-09-14 11:19:35', '2025-07-19 11:20:51', '2025-07-19 11:20:51');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('华中科技大学坚持“四力并举” 深入推进拔尖创新人才培养', '<p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; text-align: center;">教育部简报〔2024〕第19期</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　华中科技大学认真学习贯彻习近平总书记关于教育的重要论述，牢记为党育人、为国育才初心使命，紧紧围绕立德树人根本任务，健全思政工作、自主培养、要素保障、协同育人四个工作体系，着力提升拔尖创新人才培养的引领力、内驱力、支撑力、创新力，走好具有华科大特色的拔尖创新人才自主培养之路，有力服务教育强国、科技强国、人才强国建设。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">健全思政工作体系，提升“引领力”。</strong>一是加强思政课程建设。将思政课作为立德树人的关键课程，建成以习近平新时代中国特色社会主义思想为核心内容的思政课课程群，创新开设“深度中国”“百年中国”“星河灯塔——伟大的科学家精神”等思政选修课，大力推动思政课守正创新。依托学校丰富的国家级科研平台资源和湖北省、武汉市红色资源，建好用好校内外的实践教学基地，出版“青春力行”实践育人丛书5本，上好“行走的思政课”。二是提升课程思政实效。出台加强课程思政建设的方案，实施院（系）党组织书记课程思政亮点工程和“一院一品”计划，实现课程思政全覆盖。大力提升教师课程思政教学能力，成立课程思政教师工作坊，开展课程思政主题培训100余期，培训教师3000多人次，创建《课程思政教学研究》辑刊，出版《新工科背景下专业课程思政教学指南》等课程思政系列丛书12本。三是深化党旗领航内涵。实施“新时代党旗领航工程”，依托“青马工程”“西部计划”“星火计划”“头雁领航”等平台加强学生骨干培养，持续推进胡吉伟班、黄群班等荣誉班级建设，引导学生爱党报国。加强“一站式”学生社区建设，开展“书记下午茶”“校长面对面”“五老进社区”等活动，努力推进“先锋型、学习型、平安型、美丽型、活力型”五型社区建设。教育部高校“一站式”学生社区综合管理模式建设工作推进会在学校召开。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">健全自主培养体系，增强“内驱力”。</strong>一是深化教育教学改革。贯彻“学生中心、产出导向、持续改进”的教育理念，先后出台一流本科教育改革和一流研究生教育改革实施意见，新时代卓越工程师、卓越医学人才、卓越法治人才和卓越新闻传播人才等4类人才教育培养管理办法，不断优化新时代卓越人才培养体系，推动学校“办最好的本科教育”“让研究生站到创新最前沿”。二是优化学科专业设置。主动对接国家和区域重大战略需求，布局增设网络空间安全、人工智能、集成电路、智能建造、储能科学等10余个前沿、新兴、交叉学科专业，以及儿科学等民生急需专业，通过关、停、并、转对老、旧、窄、散专业进行更新整合，提升专业建设质量。三是创新人才培养模式。实施“启明·星计划”，依托启明学院深入探索以学生为中心的“团队作战、项目驱动、本硕协同、师生共创”主动实践模式，“启明学院”入选首批国家级创新创业学院建设试点。探索本研贯通式人才培养模式，设置“启明”“强基”“未来”“创新”等四类实验班，健全跨层次选课和学分认定机制，打通本研课程互选通道。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">健全要素保障体系，夯实“支撑力”。</strong>一是建设高质量课程体系。全面修订人才培养方案，加强一流专业和一流教材建设，推行课程责任教授制，建设具有高阶性、创新性和挑战度的一流核心课程，大力培养学生自主学习和创新能力，学校74个专业入选国家级一流专业建设点，92门课程被认定为国家级一流本科课程。推动跨学科、跨院系、跨专业组建高水平教学团队，落实教授全员给本科生上课、学生培养实验室轮转等制度，不断提升教学质量。二是完善高水平载体平台。集聚拔尖创新人才培养平台，先后建设网络空间安全学院、未来技术学院、集成电路学院、高水平公共卫生学院、国家卓越工程师学院，获批教育部基础学科拔尖学生培养计划2.0基地7个。优化实习实践环境，建有国家级实验教学示范中心7个，国家级虚拟仿真实验教学中心2个，各级校内外实习、实训基地608个。三是加强数字化技术应用。开发建成“学在华科大”教育教学数字化平台，支撑全链路教学活动，推进本研教务一体化和运维一体化建设，实现“教、学、管”全面数字化转型升级。建设虚实融合的新型教学空间，丰富交互讨论、VR教学等数字化教学手段，优化课堂远程实时直播、多视窗互动等功能，建成116间智慧教室，在中国大学MOOC等平台上线课程121门，助力教育教学提质增效。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">健全协同育人体系，激发“创新力”。</strong>一是着眼“优选”促进招培联动。主动对接国家人才需求实施招生制度改革，制定提升本科生源质量行动计划，全面推进“本科生源质量院系负责制”，促进招生与院系拔尖创新人才培养有效衔接。深化“高中—高校”联动，实施“英才计划”和“登峰计划”，通过与重点中学共建大学先修课、科创实验室、优质生源基地等育苗行动选育英才，推动拔尖创新人才早发现、早培育。二是突出“优教”深化科研育人。出台加强科研基地向本科生开放的若干意见，推动武汉光电国家研究中心、国家脉冲强磁场科学中心、精密重力测量国家重大科技基础设施等国家级科研基地向学生开放资源，引导本科生早进实验室、早进团队、早进课程、早进科技前沿，将科技前沿成果转化为实践教学项目、科技创新项目。每年有超过2万名学子参与各类科技创新活动和创新大赛。三是注重“优培”加强产教融合。加强与一流科研院所和领军企业的全链条合作，实施“十大研究院计划”“龙头企业对接计划”等，完善“订单式、项目制”人才培养模式，以科学和产业前沿问题牵引拔尖创新人才培养。建立“课程实验－平台实训－企业实习”分层次专业实践体系，校企共建“教育与科技创新促进中心”，共推创客空间、众创空间，共办亚马逊杯编程大赛等赛事，推动学生创新项目从研究到应用、创新到创业、校内到校外的无缝对接。</p>', NULL, '本站', '教育部简报〔2024〕第19期华中科技大学认真学习贯彻习近平总书记关于教育的重要论述，牢记为党育人、为国育才初心使命，紧紧围绕立德树人根本任务，健全思政工作、自主培养、要素保障、协同育人四个工作体系，着力提升拔尖创新人才培养的引领力、内驱力、支撑力、创新力，走好具有华科大特色的拔尖创新人才自主培养之路', 1, 255, 1, '2024-08-30 11:18:30', '2025-07-19 11:19:34', '2025-07-19 11:19:34');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('辽宁省构建产教融合发展新格局 服务全面振兴新突破 ——2024年全国教育工作会议经验交流之三', '<p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; text-align: center;">教育部简报〔2024〕第3期</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　辽宁省坚持以习近平新时代中国特色社会主义思想为指导，深入学习贯彻习近平总书记关于教育的重要论述，聚焦“一体两翼”（一体，即探索省域现代职业教育体系建设新模式；两翼，即市域产教联合体和行业产教融合共同体）、振兴发展、内涵建设三个重点，着力构建产教融合发展新格局，以教育高质量发展服务推动全面振兴新突破。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">聚焦“一体两翼”，推动产教协同实现新突破。</strong>一是强化规划设计和整体统筹。落实部省战略合作协议任务要求，研制实施方案，坚持部省同题共答、同向发力，构建具有辽宁特色的省域现代职业教育体系。二是筹建国家工业母机行业产教融合共同体。跨区域联合行业组织、学校、科研机构、上下游企业等，重点围绕工业母机高端主机产品、数控系统、功能部件及关键共性技术开展人才、技术对接，首批对接人才、技术需求102项。三是服务辽宁“老字号”“原字号”“新字号”产业结构调整和大国重器建设。组建石油化工、机器人、船舶、航空等10个行业产教融合共同体，依托国家、省级产业园区组建20个市域产教联合体。健全实体化运作机制，建立厅领导包保制度，深入园区、企业调研；搭建职业教育产教协同对接服务平台，建立对接台账，推动人才供给、技术创新等产教需求精准匹配；组织共同体对接项目签约，召开工作推进会，推动校企实质对接。截至目前，已有581家院校、企业加入共同体，校企共建专业、课程、教材，联合开展技术攻关等2500余项。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">聚焦全面振兴，推动服务发展实现新突破。</strong>一是服务“人才强国”战略，积极探索“卓越工匠”辽宁实践。启动实施“兴辽未来工匠”培育工程，省教育厅会同省发展改革委、省财政厅等部门印发《辽宁省“兴辽未来工匠”培育工程实施方案》，明确建设培育基地、创新选拔机制、改革培养模式、打造师资团队、探索评价机制等任务。遴选27个培育基地，探索校企双元育人新模式。采用“资格推荐+文化考试+技能考核”遴选方式，首批录取“匠苗”136名。发布“兴辽未来工匠”人才培养方案编制指南，“一匠一案”开展学情分析，明确培养目标及规格。通过以师带徒、工匠传承、送教到岗、多方拜师等方式，修素养、厚基础、强技术、锻绝活，为辽宁全面振兴实现新突破储备一批大国工匠、能工巧匠。二是服务“乡村振兴”战略，创新建设乡村振兴学院。依托县级职教中心，组织高职院校与县域重点企业共建15个乡村振兴学院，开展五年一贯制学历教育和高素质农民培训。通过市域定向招生、县域定向就业、产教资源精准对接，为县域经济培养“留得住、用得上、下得去”的高素质技术技能人才，不断提高职业教育服务乡村振兴的能力与水平。三是服务“一带一路”倡议，推动“职教出海”。成功举办首届“一带一路”国际职业教育改革发展研讨会，来自17个国家各界代表300余人参会。中国、柬埔寨、德国等13个国家社会组织共同发起并签署《沈阳协议》，共同探索构建实质等效的高等职业教育国际认证体系，促进职业技术技能人才在不同国家、地区之间的流动和认可。坚持“教随产出、校企同行”，在俄罗斯、加纳、老挝等14个国家建设15个海外职业教育产业学院——“墨子工坊”。精准对接“走出去”企业的本土化技术技能人才需求，服务企业国际产能合作、推动共建“一带一路”高质量发展。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">聚焦内涵建设，推动改革创新实现新突破。</strong>一是重塑职业教育教学形态。提升技术技能人才培养适应性，立足区域产业发展实际，创建职业教育专业能力图谱，开发应用场景，修订培养方案、重构课程体系、重组教学内容、实施过程性评价、生成能力“画像”，启动94个图谱建设及应用。二是实施混合所有制办学改革。省教育厅会同省发展改革委等部门印发《关于推进职业院校混合所有制办学的指导意见》，并制定《职业院校举办混合所有制二级学院实施细则（试行）》，明确混合所有制办学的设立程序、办学形式、治理结构、支持政策。鼓励“先行先试”，按照“成熟一个、批复一个”的原则，首批启动4个混合所有制二级学院试点建设，并在园区、企业建设10个开放型区域产教融合实践中心。指导有关院校按照“公办高校、混合体制、民营机制”办学思路和“党委领导、董事会决策、院长负责”治理结构进行管理。省教育厅会同省发展改革委、省财政厅等部门印发《“金融+财政+土地+信用”组合式产教融合激励政策》，从强化金融扶持、落实财政税收优惠政策、完善土地保障政策、健全信用激励和考核评价机制等方面进一步激发企业参与职业教育的积极性和主动性。三是加强数字职教建设。制定数据基座实施标准，研发并部署全省职业院校数据基座、校级驾驶舱建设，完成6所职业院校数据部署和数据对接工作。建成省级职教大数据平台，从院校、专业、人才培养方案、课程、实习实训、就业、社会服务等方面对全省职业教育发展进行动态监控和数据分析，实现对全省职业教育人才培养工作统一的管理和服务，为职业教育管理决策提供数据支撑。</p>', NULL, '本站', '教育部简报〔2024〕第3期辽宁省坚持以习近平新时代中国特色社会主义思想为指导，深入学习贯彻习近平总书记关于教育的重要论述，聚焦“一体两翼”（一体，即探索省域现代职业教育体系建设新模式；两翼，即市域产教联合体和行业产教融合共同体）、振兴发展、内涵建设三个重点，着力构建产教融合发展新格局，以教育高质量发', 1, 255, 1, '2024-03-22 11:17:31', '2025-07-19 11:18:28', '2025-07-19 11:18:28');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('新疆维吾尔自治区积极做好国家通用语言文字推广普及工作', '<p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; text-align: center;">教育部简报〔2023〕第30期</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　新疆维吾尔自治区坚持以习近平新时代中国特色社会主义思想为指导，深入落实习近平总书记关于教育的重要论述和视察新疆重要讲话重要指示精神，坚持把语言文字工作融入党和国家事业发展全局，按照“一地一策”工作部署，精准聚焦，因地制宜，切实加大国家通用语言文字推广普及力度，统筹发展和安全，不断推动自治区语言文字工作高质量发展，着力为铸牢中华民族共同体意识、构筑中华民族共有精神家园贡献力量。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">加强组织领导，强化政策落实。</strong>把坚持和加强党的领导全面贯穿语言文字工作全过程各方面，系统谋划、统筹推进国家通用语言文字推广普及工作。一是健全工作机制。成立以自治区党委分管负责同志任主任、自治区政府分管负责同志任副主任，37个相关部门为成员单位的语言文字工作委员会，明确各单位工作职责，每年召开自治区语言文字工作会议和语言文字工作委员会全体会议等，有力有序推动各项工作落实，不断健全“党委领导、政府主导、语委统筹、部门支持、社会参与”的管理体制，形成上下贯通、一体联动抓好国家通用语言文字推广普及的工作格局。二是优化服务体系。持续深化对民族地区、边疆地区科学推普工作的规律性研究，在深入调研分析的基础上，分区域、分群体制定自治区国家通用语言文字推广普及工作方案，进一步健全适应广大群众需求的服务体系。三是完善政策举措。深入落实国家通用语言文字普及提升工程和推普助力乡村振兴计划，自治区教育厅、发改委、财政厅、乡村振兴局联合印发《自治区实现巩固拓展教育脱贫攻坚成果同乡村振兴有效衔接实施方案（2021—2025年）》，编制语言文字事业“十四五”发展规划，出台面向社会特别是中青年群体加强国家通用语言文字学习培训、提高产业园区务工人员国家通用语言文字应用能力等系列文件，切实为推普工作提供有力政策保障。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">发挥学校作用，建强基础阵地。</strong>落实国家通用语言文字作为教育教学基本用语用字的法定要求，充分发挥学校的基础阵地作用，不断提升各级各类学校国家通用语言文字教育教学质量。一是加快推进学校语言文字达标建设。自治区教育厅与新疆生产建设兵团教育局联合印发《关于做好2023年各级各类学校语言文字工作达标建设的通知》，指导督促各地各校做到语言文字工作“有机构、有目标、有计划、有措施、有检查”，确保2025年各级各类学校（幼儿园）高质量完成语言文字达标建设目标。二是实施学前儿童普通话教育专项计划。坚持使用国家通用语言文字开展学前儿童保育教育活动，自2021年起培训幼儿园教师5000余人。完成9个地区（州、市）814所幼儿园的11.5万名学前儿童的普通话能力跟踪监测和80所幼儿园1.7万名学前儿童的普通话能力抽测工作，为做好普通话教育工作提供科学依据，进一步提升学前儿童的普通话交流能力。三是持续强化教师队伍教育教学能力。依托“国培计划”“语培计划”“区培计划”等，利用线上线下组织示范课、研讨课、专家讲座等形式，年均培训各级各类教师9万余人次，不断增强教师国家通用语言文字素养和教育教学能力。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">　注重分层分类，推动精准施策。</strong>积极拓展工作路径，创新工作手段，努力做好社会面国家通用语言文字培训工作。一是做好示范带动。自治区党委办公厅、自治区人民政府办公厅联合印发通知，推动党政机关、科研院所和教育医疗、新闻媒体等领域工作人员国家通用语言文字应用水平率先达标，切实发挥辐射带动作用。二是实施重点突破。面向基层干部、产业园区务工人员等重点群体，采取集中培训、赴援疆省市考察学习等方式，不断强化基层干部国家通用语言文字应用能力，年均培训3.6万人次；采取工前工后“一刻钟”微课堂、结对帮扶、集中学习等方式，努力帮助产业园区务工人员提升国家通用语言文字的听说能力。三是集中力量攻坚。加强青壮年农牧民国家通用语言学习培训，在县（市、区）开设93个“中心课堂”、在村（社区）开设夜校分课堂1.02万个，2023年上半年培训169.28万人次。多渠道、多形式扩充推普培训工作力量，从高校毕业生、基层干部、村干部中选派国家通用语言文字基础较好人员承担培训辅导任务；对12个地（州、市）、84个县（市、区）的1.9万名青壮年劳动力进行国家通用语言文字应用能力调查，准确了解和掌握学习效果，促进培训方式由“大水漫灌”向“精准滴灌”转变，进一步提高国家通用语言文字的普及程度和普及质量。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">　夯实条件保障，提升支撑能力。</strong>统筹多方力量，持续优化国家通用语言文字推广普及资源配置，强化支撑保障。一是拓展学习资源。编写面向村干部、农村中青年群体和产业园区务工人员的国家通用语言文字学习教材，委托新疆大学研发面向青壮年劳动力群体的国家通用语言文字智能学习云平台，为中青年群体学习国家通用语言文字提供更加优质便捷的条件支持。截至目前，已开发各类国家通用语言文字学习材料、数字资源40余种。二是强化站点建设。持续强化普通话水平测试站点建设和测试员培训培养，建成站点147个，基本实现县市普通话测试站点全覆盖，助力提升全社会普通话应用水平。2023年，组织开展普通话水平测试78万余人次。三是建好推广基地。依托新疆大学、新疆师范大学、新疆财经大学、喀什大学、昌吉学院、阿克苏教育学院6个国家语言文字推广基地，大力推动国家通用语言文字推广普及项目研究、传承推广、示范培训等工作，累计完成114个语言文字相关课题项目，培训语言文字工作干部、国家通用语言文字教学骨干2500余人次，着力为国家和区域语言文字事业发展提供有力人才保障和智力支持。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">坚持文化浸润，营造学用氛围。</strong>坚持以铸牢中华民族共同体意识为主线，广泛开展文化浸润活动，持续提升社会大众特别是青少年的语言文字应用能力和语言文化素养，以国家通用语言文字为纽带，推进文化铸魂，增强中华民族凝聚力和向心力。一是打造品牌活动。实施中华经典诵读工程和“经典润乡土”计划，组织开展全国推广普通话宣传周、“中国诗词大会”选拔赛、“品读经典·声动新疆”等活动，累计吸引广大师生和各族干部群众近400万人次参与。二是加强推普宣传。挖掘选树推普典型案例、先进人物事迹和经验成效，2022年以来，精心组织“推普达人”“学普达人”等评选活动，在新疆电视台、新疆人民广播电台等媒体展播推普典型的事迹短片，鼓励更多群众投身推广普通话的事业，相关视频网络访问量达2865万人次。三是丰富活动载体。探索将国家通用语言学习纳入村规民约，常态化开展“小手拉大手·学讲普通话”活动，将国家通用语言文字学习培训作为“民族团结一家亲”、民族团结联谊等活动的规定内容，努力将普通话教育延伸到每一个家庭，积极营造全社会“学、讲、用”国家通用语言文字的良好氛围。</p>', NULL, '本站', '教育部简报〔2023〕第30期新疆维吾尔自治区坚持以习近平新时代中国特色社会主义思想为指导，深入落实习近平总书记关于教育的重要论述和视察新疆重要讲话重要指示精神，坚持把语言文字工作融入党和国家事业发展全局，按照“一地一策”工作部署，精准聚焦，因地制宜，切实加大国家通用语言文字推广普及力度，统筹发展和安', 1, 255, 1, '2023-10-23 00:00:00', '2025-07-19 11:14:42', '2025-07-19 11:14:42');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('中国人民大学坚持人才引领驱动 奋力打造人文社会科学研究和教学领域重要人才中心和创新高地', '<p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; text-align: center;">教育部简报〔2023〕第18期</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　中国人民大学认真学习贯彻党的二十大精神，深入落实习近平总书记关于教育的重要论述特别是考察调研学校时的重要讲话精神，强化党的全面领导，坚持“科技是第一生产力、人才是第一资源、创新是第一动力”，牢固树立“大人才观”，全面系统制定人才规划、畅通发展路径、优化管理服务，以更加积极、更加开放、更加有效的人才政策加快建设学校战略人才力量，奋力打造我国人文社会科学研究和教学领域的重要人才中心和创新高地。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">　加强党的领导，把牢人才工作正确方向。</strong>紧紧围绕“走新路、开新局、创一流”中心任务，持续深入学习贯彻习近平总书记考察调研学校时重要讲话精神，召开学校党委常委会会议、党委理论学习中心组学习会等开展专题学习；学校领导班子成员带头抓好学习贯彻，并深入二级单位党组织开展宣讲和督导，指导广大干部师生掀起学习宣传贯彻的热潮；印发《关于深入学习宣传贯彻落实习近平总书记在学校考察时重要讲话精神的总体工作方案》，谋划实施重要人才中心和创新高地打造工程，研究细化建设高质量教师队伍工作举措。坚持党管人才，印发《关于大力推进新时代人才工作高质量发展的意见》《关于加强新时代教师队伍建设改革的工作方案》等，持续强化学校党委对人才工作的全面领导、统筹协调和把向定标作用。成立由学校党委书记、校长任组长的人才工作领导小组，优化人才工作领导小组办公室职能设置，健全议事规则，着力构建“学校党委统一领导—人才部门牵头抓总—相关部门密切配合—学院（系）等工作单位主动作为—全校广泛参与”的人才工作格局。加强政策系统设计，将建成人文社会科学研究和教学领域重要人才中心和创新高地的战略目标纳入学校《学习宣传贯彻党的二十大精神总体工作方案》《新路建设十大工程实施方案》等，在人才引进、人员选聘、职评岗聘等方面制定系列配套文件，探索构建理念先进、政策完备、运转高效、评价科学、保障有力的新时代人才工作机制。注重高层次人才政治吸纳，做好优秀青年人才和海外留学归国人才党员发展工作，让听党话、跟党走的信念转化为各类人才的思想自觉和行动自觉。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">注重思想引领，树牢师德师风第一标准。</strong>坚持用习近平新时代中国特色社会主义思想武装头脑、指导实践、推动工作，制定《关于加强教职工思想政治理论学习工作的实施意见》，组织教师制度化、常态化开展理论学习。强化理想信念教育，深入开展学习贯彻习近平新时代中国特色社会主义思想主题教育；围绕党的二十大、全国“两会”等重大活动，精心组织形式多样的思想政治理论学习，切实提高人才政治理论水平。出台《关于完善教师思想政治和师德师风建设工作体制机制的实施意见》，将师德师风作为人才招聘引进、职务评审、岗位聘用、项目申请等环节的首要要求和第一标准，将“严爱相济、润己泽人”的要求融入广大教师教书育人各领域全过程。实施“吴玉章课程思政名师工作室计划”，充分发挥课程思政名师的示范引领作用，鼓励引导高层次人才带头加强课程思政建设，着力构建“团队建设—课程建设—辐射带动”三位一体工作格局。创新开展特色项目，组织教师全面参与“红色之路”“读懂中国”“海归教师挂职锻炼计划”“中华人民共和国脱贫攻坚史研究”等项目工作，引导人才深入了解党情、国情、社情、民情，扎根中国大地做研究。坚持学校党委书记为新入职教职工讲授“入职第一课”制度，将师德师风学习教育纳入教师职业发展各类培训体系。开展师德先进集体和师德标兵评选，举办“吴玉章师德师风大讲堂”，推出学校“全国高校黄大年式教师团队”专题宣传片，引导广大教师努力做精于“传道授业解惑”的“经师”和“人师”的统一者。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">精准分类施策，厚植战略人才成长沃土。</strong>系统规划构建“吴玉章学者”“成仿吾兼职学者”“青年人才涵育”人才育引支持三大岗位体系，畅通“师资博士后—青年学者—特聘教授—讲席教授—资深教授”全链条人才成长路径，使不同人才群体在不同成长阶段均可获得相匹配的政策支持。实施“名家大师和战略科学家培养工程”，开展好学校自设一级教授评聘工作，柔性聘任校外相关领域资深专家担纲学校重大研究工程，充分发挥顶尖人才示范引领作用。实施“学术领军人才和创新团队锻造工程”，依托国家重大人才项目，培养集聚具有国际影响力的领军人才，在科研项目、人员团队、平台智库资源等方面提供稳定支持。实施“青年拔尖人才孵化工程”“青年人才涵育支持计划”等，畅通青年人才破格晋升通道，构建定位明确、层次清晰、衔接紧密的优秀人才培养体系，探索加强青年人才的薪酬待遇、科研项目、发展空间、配套机制等综合保障，助力青年人才挑大梁、担重任、当主角。近一年来，学校新增国家重大人才工程入选者20人次，基本覆盖学校所有学科门类。推进科研高地建设，发挥高层次人才在推进基础理论重大创新研究、主持国家重大项目等方面的重要作用，2022年获批国家社会科学基金重大项目立项19项、国家自然科学基金项目逾百项、北京市社会科学基金项目19项。成立交叉科学研究院、欧亚研究院等跨学院跨学科创新平台，推动建设一批新的“人才培养特区”，进一步提升高层次人才资源效益。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">深化机制改革，激发人才发展内生动力。</strong>持续深化人才评价制度改革，坚持质量导向，强化多维评价，突出过程评价，探索构建重要人才中心综合评价指标体系，多维度评价人才在人才培养、科学研究、社会服务、文化传承创新、国际交流合作等方面的成果。关注在建构中国自主知识体系中的标志性贡献，推动人才评价向重视原创性贡献、决策支撑作用、文化传承影响转变。科学设置人才评价周期，对于基础研究人才和青年人才，重点推行聘期评价和长周期评价。发挥学术共同体在学术评价中的基础作用，不断完善国内外同行专家评价制度。落实科研经费管理改革，印发科研项目经费“包干制”管理办法等文件，切实为人才创造性活动提供有力保障。实施顶尖人才规模动态管理，不断优化引才审议与决策机制，对学院（系）急需紧缺特殊人才开启“绿色通道”，着力提升人才精准引进水平。创新人才使用模式，探索建立以信任为基础的人才使用机制，支持由战略科学家“挂帅”的文理交叉融合领域跨学科创新团队，鼓励学院（系）协同引才、跨学院（系）用才，实现人才用当其长、用当其时、用当其位。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">夯实服务保障，营造干事创业良好生态。</strong>坚持校院协同增强管理服务合力，学校层面切实履行好管宏观、管政策、管协调、管服务职能，不断完善人才工作政策体系；学院（系）层面充分发挥用人主体作用，持续增强人才工作服务意识和保障能力。建立健全校院两级党委联系专家、科研助理协助专家的管理服务工作机制。开展人才工作调研，近一年来，召开各类人才工作专题会50余次，举办各类人才座谈会30余场，开展人才满意度、人才制度成效等调查研究10余次，进一步凝聚共识、摸清问题、找准障碍、精准施策。打造高素质专业化管理干部队伍，研究修订学校教师以外其他专业技术队伍和行政管理队伍职称评审和岗位聘用工作办法，着力构建职务、职称、职级“三职并行”评价体系，打通干部成长“立交桥”。提升人才工作温度，开展人才“一对一”精准服务，持续优化办事流程，缩短业务办理时限。深化学校综合服务中心“一网一门”建设，加快打造“线上+线下”一体式人才综合服务平台，以数字化手段提升服务效能，实现“一站式”人才服务，积极助力打造我国人文社会科学研究和教学领域的重要人才中心和创新高地工作取得新进展。</p>', NULL, '本站', '教育部简报〔2023〕第18期中国人民大学认真学习贯彻党的二十大精神，深入落实习近平总书记关于教育的重要论述特别是考察调研学校时的重要讲话精神，强化党的全面领导，坚持“科技是第一生产力、人才是第一资源、创新是第一动力”，牢固树立“大人才观”，全面系统制定人才规划、畅通发展路径、优化管理服务，以更加积极', 1, 255, 1, '2023-07-24 11:14:44', '2025-07-19 11:15:40', '2025-07-19 11:16:27');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('浙江省绍兴市聚力“补、防、堵” 持续推进非学科类培训机构规范治理工作', '<p><br/></p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; text-align: center;">教育部简报〔2022〕第42期</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　浙江省绍兴市深入贯彻落实党中央、国务院关于“双减”工作的决策部署，在不断深化学科类培训治理的同时，因地制宜同步推进非学科类培训规范工作，依托全国校外教育培训监管与服务综合平台，通过健全制度机制、强化安全管理、完善监管体系等举措，着力补短板、防风险、堵漏洞，稳步推进非学科类培训机构规范治理工作落地落细落实。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">健全制度机制，在“补短板”上下功夫。</strong>一是强化监管责任。印发《关于进一步加强非学科类培训机构监管工作的通知》，按照“谁审批、谁负责”原则，明确由文广旅、科技、体育等部门分别牵头负责文化艺术类、科技类、体育类培训机构审批与监管。召开非学科类培训机构规范治理专题部署会，完善工作方案和具体措施，压实工作责任，推动形成“准入、审批、监管”全链条工作闭环。二是细化分类标准。由市教育局牵头，联合相关部门印发《绍兴市科技类校外培训机构准入指引（试行）》《绍兴市体育类校外培训机构准入指引（试行）》《绍兴市艺术类校外培训机构准入指引（试行）》，从机构设置、场地设施、从业人员、培训内容、资金监管以及审批登记等方面分别作出明确规定。三是优化监管方式。建立义务教育阶段校外培训项目分类鉴别及复核机制，成立专家委员会，对学科类与非学科类培训机构划定明确界限，加强非学科类培训机构的审核，并参照学科类培训机构管理方式，纳入平台统一监管。组织开展非学科类校外培训收费专项排查整治工作，实行销号制度和“黑白名单”制度，对排查发现的问题，明确整改要求和期限，坚决遏制非学科类校外培训机构违法违规行为。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">强化安全管理，在“防风险”上下功夫。</strong>一是完善资金监管强预警。紧抓资金监管关键环节，利用信息化手段对非学科类校外培训机构预收费加强风险管控。全面实施预收费监管，明确培训机构可在本市范围内选择1家托管银行，开设预收费专用账户，采取“预收费—上课—付款消课”模式，由银行按约定发出消课和划转指令。相关部门共享校外培训机构预收费监管信息，实时掌握机构招生、开课、资金等情况，有效防止培训机构“退费难”和“卷款跑路”等问题。搭建“服务+监管”一站式综合服务管理平台，公开证照、教师、课程、培训材料等信息，并为培训机构提供课程发布、招生、收费等服务。二是严格隐患排查保安全。联合市场监管、消防等部门开展大检查，全面排查培训机构安全管理情况，督促指导校外培训机构履行安全主体责任，对存在安全隐患的培训机构，依法依规严肃处理。2022年7月以来，共开展“双随机”“四不两直”检查370余家次。三是落实疫情防控守防线。严格落实常态化疫情防控要求，督促培训机构守好“责任田”，加强从业人员每日健康监测，坚持“日报告”“零报告”等制度；加大明察暗访监管力度，全面落实场所码“应贴尽贴、应扫尽扫”、行程码健康码“应查尽查”等防控举措，切实保障学生健康和安全。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">完善监管体系，在“堵漏洞”上下功夫。</strong>一是建立清单管理机制。充分发挥市“双减”工作专班牵头抓总作用，建立市县两级信息互通机制，文广旅、科技、体育等部门对非学科类校外培训机构开展地毯式摸排，通过“机构清单”和“红线清单”实行全覆盖管理。针对举办者、机构负责人、教师和管理人员等群体，细化明确要求，划定准入“红线”，严格规范培训机构办学行为。二是建立联合检查机制。市县两级“双减”工作专班联合开展校外培训机构常态化督查监管，充实社会监督员、网格监督员队伍，加大执法检查力度，坚决遏制非学科类培训恶意涨价、超时收费等违背公益属性的行为，确保治理成效不打折扣。截至目前，已累计出动执法人员4500余人次，检查非学科类培训机构1700余次。三是建立定期通报机制。实行每周通报机制，并根据不同阶段工作重点，动态调整通报指标，对非学科类培训机构平台开设账号、录入教师课程相关信息、建立银行监管账户等情况进行定期通报。截至目前，全市78家体育类培训机构、73家文化艺术类培训机构和21家科技类培训机构均开设了银行托管监管账户，全部纳入全国校外教育培训监管与服务综合平台监管，切实维护好广大学生和家长的合法权益，推动构建区域教育良好生态。</p><p><br/></p>', NULL, '本站', '教育部简报〔2022〕第42期浙江省绍兴市深入贯彻落实党中央、国务院关于“双减”工作的决策部署，在不断深化学科类培训治理的同时，因地制宜同步推进非学科类培训规范工作，依托全国校外教育培训监管与服务综合平台，通过健全制度机制、强化安全管理、完善监管体系等举措，着力补短板、防风险、堵漏洞，稳步推进非学科类', 1, 255, 1, '2022-11-18 11:08:08', '2025-07-19 11:10:10', '2025-07-19 11:10:10');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('清华大学以“四个注重”持续加强卓越工程师培养', '<p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; text-align: center;">教育部简报〔2022〕第30期</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　清华大学认真学习贯彻习近平总书记关于教育的重要论述，牢记为党育人、为国育才初心使命，积极适应新一轮科技革命和产业变革新趋势，紧紧围绕国家重大战略和经济社会发展需求，以新工科建设为重要抓手，持续深化工程教育改革，探索构建中国特色、世界水平的工程师培养体系，不断提升工程技术人才培养质量和水平，努力为走好人才自主培养之路作出更大贡献。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">注重本研衔接，完善一体化贯通培养模式。</strong>按照“能力提升、系统优化、激发志趣、挑战创新”总体思路，完善本科培养方案，并合理设置研究生衔接课程、进阶课程。根据学生特点和志趣方向，为本博贯通培养学生设计“一人一策”培养方案。围绕优化知识结构，明确基础课程和专业核心课程要求，加强核心课程间的衔接融合，切实提高课程质量。深化工程教育改革，面向国家重大需求制定工程硕博士培养改革专项试点方案，加快工程领域“高精尖缺”高层次人才培养，先后推进建设30余个高水平工程类研究生培养项目。积极探索面向未来、以学生为主的特色书院制培养模式改革，制定《强基书院本博贯通培养实施办法》，以强基书院为试点，发掘培养更多有坚定学术志趣、具备创新潜质的学生，促进创新人才脱颖而出。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">注重学科交叉，健全融合型课程教学体系。</strong>探索“理—工”衔接的双学士学位培养模式，聚焦高端芯片与软件、智能科技、新材料、先进制造等重点领域，将数理基础知识与专业应用场景有机结合，着力培养具有深厚理科基础和核心专业素养的高水平工科人才。面向未来技术发展，构建“宽厚基础—工程实践—探索研究”融合培养体系，着力培养优秀技术创新人才。发挥学堂计划“钱学森力学班”工科拔尖创新人才培养的引领作用，推动10余个院系和研究中心打破学科壁垒，形成兼具“精深挑战”与“开放交叉”特色的核心课程体系。设立28个高水平工程类专业学位研究生培养项目，包括海洋技术与工程、智能装备设计与制造等14个工程类交叉项目，加快培养国家急需的工程领域高素质人才。设立创新领军工程博士培养项目，鼓励不同专业的师生相互交流学习，支持不同学科背景的工程博士研究生在合作研究中共同成长。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">　注重校企合作，构建全链条协同育人机制。</strong>校企合作加强课程建设，开设大数据、高端装备、人工智能、新一代信息与媒体技术等实践课程，由校企双方专家组共同完成课程设计、遴选重点任务、指导学生实践，并设置与行业专家、研发技术人员面对面交流等教学环节，为在校师生和企业研发骨干间搭建交流合作平台。充分利用校友及行业资源，邀请业界校友、专家参加相关课程建设，帮助学生了解产业发展与前沿热点，进一步提高学生实践创新能力和职业素养。构建产学研用互通互促机制，成立工程专业学位研究生教育中心和工程管理硕士教育中心，推进校企间、院系间育人资源共建共享。建立行业企业参与研究生培养的咨询指导机制，与行业领域重点单位开展研究生联合培养，进一步提升工程人才培养质量。与29家企业深度合作，面向关键核心技术领域开展工程硕士、博士培养改革专项招生试点，校企联合培养卓越工程技术人才。在集成电路、航空发动机等重点领域，与近50家企业签订合作协议，拓宽行业企业与学校的双向人才交流渠道，建成175个专业实践基地，加强研究生实践历练，不断提升发现真问题、解决大难题、定义新命题的实践创新能力，引导学生厚植爱国之情、砥砺强国之志、实践报国之行。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">注重交流互鉴，探索项目式国际合作方案。</strong>围绕服务“一带一路”建设，与相关企业合作开设“核电工程与管理国际人才培养”专业硕士学位项目，招收“一带一路”沿线国家学生。加强国际合作，与全球知名高校合作开设25个工程领域的硕士和博士学位项目。设置博士研究生培养基金，支持博士研究生赴世界一流高校和科研机构短期访学、合作研究。积极开展研究生海外实践项目，与18家企业共建研究生海外社会实践基地，累计派出200余名研究生前往20余个国家开展课题研究、项目攻关，参与服务蒙内铁路、亚吉铁路、淡布隆跨海大桥等多项国际重大工程项目的建设及运营，在实践中培养具有全球视野、紧跟产业发展的高层次工程技术人才。</p>', NULL, '本站', '教育部简报〔2022〕第30期清华大学认真学习贯彻习近平总书记关于教育的重要论述，牢记为党育人、为国育才初心使命，积极适应新一轮科技革命和产业变革新趋势，紧紧围绕国家重大战略和经济社会发展需求，以新工科建设为重要抓手，持续深化工程教育改革，探索构建中国特色、世界水平的工程师培养体系，不断提升工程技术人', 1, 255, 1, '2022-10-24 11:10:11', '2025-07-19 11:11:08', '2025-07-19 11:11:08');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('北京市以首善标准推进“双减”行动 ——2022年全国教育工作会议经验交流之十二', '<p style="text-align:center;font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">教育部简报〔2022〕第12期</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　北京市深入学习贯彻习近平总书记关于教育的重要论述，坚决落实党中央、国务院关于“双减”工作的决策部署，按照首善标准，坚持“治乱、减负、防风险”和“改革、转型、促提升”并重，着力促进教育发展理念更新、教育治理创新和教育生态重塑，努力推动教育高质量发展。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">　始终坚持高位推动。</strong>市委主要负责同志高度重视、直接推动，把“双减”工作作为“一把手工程”，主持召开市委常委会、市委书记专题会和市委教育工作领导小组会，多次到市教委及学校调研，与相关企业座谈，研究部署推动“双减”工作落实。成立市、区两级“双减”工作专班，强化统筹协调、分工协作、联合执法，坚持重点任务项目制推进，形成调度会商、挂图作战、每日报告工作机制，合力推进“双减”行动。严格检查督导，以“四不两直”“双随机、一公开”“24小时在线监测”等方式开展执法检查，对发现问题“双通报、双转办”。市教委班子成员、挂牌责任督学对义务教育学校开展全覆盖日常督导，周周检查、周周通报，实现检查督导常态化、问题整改及时化。选派200余名驻区、驻企联络员，发挥街道属地网格化管理和“吹哨报到”机制作用，不断强化日常监管。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">始终坚持创新施治。</strong>建立预付费资金监管机制，加强办学许可证管理，严格规范学科类校外培训机构办学行为。印发营利性培训机构全流程监管意见，构建“行业归口+行为监管”全过程监管闭环，制定防风险、“营转非”、“备改审”等10余个配套文件，以政策突破化解治理难题。引导各区充分发挥优势，努力调动各方积极性，创新开展“双减”基层实践。海淀区实现学科类校外培训机构视频监控全覆盖；朝阳区以党建指导员、教研员、督导员、巡查员、机关联络员等“五员”筑牢监管阵地；丰台区形成“专班+街镇+楼宇”“集中执法+科技监管+帮扶纾困”的无证机构综合治理模式。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">始终坚持整治乱象。</strong>坚持严查严管严治，公布学科类校外培训机构“白名单”，并动态调整建立校外培训机构管理平台，实现资金、学生、教师、课程、机构“五个管起来”，做到摸清底数、掌握实情。通报200余家机构，对多家违规企业严厉处罚。坚持严格审批备案，出台学科类校外培训机构监督管理办法，无证机构实现动态清零，“营转非”“备改审”工作全部完成，校外培训过多过滥、乱象丛生的局面逐步扭转。坚持治理帮扶并重，制定非学科类营利性培训机构准入工作衔接意见、学科类培训机构退租工作指导意见，引导企业向成人职业教育、综合素养等方向转型，提供22万余个岗位促进教培行业人员转岗再就业，防范化解涉稳风险。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">　始终坚持精准施策。</strong>聚焦校内提质增效，进一步规范教育教学秩序，编制作业指导手册，减轻学生作业负担。持续提高课后服务质量，引进优质教育资源进校园，全覆盖开展课后答疑辅导，学生自愿参与率达96%以上。出台《北京市义务教育体育与健康考核评价方案》，开展全学段试卷评估检查，深化教育评价改革。聚焦推进优质均衡，在东城、密云等8区推行校长教师交流轮岗试点，大力引导初中教师线上答疑辅导，推动优质师资均衡配置。推进“互联网+基础教育”，升级“空中课堂”，完成新一轮全学科全学段线上课程更新，在200余所学校建设“双师课堂”。召开中小学万人校长大会，开展“双减”大学习、大讨论、大调研活动，市教育工委、市教委班子成员深入全市所有区宣讲“双减”政策，8万余名干部教师参加。完善新闻发布机制，推进入户家访，积极主动回应社会关切，争取家长和社会的理解、支持和监督，凝聚“双减”工作合力。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">始终坚持稳妥落地。</strong>强化风险排查处置，建立每日分析、随时预警工作机制，落实“一址一案一专班”要求，加强对裁员、退费、舆情等风险的监测研判，有针对性落实应对处置措施，确保“双减”工作总体平稳。联合约谈分类化解，约谈450余人次，做到在京重点企业、重点风险机构全覆盖，坚持谈政策、谈出路、谈责任、谈措施，指导机构做好兑课、退费等工作。组织教委机关干部利用周末时间，积极回应学生家长退费、消课等诉求。切实保障群众利益，指导民办教育协会建立诉前调解中心、公益消课平台和法律服务机制。对拒不履约的机构，依法追究法律责任，对涉嫌违法的依法核查打击。</p>', NULL, '本站', '教育部简报〔2022〕第12期北京市深入学习贯彻习近平总书记关于教育的重要论述，坚决落实党中央、国务院关于“双减”工作的决策部署，按照首善标准，坚持“治乱、减负、防风险”和“改革、转型、促提升”并重，着力促进教育发展理念更新、教育治理创新和教育生态重塑，努力推动教育高质量发展。始终坚持高位推动。市', 1, 255, 1, '2022-04-08 11:11:10', '2025-07-19 11:12:21', '2025-07-19 11:12:21');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('北京林业大学以“五个强化”抓好毕业生就业创业工作', '<p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体; text-align: center;">教育部简报〔2021〕第64期</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　北京林业大学认真学习贯彻习近平总书记关于做好高校毕业生就业工作的重要指示批示精神，坚决落实党中央、国务院“稳就业”“保就业”决策部署，把毕业生就业工作摆在突出位置，以“五个强化”为着力点，不断健全就业创业促进机制，提高就业指导服务质量，努力促进毕业生更加充分更高质量就业。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">　强化组织领导，健全就业机制。</strong>落实就业工作“一把手”工程，成立党委书记和校长任组长的就业工作领导小组，学校党委常委会定期听取就业工作专题汇报，召开就业工作推进会，研究部署、督促指导做好毕业生就业工作。建立就业工作职能部门会商机制，招生就业处、研工部、学工部等相关部门协同配合、共同参与、扎实推进。各学院组织召开党政联席会、就业工作推进会等，结合学科专业特点，制定促进毕业生就业具体举措。设立院系就业专职辅导员，发动研究生导师、专业教师、班主任和辅导员等各方力量，将指导学生就业创业情况计入教师工作量，汇聚全员促就业的工作合力。将就业工作纳入学院年度考核、评奖评优指标体系，作为院党委书记、院长年度工作述职评议考核重点内容。探索建立“招生—培养—就业”联动机制，在专业评估基础上，坚持以需求为导向，有序调整专业招生规模，推动调结构、调规模、调资源配置的供给侧改革。不断健全以就业质量评价、就业工作评价、第三方评价为一体的考核评价体系，努力推动毕业生就业质量和就业工作质量“双提高”。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">强化价值引领，支持基层就业。</strong>将就业教育与思想政治教育有机融合，把就业观、成才观等教育纳入思政工作体系，引导学生立大志、明大德、成大才、担大任。实施“新生引航工程”，校党委书记、校长带头上好开学第一课；校领导担任学生公寓“楼长”，定期举办“相约午间”活动，与学生面对面深入交流，引导学生成长成才；举办“青马班”“树人学校”，组织学生参加“知国情、体民情、察林情”社会实践活动；连续37年组织开展“绿色长征”“生态文明博士生讲师团”等绿色环保实践活动，引导学生坚定理想信念，厚植爱国情怀。制定鼓励毕业生到基层就业办法，加大“西部计划”、参军入伍等宣传力度，举办基层就业主题宣传月，组织基层就业先进典型事迹报告会、基层就业毕业生欢送会等，挖掘毕业生基层就业典型，评选宣传“北林榜样”，引导毕业生积极投身生态文明建设，在建设美丽中国中实现人生梦想。近年来，学校共有8000余名毕业生到西部、到基层和林草行业就业；定向培养国防生800余名；参加“三支一扶”、应征入伍、进疆入藏毕业生近3000名，涌现出“全国脱贫攻坚先进个人”等一批基层工作先进典型。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">强化资源开发，拓宽就业渠道。</strong>积极与各级政府、行业主管部门等开展对接，先后与41个地方政府和林草主管部门签订校地合作协议；校领导带队走访人才部门，了解人才引进需求，有针对性推荐毕业生就业。协调校友企业、行业协会和社会招聘机构等，建立一批稳定的就业实习实践基地，多方挖掘就业岗位。充分发挥校园招聘主渠道作用，牵头涉林高校举办林草行业专场网络双选会，联合相关高校举办“农林行业专场线上招聘会”，2021年举办校园双选会10场、宣讲会304场，不断完善用人单位与学生“线上+线下”双向选择平台。用好教育部“24365校园招聘服务”平台等资源，组织毕业生积极参加教育部、北京市以及相关专业机构举办的各类招聘活动。安排专人每日收集整理招聘信息，根据学科专业、就业意向、就业状态等，通过网络平台、微信群等精准推送至毕业生，有效提升人岗匹配精确度。每年推送就业资讯11.5万余条，实现毕业生全覆盖。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">强化指导服务，提升就业质量。</strong>深化职业生涯规划和就业指导课程改革，构建“通识+专业”职业生涯课程体系和“模块化”就业指导课程体系，实行内容统一研发、教师统一培训、课程统一安排、师资统一调配，夯实学生就业能力基础。职业生涯规划课每年开设206个班，覆盖学生3万余人次。建立职业生涯发展工作室，聘请90余名行业专家、优秀校友等担任职业生涯发展导师，为学生提供“一对一”指导，帮助解决毕业生就业困惑和难题。搭建校友咨询互动平台，学生可在线查询往届校友毕业去向，向校友咨询请教。丰富就业指导内容，举办“就业指导月”和“职业生涯规划月”系列活动，组织生涯体验周、研招咨询会，举办就业政策解读、简历制作、面试指导、求职礼仪、升学留学等团体辅导活动200余场，服务学生6600余人次。构建以学生为中心的“就业+”信息管理平台，采集学生生涯成长数据，建立学生“成长档案”，为就业创业指导提供数据支撑；与第三方机构数据对接，辅助做好来校招聘企业信息核实，确保岗位资讯真实有效，保障毕业生求职安全；推进就业手续“最多跑一次”改革，实现就业材料申请、派遣、改派等业务全程网上办理、限时办结，不断提升就业服务质量。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">强化重点帮扶，彰显就业温度。</strong>建立重点群体毕业生电子台账，动态掌握家庭经济困难学生、少数民族学生等重点群体就业情况。落实“一生一策”，学校及院系领导班子带头，党员干部、教师积极担任“一对一”就业帮扶导师，深入开展“两个不少于”工作，即与每名毕业生不少于两次谈心谈话、不少于两次就业工作推荐。加强分类帮扶，针对家庭经济困难学生，发放求职创业补贴和专项补助；针对学业困难学生，优化学业预警制度；针对就业困难学生，开展简历制作、求职面试技巧培训等，全力保障重点群体毕业生尽快就业、顺利就业。</p>', NULL, '本站', '教育部简报〔2021〕第64期北京林业大学认真学习贯彻习近平总书记关于做好高校毕业生就业工作的重要指示批示精神，坚决落实党中央、国务院“稳就业”“保就业”决策部署，把毕业生就业工作摆在突出位置，以“五个强化”为着力点，不断健全就业创业促进机制，提高就业指导服务质量，努力促进毕业生更加充分更高质量就业。', 1, 255, 1, '2022-01-27 11:06:04', '2025-07-19 11:08:06', '2025-07-19 11:08:06');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('河北省石家庄市探索“家、校、社”协同推进劳动教育新路径', '<p style="text-align:center;font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">教育部简报〔2021〕第25期</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　河北省石家庄市认真学习贯彻习近平总书记关于教育的重要论述和全国教育大会精神，把劳动教育纳入人才培养全过程，调动家庭、学校、社会各方面，逐步探索“2+4+4+5”劳动教育新路径，着力构建课上课下相结合、校内校外相贯通、家庭社会全参与的劳动教育新局面，努力培养德智体美劳全面发展的社会主义建设者和接班人。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">开发双向立体劳动课程，构建劳动教育新体系。</strong>一是建立“必修+渗透+校本”横向课程体系。落实劳动教育必修课，全市共配备1.5万余名专兼职劳动教育教师，每所学校至少配备1名劳动教育专任教师。组织各学科开发“劳动+”系列课程，如语文课学习赞美劳动者的文章，数学课通过应用题计算解答劳动中经常遇到的实际问题，音乐课欣赏《劳动号子》《船夫曲》，学唱《劳动最光荣》，美术课学习劳动绘画、制作手工作品等。鼓励学校研发涵盖家务、手工、园艺等内容的校本课程，共同打造劳动教育“金课”。二是建立“萌芽+成长+绽放”纵向课程体系。即以劳动品德教育为基础的“萌芽”课程、以劳动习惯养成为目标的“成长”课程、以职业生涯规划为导向的“绽放”课程，通过古诗词欣赏、先进事迹观影、家长职业讲座、公益性服务劳动、职业体验课程等，引导学生树立正确的劳动观念，增强劳动意识。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">建设校园内外四个阵地，拓展劳动教育新空间。</strong>一是建好校园劳动教育场所。建立“市—县—校”三级推进机制，近两年累计投入1600余万元，按照“种植园+实验室+生活馆”的思路，对校园进行整体规划设计，充分利用食堂、实验室以及天台闲置空地等现有资源，建立手工缝纫、物创空间、农耕实践等校内劳动教育实践场所。在全市确定首批劳动教育特色学校20所，通过劳动教育现场会、劳动教育特色学校巡礼活动等，推动每县重点打造1—2所实验学校，每校打造1—2个劳动教育特色品牌。二是打造综合劳动实践中心。充分发挥市青少年社会综合实践学校作用，设置涵盖生产性劳动、服务性劳动、艺术创造性劳动、研究性劳动和合作性探究等六大主题的62门劳动实践课程，开设STEAM体验馆、机器人体验馆、纳米技术应用体验馆等，已累计接待学生10万余人次。开发红色、农业、工业、科技和生态等5条劳动实践精品线路，引导学生走进工厂车间，学习简单工具的使用；走进田间农场，学习种植、养殖基本知识，参加农业劳作；走进酒店、商场，学当导购员、服务员、分装员；走访民间艺人，学习制作宫灯、编中国结、剪纸、扎风筝等，感受中华优秀传统文化魅力。三是重塑家庭劳动教育阵地。制定《大中小学劳动教育指南》，针对不同学段学生，从卫生清扫、内务整理、食品加工、垃圾分类、种植养护、电器使用等方面推荐不同的家务劳动内容，以家庭劳动作业的形式引导学生在家庭中寻找服务“小岗位”，培养一批“劳动小达人”。开设石家庄家长学校微信公众号，定期推送“劳动微课堂”，引导家长通过言传身教，在潜移默化中让孩子从小养成热爱劳动的好习惯。四是开辟校外劳动教育基地。携手产业园区等，建立“农业+”“工业+”“科技+”“生态+”等劳动实践项目25个，打造一批集学工、学农及生活技能、传统文化传承于一体的校外实践基地。统筹协调全市各级各类职业院校劳动实训基地资源，通过普职联动构建劳动教育共同体，指导职业院校联合中小学开展劳动和职业启蒙教育。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">打造线上线下四级平台，丰富劳动教育新载体。</strong>一是组建智库平台。成立由各级劳动教育教研员和能工巧匠等组成的劳动教育专家委员会，建立由教育行政部门、学校、教研机构等组成的区域劳动教育联盟，组织开展劳动教育交流研讨。二是研发“石家庄市劳动实践”线上平台。通过平台展示全市校外劳动实践场所地理位置分布、各场所介绍和特色课程，同时实现对校外劳动实践场所的动态管理。三是建立评价平台。针对小学、初中、高中三个学段学生特点，探索实行以教师评价为主，家长、劳动实践单位评价为辅的评价机制，对学生劳动目的、劳动过程、劳动结果进行全过程纪实评价，并将学生参与劳动情况记入学生综合素质档案。四是搭建展示平台。面向全市中小学生举办劳动技能竞赛，设置技能类、烹饪类、生活类和农耕类等四类26个竞赛项目，根据学生劳动过程、劳动态度、劳动成果等，客观评价不同学段学生的劳动过程和结果，进一步激发学生劳动潜能、增强学生劳动技能。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">紧扣“两日三节”重要节点，形成劳动教育新常态。</strong>一是组织好“3•5”学雷锋纪念日、“12•5”国际志愿者日活动。开展学雷锋志愿服务月，举行“传承雷锋精神共建文明校园”“弘扬雷锋精神彰显志愿风采”“学雷锋争做最美少年”等主题活动，引导学生走进石家庄（正定）国际博览会、市老年养护院等开展志愿服务。启动小手拉大手共护校容校貌、村容村貌、户容户貌行动，选树学雷锋先进个人、先进班集体等典型，弘扬劳动光荣、创造伟大的主旋律。二是抓住“3•15”植树节、“五一”国际劳动节、中国农民丰收节等具有劳动意义的节日推进劳动教育。开展劳动周、劳动月系列活动，引导学校构建“春种夏长秋收冬藏”劳动教育活动体系，以“四季”为主线开展劳动教育活动，引导学生感受劳动艰辛、体会丰收喜悦；开展“我为大地添新绿”活动，引导学生挥锹挖土、种植春树；开展“童年里的二十四节气”系列活动，通过立春炸春卷、谷雨种瓜点豆、小满挖野菜等趣味活动，引导学生学习节气、因时而作；启动“童心向党 传承国粹”劳动教育月暨中草药文化教育周活动，建立“百草园”劳动教育基地，举行中草药故事分享会，让学生了解中医药文化、学习中医保健常识，在劳动中学习知识、体验乐趣。</p>', NULL, '本站', '教育部简报〔2021〕第25期河北省石家庄市认真学习贯彻习近平总书记关于教育的重要论述和全国教育大会精神，把劳动教育纳入人才培养全过程，调动家庭、学校、社会各方面，逐步探索“2+4+4+5”劳动教育新路径，着力构建课上课下相结合、校内校外相贯通、家庭社会全参与的劳动教育新局面，努力培养德智体美劳全面发展的社会', 1, 255, 1, '2021-12-03 11:02:16', '2025-07-19 11:04:10', '2025-07-19 11:04:10');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('河北省石家庄市探索“家、校、社”协同推进劳动教育新路径', '<p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">河北省石家庄市认真学习贯彻习近平总书记关于教育的重要论述和全国教育大会精神，把劳动教育纳入人才培养全过程，调动家庭、学校、社会各方面，逐步探索“2+4+4+5”劳动教育新路径，着力构建课上课下相结合、校内校外相贯通、家庭社会全参与的劳动教育新局面，努力培养德智体美劳全面发展的社会主义建设者和接班人。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">开发双向立体劳动课程，构建劳动教育新体系。</strong>一是建立“必修+渗透+校本”横向课程体系。落实劳动教育必修课，全市共配备1.5万余名专兼职劳动教育教师，每所学校至少配备1名劳动教育专任教师。组织各学科开发“劳动+”系列课程，如语文课学习赞美劳动者的文章，数学课通过应用题计算解答劳动中经常遇到的实际问题，音乐课欣赏《劳动号子》《船夫曲》，学唱《劳动最光荣》，美术课学习劳动绘画、制作手工作品等。鼓励学校研发涵盖家务、手工、园艺等内容的校本课程，共同打造劳动教育“金课”。二是建立“萌芽+成长+绽放”纵向课程体系。即以劳动品德教育为基础的“萌芽”课程、以劳动习惯养成为目标的“成长”课程、以职业生涯规划为导向的“绽放”课程，通过古诗词欣赏、先进事迹观影、家长职业讲座、公益性服务劳动、职业体验课程等，引导学生树立正确的劳动观念，增强劳动意识。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">建设校园内外四个阵地，拓展劳动教育新空间。</strong>一是建好校园劳动教育场所。建立“市—县—校”三级推进机制，近两年累计投入1600余万元，按照“种植园+实验室+生活馆”的思路，对校园进行整体规划设计，充分利用食堂、实验室以及天台闲置空地等现有资源，建立手工缝纫、物创空间、农耕实践等校内劳动教育实践场所。在全市确定首批劳动教育特色学校20所，通过劳动教育现场会、劳动教育特色学校巡礼活动等，推动每县重点打造1—2所实验学校，每校打造1—2个劳动教育特色品牌。二是打造综合劳动实践中心。充分发挥市青少年社会综合实践学校作用，设置涵盖生产性劳动、服务性劳动、艺术创造性劳动、研究性劳动和合作性探究等六大主题的62门劳动实践课程，开设STEAM体验馆、机器人体验馆、纳米技术应用体验馆等，已累计接待学生10万余人次。开发红色、农业、工业、科技和生态等5条劳动实践精品线路，引导学生走进工厂车间，学习简单工具的使用；走进田间农场，学习种植、养殖基本知识，参加农业劳作；走进酒店、商场，学当导购员、服务员、分装员；走访民间艺人，学习制作宫灯、编中国结、剪纸、扎风筝等，感受中华优秀传统文化魅力。三是重塑家庭劳动教育阵地。制定《大中小学劳动教育指南》，针对不同学段学生，从卫生清扫、内务整理、食品加工、垃圾分类、种植养护、电器使用等方面推荐不同的家务劳动内容，以家庭劳动作业的形式引导学生在家庭中寻找服务“小岗位”，培养一批“劳动小达人”。开设石家庄家长学校微信公众号，定期推送“劳动微课堂”，引导家长通过言传身教，在潜移默化中让孩子从小养成热爱劳动的好习惯。四是开辟校外劳动教育基地。携手产业园区等，建立“农业+”“工业+”“科技+”“生态+”等劳动实践项目25个，打造一批集学工、学农及生活技能、传统文化传承于一体的校外实践基地。统筹协调全市各级各类职业院校劳动实训基地资源，通过普职联动构建劳动教育共同体，指导职业院校联合中小学开展劳动和职业启蒙教育。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">打造线上线下四级平台，丰富劳动教育新载体。</strong>一是组建智库平台。成立由各级劳动教育教研员和能工巧匠等组成的劳动教育专家委员会，建立由教育行政部门、学校、教研机构等组成的区域劳动教育联盟，组织开展劳动教育交流研讨。二是研发“石家庄市劳动实践”线上平台。通过平台展示全市校外劳动实践场所地理位置分布、各场所介绍和特色课程，同时实现对校外劳动实践场所的动态管理。三是建立评价平台。针对小学、初中、高中三个学段学生特点，探索实行以教师评价为主，家长、劳动实践单位评价为辅的评价机制，对学生劳动目的、劳动过程、劳动结果进行全过程纪实评价，并将学生参与劳动情况记入学生综合素质档案。四是搭建展示平台。面向全市中小学生举办劳动技能竞赛，设置技能类、烹饪类、生活类和农耕类等四类26个竞赛项目，根据学生劳动过程、劳动态度、劳动成果等，客观评价不同学段学生的劳动过程和结果，进一步激发学生劳动潜能、增强学生劳动技能。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">紧扣“两日三节”重要节点，形成劳动教育新常态。</strong>一是组织好“3•5”学雷锋纪念日、“12•5”国际志愿者日活动。开展学雷锋志愿服务月，举行“传承雷锋精神共建文明校园”“弘扬雷锋精神彰显志愿风采”“学雷锋争做最美少年”等主题活动，引导学生走进石家庄（正定）国际博览会、市老年养护院等开展志愿服务。启动小手拉大手共护校容校貌、村容村貌、户容户貌行动，选树学雷锋先进个人、先进班集体等典型，弘扬劳动光荣、创造伟大的主旋律。二是抓住“3•15”植树节、“五一”国际劳动节、中国农民丰收节等具有劳动意义的节日推进劳动教育。开展劳动周、劳动月系列活动，引导学校构建“春种夏长秋收冬藏”劳动教育活动体系，以“四季”为主线开展劳动教育活动，引导学生感受劳动艰辛、体会丰收喜悦；开展“我为大地添新绿”活动，引导学生挥锹挖土、种植春树；开展“童年里的二十四节气”系列活动，通过立春炸春卷、谷雨种瓜点豆、小满挖野菜等趣味活动，引导学生学习节气、因时而作；启动“童心向党 传承国粹”劳动教育月暨中草药文化教育周活动，建立“百草园”劳动教育基地，举行中草药故事分享会，让学生了解中医药文化、学习中医保健常识，在劳动中学习知识、体验乐趣。</p>', NULL, '本站', '河北省石家庄市认真学习贯彻习近平总书记关于教育的重要论述和全国教育大会精神，把劳动教育纳入人才培养全过程，调动家庭、学校、社会各方面，逐步探索“2+4+4+5”劳动教育新路径，着力构建课上课下相结合、校内校外相贯通、家庭社会全参与的劳动教育新局面，努力培养德智体美劳全面发展的社会主义建设者和接班人。开发', 1, 255, 1, '2021-12-03 10:52:44', '2025-07-19 10:58:11', '2025-07-19 10:59:00');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('甘肃省着力办好契合地区特色的现代职业教育 ——贯彻落实全国职教大会精神系列之四', '<p style="text-align:center;font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">教育部简报〔2021〕第13期</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　甘肃省深入贯彻落实习近平总书记视察甘肃重要讲话和指示精神，把大力发展职业教育作为促进教育质量全面提升、助推城镇化建设、服务“绿色崛起”、巩固脱贫攻坚成果与乡村振兴有效衔接的重要支撑，抢抓打造“技能甘肃”的历史机遇，系统谋划部署，努力推动职业教育迈入提质培优、增值赋能的高质量发展新阶段。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">着力优化发展生态。</strong>加大制度创新，把制度创新作为推动职业教育发展的主要驱动力。省委省政府坚持下好职业教育改革发展的“先手棋”，主要负责同志定期研究重大事项、协调解决重点难点问题，积极为职业教育发展创造条件。在省、市、州各级成立“技能甘肃”工作领导小组，建立职业教育联席会议制度，定期研究解决推进实施中的问题。各级党委政府把职业教育发展纳入经济社会发展大局和教育工作全局，统筹谋划。加大政策供给，先后出台《甘肃省现代职业教育体系建设规划（2014—2020年）》《甘肃省职业教育改革实施方案》《甘肃省职业教育助推绿色生态产业发展实施方案》等文件，初步构建了支持和推动职业教育高质量发展的政策体系，为职业教育创新发展提供坚实保障。加大投入力度，促进职业教育持续健康发展。每年投入专项经费1.5亿元，支持高水平高职学校和优质中等职业学校高质量发展。设立中职改善办学条件专项资金，将中职学校办学能力提升作为厅长突破项目，持续加强中职学校的办学水平。2021年计划投入技能提升行动专账资金8亿元，实现职业技能培训37万人次，全力推进职业技能提升落地见效。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">着力推进深化改革。</strong>推动职业院校分类考试招生制度改革，形成更加符合职业教育类型特征和规律的人才选拔模式。普通高中毕业生采取综合评价录取或统一高考录取方式，中职学校学生实行“文化素质+职业技能”录取方式，配套实施五年一贯制“中高职贯通”招生和中职升学考试招生制度，打通中高本衔接培养通道。2020年全省中职计划招生完成率达129%，高职院校招生总计划完成率达116%。深化职教领域“放管服”改革，推动由注重“办”职业教育向“管理与服务”过渡。建立“陇原人才服务卡”制度，从户籍办理、子女入学、配偶安置等9个方面，为各类高层次人才制定务实管用的服务保障措施，切实解决高层次人才的后顾之忧，营造尊重知识、尊重人才的良好氛围，吸引高层次人才扎根甘肃、服务甘肃。施行职业院校教师队伍用工总量管理，建立动态调整机制，支持校企互聘、双向流动。深化职业院校人才薪酬待遇改革，将绩效工资分配权限和总量审核权限下放至各职业院校，单列引进高层次人才绩效工资，拓宽收入渠道并允许兼职取酬，提高职业院校教师队伍创新创业的积极性。开通特殊人才职称评价“绿色通道”，对符合条件的特殊人才对象，按照“一人一事、一事一议、特事特办”的模式，打破技能人才职称评聘“天花板”，推动一批产业工人破格晋升正高级工程师职称。畅通企业高层次技术技能人才从教渠道，深入实施“陇原巨匠”培育工程，培育一批有“绝活”、善育人的“双师型”教师。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">着力深化产教融合。</strong>积极探索产业、行业、企业、职业、专业融合发展模式，促进教育链、产业链、创新链、人才链有效衔接融合。打造陇中职业教育集群，重点加强石油化工、有色冶金、现代制造等专业建设，助力西陇海兰新经济带建设；打造河西走廊职业教育集群，重点加强生态保护、清洁能源、戈壁农业等专业建设，支撑河西内陆河流域生态屏障构建，助力祁连山生态环境修复和涵养；打造陇东南职业教育集群，着力加强现代制造、电子商务、文化旅游等专业建设，助力提升陇东南经济增长带核心竞争力。推进职教集团建设，建成电子商务、石油化工、军民融合等29个省级行业型职教集团，3家单位入围国家第一批示范性职业教育集团（联盟）培育单位名单。启动省级产教融合型试点企业培育建设工程，健全产教融合激励机制，遴选甘肃省首批产教融合型企业建设培育单位40家，支持社会力量兴办职业教育，全面提升职业教育助推经济、改善民生的支撑能力。发挥职教园区示范作用，高起点、高质量、高标准打造兰州新区职教园区，累计投入资金186亿元，将24所中职学校整合为4所高职院校，10所高校及职业院校约15万师生入驻园区。按照“一会两院多平台”的建设思路，组建兰州新区职教园区校企合作理事会，筹建培训学院和中德学院，组建产教融合中心、智能制造中心、创业孵化中心、行业服务中心等多个服务园区职业院校的经营实体平台，优化运行机制，盘活公共实训资源，将职教园区打造为全省产教融合的示范区。</p><p style="font-size: 16px; white-space: normal; margin-top: 0px; margin-bottom: 0px; padding: 16px 0px; border: 0px; overflow: hidden; caret-color: rgb(75, 75, 75); color: rgb(75, 75, 75); font-family: 微软雅黑, Arial, 宋体;">　　<strong style="margin: 0px; padding: 0px; border: 0px; overflow: hidden;">着力促进提质赋能。</strong>扩容优质资源，实施高水平高等职业学校和专业群建设计划、优质中等职业学校建设计划，集中力量建设19所高水平高职学校、33所优质中职学校，显著提升职业院校的核心竞争力。其中，23所中职学校获批国家中等职业教育改革发展示范学校，3所高职院校入选国家高水平高职学校和专业建设计划建设单位名单，6所院校分别入选全国职业院校“教学管理50强”“实习管理50强”和“学生管理50强”。完善职业教育办学层级结构，贯通职业学校体系，推动应用型本科高校转型发展，组建2所职业技术大学，3所独立院校转设为民办本科院校。赋能脱贫攻坚，构建职业教育“技能扶贫”模式，紧盯职业教育助推脱贫攻坚目标任务，每年面向农村招收近10万名初高中毕业生免费接受职业教育，每年培养“两后生”6万人、培训新型职业农民1.6万人次。</p>', NULL, '本站', '教育部简报〔2021〕第13期甘肃省深入贯彻落实习近平总书记视察甘肃重要讲话和指示精神，把大力发展职业教育作为促进教育质量全面提升、助推城镇化建设、服务“绿色崛起”、巩固脱贫攻坚成果与乡村振兴有效衔接的重要支撑，抢抓打造“技能甘肃”的历史机遇，系统谋划部署，努力推动职业教育迈入提质培优、增值赋能的高质', 1, 255, 1, '2021-08-27 11:04:12', '2025-07-19 11:06:03', '2025-07-19 11:06:03');

-- 重大活动 -> news (8 rows)
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('金砖国家职业教育联盟正式成立', '<p id="1uRn7kcQBp3VMMXF" style="-webkit-tap-highlight-color: rgba(255, 255, 255, 0); margin-top: 0px; margin-bottom: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; color: rgb(102, 102, 102); font-family: &quot;Microsoft Yahei&quot;, Arial, Helvetica, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">为落实习近平主席在金砖国家领导人第十三次会晤上提出的建立金砖国家职业教育联盟的倡议，4月27日，由中国教育部主办的金砖国家职业教育联盟大会在北京以线上线下相结合形式召开。金砖五国职业教育主管部门、驻华使节、行业组织、职业院校和企业代表共百余人出席会议，共同见证金砖国家职业教育联盟正式成立。</p><p id="1uRn7kcQBp3VMMXF" style="-webkit-tap-highlight-color: rgba(255, 255, 255, 0); margin-top: 0px; margin-bottom: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; color: rgb(102, 102, 102); font-family: &quot;Microsoft Yahei&quot;, Arial, Helvetica, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p id="fgvhvUkGIph7sj5o" style="-webkit-tap-highlight-color: rgba(255, 255, 255, 0); margin-top: 0px; margin-bottom: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; color: rgb(102, 102, 102); font-family: &quot;Microsoft Yahei&quot;, Arial, Helvetica, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">中国教育部副部长田学军发表视频致辞。田学军指出，在五国的共同努力下，金砖国家职业教育联盟正式成立，这对于促进五国职业教育改革发展、打造对话和信息平台、推动职业教育合作走深走实具有重要意义，将为共同应对教育领域挑战、助推各国经济转型和产业升级、共创全球发展新时代作出积极贡献。</p><p id="fgvhvUkGIph7sj5o" style="-webkit-tap-highlight-color: rgba(255, 255, 255, 0); margin-top: 0px; margin-bottom: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; color: rgb(102, 102, 102); font-family: &quot;Microsoft Yahei&quot;, Arial, Helvetica, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p id="cjHLTWrQMQrRNmm3" style="-webkit-tap-highlight-color: rgba(255, 255, 255, 0); margin-top: 0px; margin-bottom: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; color: rgb(102, 102, 102); font-family: &quot;Microsoft Yahei&quot;, Arial, Helvetica, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">田学军对联盟未来发展提出三点建议：一是五国共同参与，确保取得实效，联盟建设应秉持开放合作理念，充分发挥每个国家、每个成员的积极性。二是深化产教融合，不断增强职业教育适应性，培养更多适应经济社会发展需求的高素质人才。三是创新发展途径，利用现代技术加快技能人才培养模式改革，加大绿色技术和数字化赋能推广力度。</p><p id="cjHLTWrQMQrRNmm3" style="-webkit-tap-highlight-color: rgba(255, 255, 255, 0); margin-top: 0px; margin-bottom: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; color: rgb(102, 102, 102); font-family: &quot;Microsoft Yahei&quot;, Arial, Helvetica, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p id="8CsdzVvOUABpYGyV" style="-webkit-tap-highlight-color: rgba(255, 255, 255, 0); margin-top: 0px; margin-bottom: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; color: rgb(102, 102, 102); font-family: &quot;Microsoft Yahei&quot;, Arial, Helvetica, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">金砖五国职业教育主管部门充分肯定并积极支持联盟成立。巴西教育部长戈多伊、俄罗斯教育部副部长布加耶夫、印度技能发展与创业部国务部长钱德拉塞卡和南非高等教育与科创部部长恩齐曼迪分别以视频或贺信形式致辞。部长们表示将鼓励支持本国成员单位积极参与金砖国家职业教育联盟建设，推动联盟开展务实合作。</p><p id="8CsdzVvOUABpYGyV" style="-webkit-tap-highlight-color: rgba(255, 255, 255, 0); margin-top: 0px; margin-bottom: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; color: rgb(102, 102, 102); font-family: &quot;Microsoft Yahei&quot;, Arial, Helvetica, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p id="uC51Xeb94RaA941y" style="-webkit-tap-highlight-color: rgba(255, 255, 255, 0); margin-top: 0px; margin-bottom: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; color: rgb(102, 102, 102); font-family: &quot;Microsoft Yahei&quot;, Arial, Helvetica, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">在金砖五国职业教育主管部门支持和指导下，金砖国家职业教育联盟由各国行业组织、职业院校、研究机构和企业等组成，五国发起成员单位共68家。</p>', NULL, '本站', '为落实习近平主席在金砖国家领导人第十三次会晤上提出的建立金砖国家职业教育联盟的倡议，4月27日，由中国教育部主办的金砖国家职业教育联盟大会在北京以线上线下相结合形式召开。金砖五国职业教育主管部门、驻华使节、行业组织、职业院校和企业代表共百余人出席会议，共同见证金砖国家职业教育联盟正式成立。中国教育部副部', 1, 255, 2, '2025-07-17 21:47:38', '2025-07-17 21:49:47', '2025-07-17 21:49:47');
INSERT INTO `news` (`title`, `content`, `cover_url`, `source`, `summary`, `status`, `sort`, `type`, `publish_time`, `create_time`, `update_time`) VALUES ('人社部、工信部、国资委启动实施制造业技能根基工程', '<p style="-webkit-tap-highlight-color: rgba(255, 255, 255, 0); margin-top: 0px; margin-bottom: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; color: rgb(102, 102, 102); font-family: &quot;Microsoft Yahei&quot;, Arial, Helvetica, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">日前，人力资源社会保障部、工业和信息化部、国务院国资委联合印发《制造业技能根基工程实施方案》（以下简称《方案》），指导各地加快培养制造业高质量发展急需的高素质技能人才。</p><p style="-webkit-tap-highlight-color: rgba(255, 255, 255, 0); margin-top: 0px; margin-bottom: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; color: rgb(102, 102, 102); font-family: &quot;Microsoft Yahei&quot;, Arial, Helvetica, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="-webkit-tap-highlight-color: rgba(255, 255, 255, 0); margin-top: 0px; margin-bottom: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; color: rgb(102, 102, 102); font-family: &quot;Microsoft Yahei&quot;, Arial, Helvetica, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">《方案》提出，2022年至2025年，聚焦制造业重点领域，建立国家技能根基工程培训基地，加大急需紧缺职业工种政府补贴培训支持力度，推进技能人才培养评价工作，优化使用发展环境和激励机制配套支撑，打造数量充足、结构合理、素质优良、充满活力的制造业技能人才队伍。</p><p style="-webkit-tap-highlight-color: rgba(255, 255, 255, 0); margin-top: 0px; margin-bottom: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; color: rgb(102, 102, 102); font-family: &quot;Microsoft Yahei&quot;, Arial, Helvetica, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);"><br/></p><p style="-webkit-tap-highlight-color: rgba(255, 255, 255, 0); margin-top: 0px; margin-bottom: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: rgb(229, 231, 235); --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; color: rgb(102, 102, 102); font-family: &quot;Microsoft Yahei&quot;, Arial, Helvetica, sans-serif; text-align: justify; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);">《方案》明确六项重点任务。<span style="-webkit-tap-highlight-color: ; margin: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: #E5E7EB; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; font-weight: bolder;">一是</span>遴选建设国家技能根基工程培训基地，重点开展高技能人才特别是技师、高级技师、特级技师、首席技师培训研修，促进制造业技术迭代和质量升级。<span style="-webkit-tap-highlight-color: ; margin: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: #E5E7EB; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; font-weight: bolder;">二是</span>制定制造业政府补贴职业技能培训目录，突出“高精尖缺”导向，适当提高补贴标准。<span style="-webkit-tap-highlight-color: ; margin: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: #E5E7EB; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; font-weight: bolder;">三是</span>在制造业企业全面推行中国特色企业新型学徒制，通过名师带高徒、师徒结对子、建立技能大师工作室等形式，培养高质量企业新型学徒。<span style="-webkit-tap-highlight-color: ; margin: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: #E5E7EB; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; font-weight: bolder;">四是</span>加强制造业高技能领军人才选拔评聘，推动符合条件的规模以上制造业企业全部备案纳入培训评价机构目录，对高技能领军人才聘任、评选表彰等予以优先支持。<span style="-webkit-tap-highlight-color: ; margin: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: #E5E7EB; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; font-weight: bolder;">五是</span>全面推进制造业工学一体化技能人才培养模式，大力建设先进制造业等产业需要的新兴专业和优质专业，开发优质教学资源包，加强一体化教材和培训资源建设。<span style="-webkit-tap-highlight-color: ; margin: 0px; box-sizing: border-box; border-width: 0px; border-style: solid; border-color: #E5E7EB; --tw-translate-x: 0; --tw-translate-y: 0; --tw-rotate: 0; --tw-skew-x: 0; --tw-skew-y: 0; --tw-scale-x: 1; --tw-scale-y: 1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness: proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width: 0px; --tw-ring-offset-color: #fff; --tw-ring-color: rgb(59 130 246 / 0.5); --tw-ring-offset-shadow: 0 0 #0000; --tw-ring-shadow: 0 0 #0000; --tw-shadow: 0 0 #0000; --tw-shadow-colored: 0 0 #0000; --tw-blur: ; --tw-brightness: ; --tw-contrast: ; --tw-grayscale: ; --tw-hue-rotate: ; --tw-invert: ; --tw-saturate: ; --tw-sepia: ; --tw-drop-shadow: ; --tw-backdrop-blur: ; --tw-backdrop-brightness: ; --tw-backdrop-contrast: ; --tw-backdrop-grayscale: ; --tw-backdrop-hue-rotate: ; --tw-backdrop-invert: ; --tw-backdrop-opacity: ; --tw-backdrop-saturate: ; --tw-backdrop-sepia: ; padding: 0px; font-weight: bolder;">六是</span>大力开展制造业品牌职业技能竞赛，聚焦人工智能、工业机器人、机械制造、新能源汽车等重点领域职业工种，促进更多优秀高技能人才脱颖而出。</p>', NULL, '本站', '日前，人力资源社会保障部、工业和信息化部、国务院国资委联合印发《制造业技能根基工程实施方案》（以下简称《方案》），指导各地加快培养制造业高质量发展急需的高素质技能人才。《方案》提出，2022年至2025年，聚焦制造业重点领域，建立国家技能根基工程培训基地，加大急需紧缺职业工种政府补贴培训支持力度，推进技能人', 1, 255, 2, '2025-07-12 21:49:49', '2025-07-17 21:50:19', '2025-07-17 21:50:19');
